INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-I2-1', 1, 'invariant', 'local', NULL, NULL, 'The session owns accepted in-memory messages and one `RunId`.', 'c28545ec0a6f85c7a2a91cbbeccb73c892f49d65497f6916534dd02713dae256', 'active', NULL, 181);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-I2-2', 1, 'invariant', 'local', NULL, NULL, 'A run captures model ID, tool catalog generation, instructions and limits.', '5c257b4fad7d0956d3406c3f7e4a468aab779a0a13c41d18d59ae2997a37fb2f', 'active', NULL, 182);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-I2-3', 1, 'invariant', 'interaction', NULL, NULL, 'No model or catalog change mid-run.', 'e183d544a41fb79284afab8fdf5bd090aa8fc4835a7809877097c6de574b137e', 'active', NULL, 183);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-I2-4', 1, 'invariant', 'interaction', NULL, NULL, 'New Session or model change happens only at idle and invalidates every old handle.', '6f7dfd361c772935d41233a723b864ef2c57444c6b9224cd6afabb3cf670ae4c', 'active', NULL, 184);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-I3-1', 1, 'invariant', 'interaction', NULL, NULL, 'Provider request attempts do not execute tools.', 'e22040985ab8419bea51ceaafeb8ffa4ceeaa289d8142d2c427599653e3f71be', 'active', NULL, 185);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-I3-2', 1, 'invariant', 'interaction', NULL, NULL, 'Only a terminal validated response creates a batch.', '254dcd05767ca10ec3572fbf482cea7a0ad0d76b694e0c31bd44e6e6e5bf82a7', 'active', NULL, 186);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-I3-3', 1, 'invariant', 'interaction', NULL, NULL, 'Each invocation has one local CallId and one terminal outcome.', 'b0ee13525d6859382951cdcded3dbff3004aedc0abcc2440ef07373eb2fc529e', 'active', NULL, 187);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-I3-4', 1, 'invariant', 'interaction', NULL, NULL, 'The harness never retries an executed call. Retrying the next provider request with prior results does not replay effects.', '555797a189eff07a004a238fbaf891d1454f939c9b8d0de9e80b717387836847', 'active', NULL, 188);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-I4-1', 1, 'invariant', 'interaction', NULL, NULL, 'Each accepted tool call gets exactly one result before the next provider request.', 'b14927371561fbde451748fe0a186546db19f2f534b220a15d6e632ea6004007', 'active', NULL, 189);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-I4-2', 1, 'outcome', 'interaction', 'stop with calls not started', 'CANCELLED_NOT_STARTED', 'Stop records `CANCELLED_NOT_STARTED` for remaining calls.', '41cb26bc6f7896c08a731c36659bf7f40f2ff48f030637ecbd211b318f089c4a', 'active', NULL, 190);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-I4-3', 1, 'outcome', 'interaction', 'stop with a started effect', 'real terminal outcome', 'An already-started effect reports its real terminal outcome.', '342320caff0d11dc3c0b049d709656014df17c9dea01c01c6d879bfe1ce6a2a2', 'active', NULL, 191);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-I4-4', 1, 'invariant', 'interaction', NULL, NULL, 'A partial provider response never enters accepted context.', 'cf18931a920f52322dd9aebd10e490f26b02b04de201c1153cc815ae5bb1780a', 'active', NULL, 192);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-I5-1', 1, 'invariant', 'local', NULL, NULL, 'Symbol handles come from IntelliJ resolution, not from the model.', '94a12c1670f12cf2c22f716bbdd74192a7addca62685b3ba0621f2ec9950ae58', 'active', NULL, 193);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-I5-2', 1, 'invariant', 'local', NULL, NULL, 'Ambiguity, stale document state, unsupported language, unavailable indices and incomplete search are explicit outcomes, never permission to choose a first/nearest match or return an authoritative empty result.', 'dfb2b485e92a1cfe63198ca5b37b66f1215edc40521a394d4783485c3cfe3f49', 'active', NULL, 194);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-I6-1', 1, 'invariant', 'local', NULL, NULL, 'Mutation approval and mutation correctness are separate.', '10de835da57ed7b63743834864fd3c9fbb7e1cad82a04dfa507aab1452579da1', 'active', NULL, 195);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-I6-2', 1, 'pre', 'local', NULL, NULL, 'Native IDE mutations are restricted to writable project content.', '7c73a8b70035bc419bd585882e18ade632992a35e0c1593bbdfed49c3fc15bfb', 'active', NULL, 196);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-I6-3', 1, 'pre', 'interaction', NULL, NULL, 'File identity, document version, symbol identity, writability and cancellation are rechecked at the final mutation boundary for every touched target.', '55fc47cfde13198031c78a4672e8e939de5ed034138600f0db0cdec4c2bdabd9', 'active', NULL, 197);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-I6-4', 1, 'invariant', 'local', NULL, NULL, 'Unsaved editor state is authoritative.', 'd4da2f54f43d450c220747169897133fc581d737fc9fee312eafcb7d1afced49', 'active', NULL, 198);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-I6-5', 1, 'invariant', 'interaction', NULL, NULL, 'No raw offsets survive an intervening document change.', '603c3b864c36e388121e6bdc88f6c6cedfa17cbe3aaa7800521337d9616fe99f', 'active', NULL, 199);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-I7-1', 1, 'invariant', 'interaction', NULL, NULL, 'No EDT wait while holding a read action.', '02b741b517d4b10acc3a93f78497c027200e70b23baca3c8c0279720dfd0b753', 'active', NULL, 200);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-I7-2', 1, 'decision', 'local', NULL, NULL, 'Do not wrap refactoring processors in a broad read/write action.', '2722cd851fc057211c351d796b02f1eb6a546ea7a4407f7e4d1f83ed8f65982e', 'active', NULL, 201);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-I7-3', 1, 'invariant', 'local', NULL, NULL, 'Discovery is cancellable and bounded.', '12edd70ee14d8710857ee8c412d353ba9487b95fccf7f6830a70ee563ff06efd', 'active', NULL, 202);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-I7-4', 1, 'invariant', 'local', NULL, NULL, 'The write command is short, named and undoable.', '39b8d9af2f5dcb036ba34102bb6a12b3835b0ae07f1adffd9f197827ddfe6fbe', 'active', NULL, 203);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-I8-1', 1, 'invariant', 'interaction', NULL, NULL, 'Stop wins against not-yet-started effects through one synchronized admission boundary shared by cancellation and effect start, checked inside the actual queued runnable, not before scheduling.', 'f44d80df6a5891ce59d6d6e20e3ddd7bb91bf8c004831f001ad28d24faa49e55', 'active', NULL, 205);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-I8-2', 1, 'invariant', 'interaction', NULL, NULL, 'Once an effect begins, Stop does not roll it back; the run stays `STOPPING` until it and owned cleanup settle, and no new run can start.', '9d0a6e1885307cf80f7374a77a4c32057033b1ba8612e28b015cd6d7ffe773f1', 'active', NULL, 206);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-I8-3', 1, 'decision', 'local', NULL, NULL, 'No unconditional "Stop always finishes" claim: safety holds without progress assumptions, liveness assumes the operation eventually returns.', '777a9dab8496d0ffbadfc99fc0b2f29192add243740dc7f4bfdbba3bb433c563', 'active', NULL, 207);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-I9-1', 1, 'invariant', 'interaction', NULL, NULL, 'Run-owned formatting, saves, diagnostic waits, request bodies, HTTP requests and callbacks are cancellable or tracked to completion.', '86478156aa451531f3f82348dcb67c807f2aa22aa705622c824f232bd181dcce', 'active', NULL, 208);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-I9-2', 1, 'invariant', 'interaction', NULL, NULL, 'No background queue mutates after the run reports stopped.', '5f4b4c3a702c392579ea450a7ecaa39ac0f82857e7cd50b0ca05dba175b26458', 'active', NULL, 209);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-I9-3', 1, 'invariant', 'local', NULL, NULL, 'Cleanup does not block EDT.', 'e1516395e94677673571aecf0b12d5bafb52a34e9521c8adec7c585e3e682ee0', 'active', NULL, 210);
