INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-ST-1', 1, 'pre', 'local', NULL, NULL, '`search_text`: explicit file/directory scope and literal query; regex deferred.', 'b2b524f78a3578fcb2bbab3061743a694d3e09f30a6e570b9fded25602a1b235', 'active', NULL, 241);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-ST-2', 1, 'invariant', 'local', NULL, NULL, '`search_text` caps 50 matches/page, 100 maximum, bounded excerpts, generated/excluded paths omitted.', '6aeda39a80ee292b69e7f1eaf4c2d1719ab0577a234e4e82fec1c4ff965a423b', 'active', NULL, 242);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-H-1', 1, 'invariant', 'local', NULL, NULL, 'Handles: bounded session-local LRU (initial bound 2,048; tune from dogfood).', '42ee277bfcd2eaf2b9defb9ff8c7232208d0d4b40c251d83734dee415e8bb320', 'active', NULL, 243);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-H-2', 1, 'invariant', 'interaction', NULL, NULL, 'Eviction is safe because mutations fail on an evicted handle.', '9f6a10ab6055124cae62d5994e38b6d99db695384b9a18b1bc82ce2e392f02cd', 'active', NULL, 244);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-H-3', 1, 'invariant', 'interaction', NULL, NULL, 'File edits invalidate handles for affected files.', '0b01d68e89d9aa93b9ace547caa400a9336fa32bb15f48d851cf02ce27828691', 'active', NULL, 245);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-H-4', 1, 'invariant', 'local', NULL, NULL, 'A symbol handle maps to a smart pointer plus language/owner/signature and document identity/version. A read handle maps to file identity/version and inspected ranges.', '96c8c147f73d009b34ddf31d2c3c0ae9c940a9762b74bf7bc0d23afde59c1b97', 'active', NULL, 246);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-H-5', 1, 'invariant', 'interaction', NULL, NULL, 'Validate pointers under read access.', '7632206fd7b73e20bc551db27ea4e1eef23f98dbccf4235c5465750e4b813776', 'active', NULL, 247);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-H-6', 1, 'decision', 'local', NULL, NULL, 'Prefer smart pointer plus document version; hash content only where filesystem or process boundaries make it useful.', 'fa9b39d56d36dbf266f590965b83f751845ab8480535a1a207b8e80708573ccd', 'active', NULL, 248);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-H-7', 1, 'invariant', 'local', NULL, NULL, 'No serialization of PSI pointers to the model.', 'b0fd377aa931ddb37ad0eb172728e95e4597b165ea76f8582a188e63d7042036', 'active', NULL, 249);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-H-8', 1, 'invariant', 'interaction', NULL, NULL, 'Handles are disposed on New Session and content close.', '5435b16cdf6e537f2ed6e99bb185076d1ec59af54f307610bb39bc71f5c0b8b8', 'active', NULL, 250);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-RD-1', 1, 'outcome', 'local', 'read cancelled or unexpected error', 'fail closed with catalog-tool hints', 'Readiness: fail closed on cancellation and unexpected errors; give actionable hints naming only catalog tools.', '8487cade7d4081e8009050b8e0f68e744be0b563fbc54ffe9d0af487358d50dc', 'active', NULL, 251);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-RT-1', 1, 'invariant', 'local', NULL, NULL, 'Retry at most once per provider request, only before acceptance: transient transport/EOF, 429 excluding quota/billing, or 5xx.', '27dc477918d2ef3704610aaa167d302ba856758c8874e6c5b0e3835cd1afd1cd', 'active', NULL, 252);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-RT-2', 1, 'decision', 'local', NULL, NULL, 'Delay 1 s or use a valid `Retry-After` from 0 through 10 s. A missing or malformed value uses 1 s.', 'f05edbf322265f9db667f696bbecb747b124b9e4613e5498e874797a6269f59c', 'active', NULL, 253);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-RT-3', 1, 'outcome', 'local', 'Retry-After negative or above 10 s', 'rate-limit outcome with requested wait', 'A negative or above-10-second value is not silently clamped or automatically waited; return the rate-limit outcome with the requested wait when available.', 'b12d58f9311f6b73603d2376823f0fb08d29010f4209c3b89d8650e38b5aa5e4', 'active', NULL, 254);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-RT-4', 1, 'pre', 'interaction', NULL, NULL, 'Roll back provisional UI before retry.', 'd4006305595531f211984858d66f652abe14b8bb9a6bd917c9b5b91e5d644fbf', 'active', NULL, 255);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-RT-5', 1, 'invariant', 'local', NULL, NULL, 'Auth refresh retry shares the two-attempt ceiling.', '225a70a6c91faae8741540add3aca5d40071422de0c29ac32418bc6f218dba2c', 'active', NULL, 256);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-RT-6', 1, 'invariant', 'local', NULL, NULL, 'No retry for malformed content, unsupported model, bad schema, billing/quota, context limit, Stop or executed calls.', '25214db31a8b53a3fb9646d6200d588f25ab82fa721a580dec73ee6cf9f45869', 'active', NULL, 257);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-SCOPE-0', 1, 'decision', 'local', NULL, NULL, 'read-domain scope: Platform-free Java domain for the seven IntelliJ-native read operations: typed argument values with a closed argument-rejection algebra, result bound values and the result collection cap value, the session-local registry for symbol handles, read handles and page tokens, read handle values, immutable outcome values and ordering comparators.', 'b759778167a8c2ea86a836ea40a699215306b6184741e0070911ef8612551158', 'active', NULL, 360);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-SCOPE-1', 1, 'decision', 'local', NULL, NULL, 'read-domain scope: No IntelliJ access and no operation execution: the adapter slices bind these values to their operations.', '6e95af4edf1e9513ad574844ff8c83c5638f3679a9bae4cf0895703e74f62c74', 'active', NULL, 361);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-SCOPE-2', 1, 'decision', 'local', NULL, NULL, 'read-domain scope: Depends on CAP-LIFECYCLE-ADMISSION and CAP-DOMAIN-RUN-DRIVER for gate order only; read domain values use no type from them.', '8803f2884dd31893ef74d466f0a44e350d843f74befa042fd1b664d9a1554dd3', 'active', NULL, 362);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-SCOPE-3', 1, 'decision', 'local', NULL, NULL, 'read-domain scope: Wire JSON argument parsing, tool schemas, the LLM status/code/content envelope and rendering of read outcomes into ToolOutcome content are excluded and belong to the codec feature.', 'f731f40988eecdd5315dd6f074b3194dcc94a60ed02e2cea083b39c491f408bd', 'active', NULL, 363);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-NG-0', 1, 'decision', 'local', NULL, NULL, 'Out of scope for read-domain: Wire JSON argument parsing, tool schemas, tool descriptions, the LLM status/code/content envelope and ToolOutcome content rendering', 'cd3e673eed5f740f3a3343bf3e5ae0fda85a2b747e057a1ab799091c414bd7f6', 'active', NULL, 364);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-NG-1', 1, 'decision', 'local', NULL, NULL, 'Out of scope for read-domain: Mutations, handle invalidation on agent edits, formatting, diagnostics, build and test execution', '870476117ec8b7d11caffb5615fa9a60f48ba9a6f5f44039bbdb64355cc83a4f', 'active', NULL, 365);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-NG-2', 1, 'decision', 'local', NULL, NULL, 'Out of scope for read-domain: Regex search, case-insensitive search, glob file patterns and whole-project unscoped text search', '618ffe7a28d16f28cc3e4114c588f9225cd17fe0521c8324c3e01bb229700ae7', 'active', NULL, 366);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-NG-3', 1, 'decision', 'local', NULL, NULL, 'Out of scope for read-domain: Semantic support or parity claims for languages other than Java', 'd4d21ad192e8fbc5aa747ea40d88155bbadab98cd7c18086c76ae4a5688005e6', 'active', NULL, 367);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-NG-4', 1, 'decision', 'local', NULL, NULL, 'Out of scope for read-domain: Session owner wiring, New Session UI and tool-window content lifetime integration beyond a registry dispose operation', '8283d8235a09bede189386366067fbaab9fa7d72a70ba29afa41b69b938bc643', 'active', NULL, 368);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-NG-5', 1, 'decision', 'local', NULL, NULL, 'Out of scope for read-domain: Persisting handles, page tokens or read results across sessions', 'e71305813cb754857fa35f6a7ffaa77219287865e61cefd8bcae77c99b297a08', 'active', NULL, 369);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-NG-6', 1, 'decision', 'local', NULL, NULL, 'Out of scope for read-domain: MCP, HTTP, idea-facade or any second index beside IntelliJ', '84a7045a0b948eb02daa80ad74dc75450c6b2ce7eec1ac245b6475a3a5148042', 'active', NULL, 370);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-NG-7', 1, 'decision', 'local', NULL, NULL, 'Out of scope for read-domain: Changing CAP-LIFECYCLE-ADMISSION or CAP-DOMAIN-RUN-DRIVER declarations or semantics', '023417bd72c99f0813ad12d5c4a5dffcc0c93f7964101153d9f9f1d8cc087475', 'active', NULL, 371);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-NG-8', 1, 'decision', 'local', NULL, NULL, 'Out of scope for read-domain: Operation execution, handle and page token issuance by operations, IDE-state regressions and the milestone prefix test, which the other semantic reads slices own', '719b0605a02b60e9bc2ef34ca5d36bcb5b4730596df365c21a96576db0f784b1', 'active', NULL, 372);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-AS-0', 1, 'pre', 'local', NULL, NULL, 'read-domain assumption: Requirement IDs are unique across the five semantic reads slices, which replace CAP-SEMANTIC-READS. A reference to a requirement outside this spec names the slice that owns it: read-domain SR-001, SR-002, SR-012, SR-014, SR-021, SR-022, SR-023, SR-024; read-pipeline SR-003, SR-004, SR-005, SR-015, SR-016, SR-019, SR-020, SR-026, SR-028; read-text-search SR-010, SR-017; read-symbols SR-006, SR-007, SR-008, SR-011, SR-013, SR-018, SR-025; read-references SR-009, SR-027.', '68f6bd37df341a880ef391a911ebe87dbf620aa90e1b465589159952eae81697', 'active', NULL, 373);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-AS-1', 1, 'pre', 'local', NULL, NULL, 'read-domain assumption: CAP-LIFECYCLE-ADMISSION is frozen with FINAL_GATE_PASS; its S3 is blocked only on EV-SURFACE. This feature relies on its admission semantics, and this feature''s S3 cannot close while lifecycle S3 remains blocked.', 'c3864c797c3ea6dde4def6824468b7e0ed60a01f4988ce45cb14c4db3834985b', 'active', NULL, 374);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-AS-2', 1, 'pre', 'local', NULL, NULL, 'read-domain assumption: CAP-DOMAIN-RUN-DRIVER is closed. Read domain values use none of its types; the dependency sets gate order only.', '6fa4655509c13819cb2cf51fdca13fbdc407357ce73623b632eaa2ffe2132b0b', 'active', NULL, 375);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-AS-3', 1, 'pre', 'local', NULL, NULL, 'read-domain assumption: Normalizations of product bounds: limit 1–100 with default 50 for find_references; 300 lines and 24 KiB for declaration source; 1,000 UTF-16 units for text queries.', '130cf213621c96a6b28cfc6e14499ca3f3fa93208e7aeb49ca2d762e184402b7', 'active', NULL, 376);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-AS-4', 1, 'pre', 'local', NULL, NULL, 'read-domain assumption: Normalizations without an owner question (review suggested resolutions): SR-001 argument names, reason set, check order, Java identifier rule, int line values and capped default end_line; SR-002 line count, UTF-8 byte and UTF-16 unit counting; SR-012 entry kinds, registry identity in identifiers, predicate order, release of the offered payload and exception behavior; SR-023 release order and suppressed exceptions; SR-024 source order as start offset.', '2b0382380035a90e6f15a4fd038e174c56e0a310c8b90dfa38db7e309ce04eef', 'active', NULL, 377);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-0-0', 1, 'invariant', 'local', NULL, NULL, 'The read catalog is exactly seven operations: find_file, search_symbols, get_file_outline, get_symbol_info, find_references, read_file, search_text.', '98f2639cf13cf2fbd97b3ff53513662f43aedc3e33090c6dd695ee732712711b', 'active', NULL, 378);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-0-1', 1, 'invariant', 'local', NULL, NULL, 'Each operation has its own typed argument value, and no model-visible generic dispatcher exists.', '040fa212509c52042f2ecde71f2e604768ac4ec637a6c0f1ca40e463c6093270', 'active', NULL, 379);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-0-2', 1, 'invariant', 'local', NULL, NULL, 'One controlled factory per operation returns either the validated argument value or exactly one argument rejection, and performs no I/O and no platform access.', '90a69586ca8c70347996e1ef69d7d14567a2c4ecdc0d2eedb61af28f4bf72180', 'active', NULL, 380);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-0-3', 1, 'invariant', 'local', NULL, NULL, 'An argument rejection holds one argument name from the closed set query, name, restriction, limit, page_token, path, symbol_handle, start_line, end_line, scope_path, and one reason from the closed set EMPTY, TOO_LONG, LINE_BREAK, NOT_JAVA_IDENTIFIER, BACKSLASH, EDGE_SLASH, INVALID_SEGMENT, NAME_REQUIRES_RESTRICTION, LIMIT_OUT_OF_RANGE, LINE_BELOW_ONE, END_BEFORE_START, SPAN_TOO_LARGE.', '0333c53bb98bf85bb1a48015ddf29ed891831a523c26316f9f1fab1072e5611f', 'active', NULL, 381);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-0-4', 1, 'invariant', 'local', NULL, NULL, 'Components are checked in this argument order: find_file query, limit, page_token; search_symbols name, restriction, limit, page_token; get_file_outline path, page_token; get_symbol_info symbol_handle; find_references symbol_handle, limit, page_token; read_file path, start_line, end_line; search_text scope_path, query, limit, page_token.', '6dfc41965d153e0f528e2ebd83d9f90e7dcf3339db92bbeabd5f2b21744c0a9a', 'active', NULL, 382);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-0-5', 1, 'decision', 'local', NULL, NULL, 'Scope values are enumerations and cannot fail.', '94888d2fccae8105a09668fab09c3b122604f84e6949e803bc54d4120f5a6112', 'active', NULL, 383);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-0-6', 1, 'invariant', 'local', NULL, NULL, 'Inside one component the checks run in the order below, and the first failing check is the result.', 'd585ad3850a2d67b06f1aab05a6b9d4c63957480e5996afe558b2f2e0ced7ed9', 'active', NULL, 384);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-0-7', 1, 'invariant', 'local', NULL, NULL, '(1) A text query (find_file query, search_symbols name, search_text query): EMPTY when a find_file or search_text query has zero UTF-16 code units; TOO_LONG above 1,000 UTF-16 code units; LINE_BREAK when it contains CR or LF; for a find_file query, BACKSLASH when it contains ''\\'', EDGE_SLASH when it starts or ends with ''/'', INVALID_SEGMENT when a ''/''-separated segment is empty, ''.'' or ''..''; for a nonempty search_symbols name, NOT_JAVA_IDENTIFIER unless its first code point satisfies Character.isJavaIdentifierStart and every other code point satisfies Character.isJavaIdentifierPart. A query is never trimmed, and a whitespace-only query is valid.', 'db5948952d7a9f0659f75d14f0904aa8be64e76a40d292a545b061c6cfb765e3', 'active', NULL, 385);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-0-8', 1, 'invariant', 'local', NULL, NULL, '(2) The search_symbols restriction: NAME_REQUIRES_RESTRICTION when the name is empty and no restriction is present.', '1a00e892298d111b6a208476f4fa121d7cbe4742512ea86b8e6f262b53a8c4fe', 'active', NULL, 386);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-0-9', 1, 'invariant', 'local', NULL, NULL, '(3) A path, file restriction path, symbol handle, owner type handle or page token string: EMPTY when it has zero UTF-16 code units; its content is checked by the adapter or the registry.', 'ea37c7c0b1f4478573141942f6242eeb69a08033e8973f3e07f5898b42610b3a', 'active', NULL, 387);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-0-10', 1, 'invariant', 'local', NULL, NULL, '(4) limit: absent gives 50; LIMIT_OUT_OF_RANGE outside 1–100.', 'c727f7b3e78ffaccdd6fd1ba7e4496a2c36138f3d1d6c93565a39a0f69dd6462', 'active', NULL, 388);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-0-11', 1, 'invariant', 'local', NULL, NULL, '(5) read_file lines are Java int values: absent start_line gives 1; LINE_BELOW_ONE when start_line is below 1; absent end_line gives start_line plus 99, capped at 2,147,483,647; END_BEFORE_START when end_line is below start_line; SPAN_TOO_LARGE when end_line minus start_line plus 1 is above 300, computed without integer overflow.', '810c4705d6fb2a6a9789cb7c4c34100629017b85a9d567c58722bbc0ac44783b', 'active', NULL, 389);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-1-0', 1, 'invariant', 'local', NULL, NULL, 'Result bound values: the limit of find_file, search_symbols, find_references and search_text is 1–100 with default 50 (SR-001); an outline page holds at most 100 entries; read_file content holds at most 300 lines and 24 KiB; declaration source holds at most 300 lines and 24 KiB; a match or reference excerpt holds at most 500 UTF-16 code units and carries an explicit truncated flag, independent of its length.', 'ec50e2d96d06106f361b70eb5a1b14853519f7e97d4b2ef2e4db6e5c9bd53fb8', 'active', NULL, 390);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-1-1', 1, 'invariant', 'local', NULL, NULL, 'Byte bounds count the UTF-8 bytes of the text.', '00179e3861dde10d5c1b79982ef9e51a1db5ef19b0aa401cf32d0266b92fb22d', 'active', NULL, 391);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-1-2', 1, 'invariant', 'local', NULL, NULL, 'Unit bounds count UTF-16 code units, so a surrogate pair counts as 2.', '41a926a7238a8012c97f6d713a1bc45697cc21a97ad4d53bf9a446960f4f0b79', 'active', NULL, 392);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-1-3', 1, 'invariant', 'local', NULL, NULL, 'The line count of a text is the number of LF characters, plus 1 when the text is nonempty and does not end with LF.', '2bc3ec800a6a5fd0dcbeb4bca564bf291b39426acc0ee8a11a0f1fc6df5632e6', 'active', NULL, 393);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-1-4', 1, 'invariant', 'local', NULL, NULL, 'Each bound value rejects an oversized value at construction, so no result value can exceed its bound.', 'b9d4291e21b99f45a4e6c88d25bd590e8818c0d9bdaa24ad5b8a859ce66077c8', 'active', NULL, 394);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-1-5', 1, 'invariant', 'local', NULL, NULL, 'The result collection cap is a validated value of at least 1 with production value 10,000.', 'b993055ec318d8bcf72ed6d9511cfdc00fb946c5caa4b4db62890abc970f2864', 'active', NULL, 395);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-1-6', 1, 'invariant', 'local', NULL, NULL, 'The TOO_MANY_RESULTS outcome holds a narrowing hint and no page.', 'd961c1b8314cfe82f22eb92fe9d57fe2f978f0fa31c2f6f79770ff2a23cbc743', 'active', NULL, 396);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-1-7', 1, 'decision', 'local', NULL, NULL, 'Collection, sorting and paging with these values belong to the adapter slices.', '9e3efbe6a8def935769ddb621449f2cad12fcb5ff40a213e35b53199e6a9d8c5', 'active', NULL, 397);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-2-0', 1, 'invariant', 'local', NULL, NULL, 'One session-local registry holds symbol handles, read handles and page tokens with a total bound of 2,048 entries and least-recently-used eviction.', '9c924db2629386c3a538b906b65aabc43e0a1b617b892a342b3dd8a3630773bb', 'active', NULL, 398);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-2-1', 1, 'invariant', 'local', NULL, NULL, 'Each entry has one kind (symbol handle, read handle or page token), and each lookup is for one kind.', 'e8f6b6472240f22358075a1212eb14fe1ece1818e7b8210b03ff386a4060a9bc', 'active', NULL, 399);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-2-2', 1, 'invariant', 'local', NULL, NULL, 'Every identifier embeds the identity of its issuing registry, so an identifier from another registry never matches a live entry, even when its registry-local part equals the local part of a live entry.', '99ec3180408068058994fcefbb3d869eeacf3e783b385ba7a2937f98a9df7b49', 'active', NULL, 400);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-2-3', 1, 'invariant', 'local', NULL, NULL, 'The registry is generic over an opaque payload type supplied by the adapter; it never inspects or compares payloads, and it invokes the adapter release action exactly once for each payload that it discards.', '33f413653561f46922b0211a98abed095b3f77d9f385dbd3e421db2a1a9de452', 'active', NULL, 401);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-2-4', 1, 'invariant', 'local', NULL, NULL, 'Each registry operation is atomic with respect to the other operations; match predicates and release actions run inside it.', 'a6ea43b4e2677bc75a8201b61e4d2112001c23918934643d0da240d187ac11cc', 'active', NULL, 402);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-2-5', 1, 'invariant', 'local', NULL, NULL, '(1) Issue registers a payload of one kind as the most recently used entry and returns a new identifier; when the registry already holds 2,048 entries, it first evicts the least recently used entry of any kind and releases its payload.', '817a91971b75cf6111a25cc3c07dee4753e6a6f173618aea66e98ac1e6c9d25e', 'active', NULL, 403);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-2-6', 1, 'invariant', 'local', NULL, NULL, '(2) Issue-or-reuse accepts symbol handle payloads only: it calls the adapter match predicate on the live symbol handle payloads, most recently used first, until one returns true; a match makes that entry most recently used, releases the offered payload and returns the existing identifier; no match behaves as issue. If the match predicate throws, the exception propagates, the registry is unchanged and the offered payload is not released.', 'b68b2e3011e0bf4c9dd15a5b91c58aac3515baa915f7c90b5675f8c32fdb5a82', 'active', NULL, 404);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-2-7', 1, 'invariant', 'local', NULL, NULL, '(3) A lookup of a live identifier of the requested kind issued by this registry returns its payload and makes the entry most recently used.', '473c74b5b9cf7cc2d33166ea84f40f4c930b0b8dfbb0eba5b8c1116066e9aae8', 'active', NULL, 405);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-2-8', 1, 'invariant', 'local', NULL, NULL, '(4) A lookup of an identifier that was never issued, was evicted, has another kind or was issued by another registry changes nothing and returns stale for the requested kind: STALE_HANDLE with a rediscovery hint for a symbol or read handle lookup, STALE_PAGE for a page token lookup.', '680eff74c0cd129ad1816075fdf13b7d4bf84c647a8ccaa23cf268403c8076af', 'active', NULL, 406);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-2-9', 1, 'invariant', 'interaction', NULL, NULL, '(5) Issue or issue-or-reuse on a disposed registry registers nothing, calls no match predicate, releases the offered payload and returns a disposed result.', 'df990c681bf03d93023266c251ba4f862c2cf29efd3ac2cf9a6224ae3531c904', 'active', NULL, 407);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-2-10', 1, 'invariant', 'local', NULL, NULL, 'An exception from a release action propagates after the registry change of the operation is complete.', 'ea7acdaa15763f77d0d5787a7f4076cd0a832ba29f4cdbbc5aa0950f1175ac6f', 'active', NULL, 408);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-3-0', 1, 'invariant', 'local', NULL, NULL, 'A read handle is an immutable value of file identity, the document modification stamp observed at the read, and the exact inspected line and offset ranges; construction rejects a start after its end, negative offsets and line values below 1.', '1b5544e9084166298780c33ac25b545c4b9b40d16231aec4123f17f39d6144be', 'active', NULL, 409);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-3-1', 1, 'invariant', 'local', NULL, NULL, 'This feature performs no mutation with a read handle.', 'aab9c803048c86913258abe55b53a6e70bbe4187466510a9a8e0be826dabf77e', 'active', NULL, 410);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-4-0', 1, 'invariant', 'local', NULL, NULL, 'Java read domain values for arguments, argument rejections, bound values, outcomes, handles, page tokens, comparators and the generic registry reference only java.* types and other read domain types.', '41773b4b8b30011bdd7a288b3a6ec5f77d2a267ce659cadb823cba5b8d72bd74', 'active', NULL, 411);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-4-1', 1, 'invariant', 'local', NULL, NULL, 'They reference no IntelliJ platform, JSON, Kotlin, coroutine, MCP or HTTP type, no type from the lifecycle or run packages, and no java.lang.reflect type.', '64feac15c7f9c0cfaaa2163bba95c8261b9a164aae72f46d7ec2b301aa6a8e9f', 'active', NULL, 412);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-5-0', 1, 'invariant', 'local', NULL, NULL, 'Every read outcome value is deeply immutable: it holds only strings, primitives, read domain values and unmodifiable copies of collections, and no platform object.', '80b89943be5338de24b986a39e1241932160908c024fca44fa6ca47002fd96f9', 'active', NULL, 413);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-5-1', 1, 'invariant', 'local', NULL, NULL, 'Changing an input collection after construction does not change the value.', '1fc4371227cde0a775035c7cfe188cb269ae2b1dda6ee8a3c4decab873782e02', 'active', NULL, 414);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-5-2', 1, 'invariant', 'local', NULL, NULL, 'Outcome values have component-wise value equality.', '93e7b185396f698d856ce027d94b2433e0dbe02c1d38ccff55ca198b69d3a8c5', 'active', NULL, 415);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-6-0', 1, 'invariant', 'local', NULL, NULL, 'Disposal is a registry operation.', 'ce793686aa795852723a233c40179de6fbd578794bb8d922a65ae47a92bb9419', 'active', NULL, 416);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-6-1', 1, 'invariant', 'local', NULL, NULL, 'Dispose on a live registry invalidates every entry and releases each live payload exactly once, least recently used first; if release actions throw, every payload is still released, the first exception propagates and later exceptions are added to it as suppressed.', '1db63dfdf916d094b1958063d0b193d72e42d49e241f36fc3d056c3e172c1a7d', 'active', NULL, 417);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-6-2', 1, 'invariant', 'interaction', NULL, NULL, 'After disposal, every lookup returns stale for the requested kind, and issue and issue-or-reuse follow SR-012 (5).', '764c464c483d52036964aba9744b697096a22ec7ab047f97dd0abbdde401cb36', 'active', NULL, 418);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-6-3', 1, 'invariant', 'local', NULL, NULL, 'Dispose on a disposed registry has no effect.', '59f9fac81ed28d2a5ef70ef3277efaa176a0acf2af3fe141ad5d9016e16283fb', 'active', NULL, 419);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-6-4', 1, 'invariant', 'local', NULL, NULL, 'A new registry never resolves an identifier issued by a disposed registry.', '97047b9562b4fdc1fd9c9dde8dc4385f070d27eeedf8b32037208f24d6d1c868', 'active', NULL, 420);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-6-5', 1, 'decision', 'local', NULL, NULL, 'This feature does not call dispose.', 'ea93da5cb36dada545c04cdf046af1cdfca17215f3fa956ee077b71e0919cf0b', 'active', NULL, 421);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-7-0', 1, 'invariant', 'local', NULL, NULL, 'Result ordering comparators are deterministic: find_file by rendered path; search_symbols by qualified owner, name, signature, rendered path and start offset; get_file_outline in source order, by start offset; find_references and search_text by rendered path, then start offset.', '8dbce4b545d02527816cdfaf9d850113bf54bb4d30b89c5cce5f880f6533966d', 'active', NULL, 422);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-REQ-7-1', 1, 'invariant', 'local', NULL, NULL, 'Strings compare by UTF-16 code unit; an absent value sorts before any present value.', '44e9d564b0e18e4ee4351b5753a5e51d5cc8c9de0137909a7ad583213d995d32', 'active', NULL, 423);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-ACC-0', 1, 'outcome', 'local', 'read-domain: factory arguments at, below, above bounds and multi-failure', 'Valid values construct, whitespace-only queries included and untrimmed; an absent limit is 50, an absent start_line is 1, an absent end_line is start_line plus 99 and is 2,147,483,647 for the largest start_line. Every invalid value returns exactly one argument rejection with the expected argument name and reason. The multi-failure cases return TOO_LONG for query, BACKSLASH for query, EMPTY for query and LINE_BELOW_ONE for start_line. The read-operation algebra has exactly seven variants.', 'read-domain acceptance ReadArgumentsTest#argumentsEnforceCatalogBounds: when For each operation factory, construct arguments at, below and above every bound: find_file and search_text queries of 0, 1, 1,000 and 1,001 UTF-16 units, one of 1,000 units made of surrogate pairs, whitespace-only queries and queries containing CR and LF; search_symbols names that are empty with and without a restriction and names that are not Java identifiers; find_file queries containing ''\\'', a leading and a trailing ''/'', and an empty, ''.'' and ''..'' segment; limits 0, 1, 100 and 101 and an absent limit; empty path, handle and token strings; read_file start_line 0, absent start_line and end_line, end_line before start_line, spans of 300 and 301 lines, and start_line 2,147,483,647 with absent end_line. Also construct arguments that fail several checks: a find_file query of 1,001 units that contains LF, a find_file query with ''\\'' and a ''..'' segment, an empty find_file query with limit 0, and a read_file argument with start_line 0 and end_line 301. then Valid values construct, whitespace-only queries included and untrimmed; an absent limit is 50, an absent start_line is 1, an absent end_line is start_line plus 99 and is 2,147,483,647 for the largest start_line. Every invalid value returns exactly one argument rejection with the expected argument name and reason. The multi-failure cases return TOO_LONG for query, BACKSLASH for query, EMPTY for query and LINE_BELOW_ONE for start_line. The read-operation algebra has exactly seven variants.', '3d0007798e0cb6f5a735fb9ce9db97e6ad9e09115b4e0c646914a4a24864b518', 'active', NULL, 424);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-ACC-1', 1, 'outcome', 'local', 'read-domain: registry recency, kinds, reuse and cross-registry lookups', 'Issuing n1 evicts e2, not e1; the reuse call calls the predicate on e4 first, returns the identifier of e4, releases the offered payload once and adds no entry, and issuing n2 evicts e3; the wrong-kind lookup of e5 returns stale for the requested kind and issuing n3 evicts e5; the unmatched reuse issues a new symbol handle and evicts e6; issuing n5 evicts e7, not n1; each evicted payload is released exactly once and each evicted lookup returns STALE_HANDLE for handle kinds and STALE_PAGE for page tokens; the throwing predicate propagates its exception, every live entry still resolves and the offered payload is not released; both cross-registry lookups return stale.', 'read-domain acceptance HandleRegistryTest#recencyKindsAndRegistryIdentity: when With a fake payload that records release calls, issue entries e1 to e2,048 of all three kinds in registry A, with e3 and e4 as symbol handles. Then, in order: look up e1 successfully and issue n1; issue-or-reuse an offered symbol payload with a predicate that matches the payloads of e3 and e4, after a lookup of e4, and issue n2; look up e5 as a different kind and issue n3; issue-or-reuse with a predicate that matches nothing; issue n5; look up evicted entries by their kinds; issue-or-reuse with a predicate that throws. Entries n1, n2, n3 and n5 are read handles. Separately, issue one entry of the kind of e1 in a new registry B, so that its registry-local part equals that of e1, and look up that B identifier in A and e1 in B. then Issuing n1 evicts e2, not e1; the reuse call calls the predicate on e4 first, returns the identifier of e4, releases the offered payload once and adds no entry, and issuing n2 evicts e3; the wrong-kind lookup of e5 returns stale for the requested kind and issuing n3 evicts e5; the unmatched reuse issues a new symbol handle and evicts e6; issuing n5 evicts e7, not n1; each evicted payload is released exactly once and each evicted lookup returns STALE_HANDLE for handle kinds and STALE_PAGE for page tokens; the throwing predicate propagates its exception, every live entry still resolves and the offered payload is not released; both cross-registry lookups return stale.', 'dec77a7450fd6af394c40c95ffdae814259bd582d844cdb92ed82a4043952cf7', 'active', NULL, 425);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-ACC-2', 1, 'outcome', 'local', 'read-domain: compiled read domain class constant pools', 'At least one class is found, and the set contains every read domain class that the design declares; every class name referenced by a constant pool, except read domain classes, starts with java/ and not with java/lang/reflect/.', 'read-domain acceptance ReadDomainArchitectureTest#readDomainReferencesOnlyJava: when Discover every class file in the compiled read domain package from the test runtime class path, including nested and synthetic classes, and read the constant pool of each. then At least one class is found, and the set contains every read domain class that the design declares; every class name referenced by a constant pool, except read domain classes, starts with java/ and not with java/lang/reflect/.', '93b84e368cc4a393c14f32c3e9d688b77faf2a9296c1d1b0e339a5babcb608bb', 'active', NULL, 426);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-ACC-3', 1, 'outcome', 'local', 'read-domain: outcome construction from mutable inputs', 'Every outcome stays equal to a copy taken at construction; its collections reject modification; equal components give equal values and equal hash codes; a differing component gives unequal values; every component type is a java.* type or a read domain type.', 'read-domain acceptance ReadOutcomeTest#outcomesAreImmutableSnapshots: when Construct each read outcome variant from mutable input lists, then mutate the lists; construct two outcomes with equal components, and two outcomes that differ in one component. then Every outcome stays equal to a copy taken at construction; its collections reject modification; equal components give equal values and equal hash codes; a differing component gives unequal values; every component type is a java.* type or a read domain type.', 'ebb0d1d5aeeae5d5a0c51d3606bc0f14fcce95aee93ecc9966db7e2c5313bf55', 'active', NULL, 427);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-ACC-4', 1, 'outcome', 'local', 'read-domain: read handle construction with invalid ranges', 'Invalid values are rejected at construction; a valid read handle keeps its file identity, version and ranges unchanged.', 'read-domain acceptance ReadOutcomeTest#readHandlesValidateRanges: when Construct read handles with a start after its end, negative offsets, a line value of 0, and valid ranges. then Invalid values are rejected at construction; a valid read handle keeps its file identity, version and ranges unchanged.', 'a8555772a90ed99c9ab1345255865e5815d0bee8fbaf5eb0193efe31a68ebee2', 'active', NULL, 428);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-ACC-5', 1, 'outcome', 'local', 'read-domain: sorting results with each comparator', 'Each list follows its SR-024 keys by UTF-16 code unit, absent values first, with ties broken by the next key; sorting a sorted list does not change it.', 'read-domain acceptance ReadOrderingTest#comparatorsFollowCatalogKeys: when Sort unordered candidates, references, matches and files that share key prefixes, have absent owners and contain non-BMP characters, with each operation''s comparator. then Each list follows its SR-024 keys by UTF-16 code unit, absent values first, with ties broken by the next key; sorting a sorted list does not change it.', '7b63e86c8959f2179eae54e85177009bdf01a2f48197bdb01e6dba377a881532', 'active', NULL, 429);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-ACC-6', 1, 'outcome', 'local', 'read-domain: bound values at and above each bound', 'Values at a bound construct and keep their truncated flag; the 101-entry page, the 301-line texts, the 24 KiB plus one byte texts, the 501-unit excerpt and cap 0 are rejected at construction; cap 1 constructs; the production cap is 10,000; the default limit is 50; the TOO_MANY_RESULTS outcome holds its hint and has no page component.', 'read-domain acceptance ReadOutcomeTest#resultValuesEnforceBounds: when Construct bound values at and above each bound: outline pages of 100 and 101 entries; read_file content and declaration source of 300 lines with and without a final LF and of 301 lines, of 8,192 three-byte UTF-8 characters (exactly 24 KiB), and of 8,191 three-byte characters plus one four-byte character (8,192 characters, 24 KiB plus one byte); excerpts of 500 single units, of 250 surrogate pairs, and of 250 surrogate pairs plus one single unit (501 units, 251 code points), each with truncated set and clear; collection caps 0 and 1 and the production cap; the default limit; a TOO_MANY_RESULTS outcome from a hint. then Values at a bound construct and keep their truncated flag; the 101-entry page, the 301-line texts, the 24 KiB plus one byte texts, the 501-unit excerpt and cap 0 are rejected at construction; cap 1 constructs; the production cap is 10,000; the default limit is 50; the TOO_MANY_RESULTS outcome holds its hint and has no page component.', '9e0745a944e49ca978b95bdbf04574b15366d10ea428162909a8cce4e78678d3', 'active', NULL, 430);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-ACC-7', 1, 'outcome', 'local', 'read-domain: registry dispose with throwing releases', 'The first dispose releases every payload exactly once, least recently used first, and throws the first release exception with the second as suppressed; issue and issue-or-reuse return the disposed result, register nothing, never call the predicate and release their offered payloads once; every former handle returns STALE_HANDLE and every former token STALE_PAGE; the second dispose releases nothing; nothing resolves in registry C.', 'read-domain acceptance HandleRegistryTest#disposalReleasesAndInvalidates: when With a fake payload that records release order, issue symbol handles, read handles and page tokens in registry A, look one up, and make the release actions of two payloads throw; dispose A; issue, issue-or-reuse with a recording predicate, and look up every former identifier by its kind; dispose A again; look up the former identifiers in a new registry C. then The first dispose releases every payload exactly once, least recently used first, and throws the first release exception with the second as suppressed; issue and issue-or-reuse return the disposed result, register nothing, never call the predicate and release their offered payloads once; every former handle returns STALE_HANDLE and every former token STALE_PAGE; the second dispose releases nothing; nothing resolves in registry C.', '8b9817b2a8f3bf2d0f71b7734b4ad26dd5087c45e5ef3469bcdc99fed2101a5d', 'active', NULL, 431);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-DEC-result_collection_cap', 1, 'decision', 'local', NULL, NULL, 'read-domain decision result_collection_cap: 10000_THEN_TOO_MANY_RESULTS', '6add7eee0174877de36a6738b78d07b4f70da1232383ea6e29bcb953e2f99eb0', 'active', NULL, 441);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-DEC-argument_rejection', 1, 'decision', 'local', NULL, NULL, 'read-domain decision argument_rejection: FIRST_FAILING_CHECK_IN_FIXED_ORDER', 'e85a2d7b0b57d5a39a9652f368e1a4b2249e216eb6e85d363ef9bd0468bd8ef0', 'active', NULL, 442);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-DEC-whitespace_query', 1, 'decision', 'local', NULL, NULL, 'read-domain decision whitespace_query: VALID_NO_TRIM', '76cd26abe8ee204ac4753c07341e9535a8d4ae1b0c01f52ba70eec16c44b0ba0', 'active', NULL, 443);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-OPM-0', 1, 'outcome', 'local', 'read-domain read argument factory in CONSTRUCTION when every check passes', 'Validated argument value with defaults applied', 'read-domain read argument factory in CONSTRUCTION when every check passes: Validated argument value with defaults applied; next phase CONSTRUCTION', 'febf2f46eb8ca8ad05badc37c514f6dd7a46ccce21fa38d772f121607581f520', 'active', NULL, 444);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-OPM-1', 1, 'outcome', 'local', 'read-domain read argument factory in CONSTRUCTION when one or more checks fail', 'Exactly one argument rejection: the first failing check in SR-001 order; no argument value', 'read-domain read argument factory in CONSTRUCTION when one or more checks fail: Exactly one argument rejection: the first failing check in SR-001 order; no argument value; next phase CONSTRUCTION', 'c8bae22391350489ca7eb57d303203152ece939f870140d42353b10e2a325530', 'active', NULL, 445);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-OPM-2', 1, 'outcome', 'local', 'read-domain issue in LIVE_BELOW_CAPACITY when fewer than 2,047 entries', 'Register the payload as most recently used; return a new identifier', 'read-domain issue in LIVE_BELOW_CAPACITY when fewer than 2,047 entries: Register the payload as most recently used; return a new identifier; next phase LIVE_BELOW_CAPACITY', '38aafb82f2aa5a523c70e10ed9fa3c68cb6e3cf03db7304981da2af6ed1ffa33', 'active', NULL, 446);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-OPM-3', 1, 'outcome', 'local', 'read-domain issue in LIVE_BELOW_CAPACITY when exactly 2,047 entries', 'Register the payload as most recently used; return a new identifier', 'read-domain issue in LIVE_BELOW_CAPACITY when exactly 2,047 entries: Register the payload as most recently used; return a new identifier; next phase LIVE_AT_CAPACITY', 'fde04ce0a1eb8fd4872060eb2a5138a5f96684f7636ecb552abadd4628054e0b', 'active', NULL, 447);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-OPM-4', 1, 'outcome', 'local', 'read-domain issue in LIVE_AT_CAPACITY', 'Evict the least recently used entry and release its payload once; register the payload as most recently used; return a new identifier', 'read-domain issue in LIVE_AT_CAPACITY: Evict the least recently used entry and release its payload once; register the payload as most recently used; return a new identifier; next phase LIVE_AT_CAPACITY', '2ff3ec93ed59dc115b5747c84045cdca9a91700cb905e9a45414b4469f299d98', 'active', NULL, 448);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-OPM-5', 1, 'outcome', 'local', 'read-domain issue-or-reuse in LIVE_BELOW_CAPACITY|LIVE_AT_CAPACITY when the match predicate returns true for a live symbol handle payload', 'The first match, most recently used first, becomes most recently used; release the offered payload once; return the existing identifier', 'read-domain issue-or-reuse in LIVE_BELOW_CAPACITY|LIVE_AT_CAPACITY when the match predicate returns true for a live symbol handle payload: The first match, most recently used first, becomes most recently used; release the offered payload once; return the existing identifier; next phase unchanged', '77ec577b794d4de46cf0c8b07a4db2e56633430c7a8bd4f0102c442dd18732ae', 'active', NULL, 449);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-OPM-6', 1, 'outcome', 'local', 'read-domain issue-or-reuse in LIVE_BELOW_CAPACITY|LIVE_AT_CAPACITY when the match predicate returns false for every live symbol handle payload', 'Same result as issue in the current phase', 'read-domain issue-or-reuse in LIVE_BELOW_CAPACITY|LIVE_AT_CAPACITY when the match predicate returns false for every live symbol handle payload: Same result as issue in the current phase; next phase same as issue', '00a67ccf22b35360da1880f6b5d6b86bc30ed58f8ae3920be2e560cec83ec0ec', 'active', NULL, 450);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-OPM-7', 1, 'outcome', 'local', 'read-domain issue-or-reuse in LIVE_BELOW_CAPACITY|LIVE_AT_CAPACITY when the match predicate throws', 'Exception propagates; registry unchanged; offered payload not released', 'read-domain issue-or-reuse in LIVE_BELOW_CAPACITY|LIVE_AT_CAPACITY when the match predicate throws: Exception propagates; registry unchanged; offered payload not released; next phase unchanged', '0fcd42ddae95f903683ea1980e66a345cd5b037b19dabeaf278c561208a49d80', 'active', NULL, 451);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-OPM-8', 1, 'outcome', 'interaction', 'read-domain issue or issue-or-reuse in REGISTRY_DISPOSED', 'Register nothing; call no predicate; release the offered payload once; return the disposed result', 'read-domain issue or issue-or-reuse in REGISTRY_DISPOSED: Register nothing; call no predicate; release the offered payload once; return the disposed result; next phase REGISTRY_DISPOSED', 'd0700bfc70985e17e54ccfb29efc70d93b60b917c30a2f0e68090464a2d0325a', 'active', NULL, 452);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-OPM-9', 1, 'outcome', 'local', 'read-domain lookup in LIVE_BELOW_CAPACITY|LIVE_AT_CAPACITY when live identifier of the requested kind issued by this registry', 'Return the payload; the entry becomes most recently used', 'read-domain lookup in LIVE_BELOW_CAPACITY|LIVE_AT_CAPACITY when live identifier of the requested kind issued by this registry: Return the payload; the entry becomes most recently used; next phase unchanged', '9e1ed9cade7ecb8933a698800251825d6b570edd15af2945cd65c082b2df2f71', 'active', NULL, 453);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-OPM-10', 1, 'outcome', 'local', 'read-domain lookup in LIVE_BELOW_CAPACITY|LIVE_AT_CAPACITY when identifier never issued, evicted, of another kind or issued by another registry', 'Stale for the requested kind (STALE_HANDLE for symbol and read handles, STALE_PAGE for page tokens); recency unchanged', 'read-domain lookup in LIVE_BELOW_CAPACITY|LIVE_AT_CAPACITY when identifier never issued, evicted, of another kind or issued by another registry: Stale for the requested kind (STALE_HANDLE for symbol and read handles, STALE_PAGE for page tokens); recency unchanged; next phase unchanged', '6167e8b9c7f5f19d5c5dcb009dc3256f2945b912dc79ee387fb4ed214b8e8c04', 'active', NULL, 454);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-OPM-11', 1, 'outcome', 'local', 'read-domain lookup in REGISTRY_DISPOSED', 'Stale for the requested kind (STALE_HANDLE or STALE_PAGE)', 'read-domain lookup in REGISTRY_DISPOSED: Stale for the requested kind (STALE_HANDLE or STALE_PAGE); next phase REGISTRY_DISPOSED', 'a61204e5dd109be5be0d82eeb268c20674d71fa7de06b4e632772c7a0c1f760d', 'active', NULL, 455);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-OPM-12', 1, 'outcome', 'local', 'read-domain dispose in LIVE_BELOW_CAPACITY|LIVE_AT_CAPACITY', 'Invalidate every entry; release each live payload once, least recently used first; the first release exception propagates after all releases, later ones suppressed', 'read-domain dispose in LIVE_BELOW_CAPACITY|LIVE_AT_CAPACITY: Invalidate every entry; release each live payload once, least recently used first; the first release exception propagates after all releases, later ones suppressed; next phase REGISTRY_DISPOSED', '19acdbde1960402f64aaddae23755f5619fbd464948c29b7a9174659886bbc36', 'active', NULL, 456);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-OPM-13', 1, 'outcome', 'local', 'read-domain dispose in REGISTRY_DISPOSED', 'No effect', 'read-domain dispose in REGISTRY_DISPOSED: No effect; next phase REGISTRY_DISPOSED', 'd728a2933538f0e3b9388890ce2f27ac6964a2e9e44d6e1ca6f392c898391135', 'active', NULL, 457);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-NBM-0', 1, 'outcome', 'local', 'read-domain null query, name, scope, restriction, path, handle, page token, line or limit component to read argument factories', 'NullPointerException before an argument value exists; absent optional components use explicit factory overloads or empty variants, never null', 'read-domain read argument factories with null query, name, scope, restriction, path, handle, page token, line or limit component: NullPointerException before an argument value exists; absent optional components use explicit factory overloads or empty variants, never null', '1ab5aea2c3f4f3373c0d98614a8fd2e115fc0a06674398313d4b9e4ea53e39b6', 'active', NULL, 458);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-NBM-1', 1, 'outcome', 'local', 'read-domain null any reference component or collection element to read outcome, bound value and handle constructors', 'NullPointerException before the value exists', 'read-domain read outcome, bound value and handle constructors with null any reference component or collection element: NullPointerException before the value exists', 'c3adfa801b89f5566b857ee2fd7e72515e7f422b8fc322163e8640ac2cbe6311', 'active', NULL, 459);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-NBM-2', 1, 'outcome', 'local', 'read-domain null payload, identifier, entry kind, match predicate or release action to registry issue, issue-or-reuse, lookup and dispose', 'NullPointerException before registry mutation', 'read-domain registry issue, issue-or-reuse, lookup and dispose with null payload, identifier, entry kind, match predicate or release action: NullPointerException before registry mutation', '9dfcdbf97762ebff57f6ca4d53c2ccf0ae80194d06ba3835e933e182a7ebb59f', 'active', NULL, 460);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-NBM-3', 1, 'outcome', 'local', 'read-domain null result value to ordering comparators', 'NullPointerException; an absent key component is an explicit empty variant, never null', 'read-domain ordering comparators with null result value: NullPointerException; an absent key component is an explicit empty variant, never null', 'fad18a67c2e8622d55c53c97261d713bb85d2ec7d6848afb9c4f90583062c82a', 'active', NULL, 461);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-TSA-0', 1, 'invariant', 'local', NULL, NULL, 'read-domain prevents: An eighth read operation, a dispatcher operation, or an out-of-bound argument reaching an IntelliJ adapter. Prevention: Sealed read-operation algebra with one record per operation; one controlled factory per operation returns a validated argument or one argument rejection with a closed argument-name enum and a closed reason enum. Residual runtime obligation: Factories run the checks in the SR-001 order; the later codec parses wire JSON into these factories. Justification: The seven-tool ceiling is a product contract; argument values come from an unsound boundary', 'c955c157910aec44ddc765f5de296de4eec0471d37426dc670abf2525c0c8c0d', 'active', NULL, 462);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-TSA-1', 1, 'invariant', 'local', NULL, NULL, 'read-domain prevents: A page, source block or excerpt larger than its bound. Prevention: Bounded result collections and text values validate UTF-8 bytes, UTF-16 units and lines at construction; limits and the collection cap are validated values; a sealed outcome has a TooManyResults variant that holds only a hint. Residual runtime obligation: None in this feature; adapter slices stop collecting at the cap plus one, sort, then slice the page. Justification: Output bounds are I12 correctness requirements, not tuning', '140b57569e84bee05b6d2072a1adc4b8ec588d4e4db92cb6c3932143cda7f40c', 'active', NULL, 463);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-TSA-2', 1, 'invariant', 'local', NULL, NULL, 'read-domain prevents: Unbounded handle growth, an evicted or foreign identifier resolving, an identifier resolving to a payload of another kind, a payload released twice or never, or an entry registered after disposal. Prevention: Final generic registry with a private bounded access-ordered map, identifiers that embed registry identity, one typed key per entry kind so that a lookup returns only that kind''s payload, an opaque payload type parameter, a release callback, an issue-or-reuse operation typed for symbol handle payloads, a sealed lookup outcome and a sealed issue outcome with a disposed variant. Residual runtime obligation: Registry runs each operation atomically; adapters supply the release action and the match predicate. Justification: Eviction order depends on runtime access sequence', '3421557db3f7acb438ddba2b1c10156dd6761f0f930317a17cf297a5abb068dc', 'active', NULL, 464);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-TSA-3', 1, 'invariant', 'local', NULL, NULL, 'read-domain prevents: A read handle whose ranges or version change after issue. Prevention: Final read-handle class with a controlled factory that validates range order, nonnegative offsets and line values of at least 1 and stores immutable ranges and version. Residual runtime obligation: None in this feature; mutation features revalidate the version at commit. Justification: Mutations in later features depend on this evidence', '18fa4e52bb4aa4a6701e9308665215103d1230dbc9dc5795da3c8704da420890', 'active', NULL, 465);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-TSA-4', 1, 'invariant', 'local', NULL, NULL, 'read-domain prevents: PsiElement, VirtualFile, Document, JSON, coroutine or run and lifecycle types in read domain values. Prevention: Separate read domain package; the registry is generic over an adapter payload type. Residual runtime obligation: Architecture test discovers and inspects every compiled read domain class. Justification: Build dependencies and later edits can break layering', 'd872fe1a0256d5bec4f62df2f73c05cd7d2e736d0b8d26f953270cb2487994eb', 'active', NULL, 466);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-TSA-5', 1, 'invariant', 'local', NULL, NULL, 'read-domain prevents: An outcome value whose content changes after construction. Prevention: Outcome values are final classes or records that copy collections into unmodifiable lists at construction and accept only domain component types. Residual runtime obligation: Architecture test (AC-018) and value test (AC-023). Justification: I13 requires accepted content that later state cannot change', '9a809da33d06b9c9704699f685cad24dd48654392ef5b33b56070f32c7fc2e21', 'active', NULL, 467);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-TSA-6', 1, 'invariant', 'interaction', NULL, NULL, 'read-domain prevents: An identifier resolving after disposal, a payload released twice, or an entry registered after disposal. Prevention: Registry identity embedded in identifiers; a disposed registry state that returns stale lookups and the disposed issue result. Residual runtime obligation: The session owner slice calls dispose at New Session and content close. Justification: Session lifetime is owned by tool-window content (SESSION_OWNER)', '3078273166db478aba38b054b46c70f53e39525abd6144f5f336eec18fc8da73', 'active', NULL, 468);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-TSA-7', 1, 'invariant', 'local', NULL, NULL, 'read-domain prevents: Order that depends on index iteration or hash order. Prevention: Ordered immutable result lists and one comparator per operation. Residual runtime obligation: None in this feature; adapter slices sort collected results with these comparators. Justification: Stable order is required for truthful paging and cache stability', 'a8149c53a75ccf264a8871a1df839044ad947df85ebaa67e3df409cebe02400a', 'active', NULL, 469);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-STG-0-entry', 1, 'pre', 'local', NULL, NULL, 'read-domain stage 0 entry requires SR-001, SR-002, EV-SOURCE', '68ed9a2232ce5b06220716d9ea9c073007e1f76bfe4399c9bec846839afdaba5', 'active', NULL, 470);
