INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-STG-1-outcome', 1, 'post', 'local', NULL, NULL, 'read-domain stage 1 outcome: DESIGN_VALID; implementation surface frozen', '900f7d78947d269b651a31b78bc0d9019c14ab6031c5e11c1a56a365a6b4b96c', 'active', NULL, 475);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-STG-2-entry', 1, 'pre', 'local', NULL, NULL, 'read-domain stage 2 entry requires SR-001, SR-002, EV-DESIGN-SOURCE, EV-DESIGN-COMPILE, EV-DESIGN-REVIEW, EV-RECEIPT', '4f22f8fad9b487b908742223e583d0ccd874c26048e11c2ac71b2832be2439ca', 'active', NULL, 476);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-STG-2-exit', 1, 'post', 'local', NULL, NULL, 'read-domain stage 2 exit requires SR-001, SR-002, SR-012, SR-014, SR-021, SR-022, SR-023, SR-024, EV-FOCUSED, EV-BUILD, EV-IMPLEMENTATION-REVIEW', '867c072e822b211709674232207103c0c8a29b96bb60e555533cc82ded1b7231', 'active', NULL, 477);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RDOM-STG-2-outcome', 1, 'post', 'local', NULL, NULL, 'read-domain stage 2 outcome: CAP-READ-DOMAIN closure qualified', '4415873dedc0b51c59b6a7e8b9b4558c562fa7ff9eb1255df617ee66f778bf57', 'active', NULL, 478);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-SCOPE-1', 1, 'decision', 'local', NULL, NULL, 'read-references scope: find_references with strict method search, reference kinds and target identity, and the prefix regression across all seven reads.', '9a1d243032e00c15171faa215b5fa88f53b52b6592a71cf99c17d6aa3895c5e9', 'active', NULL, 489);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-SCOPE-2', 1, 'pre', 'local', NULL, NULL, 'read-references depends on CAP-READ-SYMBOLS and CAP-READ-TEXT-SEARCH.', '228292b4847bac4e86e6e8188d34a5fd081167443703b6fcb8ebca526fdd4571', 'active', NULL, 490);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-SCOPE-3', 1, 'decision', 'local', NULL, NULL, 'read-references excludes wire JSON argument parsing, tool schemas, the LLM envelope and ToolOutcome rendering; they belong to the codec feature.', 'e966f91882c479d611e960411ed3961339422b52d17d1ee31005a86f62f70917', 'active', NULL, 491);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-NG-0', 1, 'decision', 'local', NULL, NULL, 'read-references out of scope: Wire JSON argument parsing, tool schemas, tool descriptions, the LLM status/code/content envelope and ToolOutcome content rendering', 'c95eb83de74a22231a64b3eb537fa48186881df47e2538621d05b34d5fa80060', 'active', NULL, 492);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-NG-1', 1, 'decision', 'local', NULL, NULL, 'read-references out of scope: Mutations, handle invalidation on agent edits, formatting, diagnostics, build and test execution', '67da06e3c7108cc4ff7d179ae2323671bc9d6f4286af112c1ce25e32ec6dcf73', 'active', NULL, 493);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-NG-2', 1, 'decision', 'local', NULL, NULL, 'read-references out of scope: Regex search, case-insensitive search, glob file patterns and whole-project unscoped text search', '1f199233bcaa0b696b420d381a4470470fc2f187fc75edaed5ceed4045c56118', 'active', NULL, 494);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-NG-3', 1, 'decision', 'local', NULL, NULL, 'read-references out of scope: Semantic support or parity claims for languages other than Java', '87bd2a796e769511dfd64d5197ca73c899eded58a1b2974464a04235c6107ad6', 'active', NULL, 495);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-NG-4', 1, 'decision', 'local', NULL, NULL, 'read-references out of scope: Session owner wiring, New Session UI and tool-window content lifetime integration beyond a registry dispose operation', '5687e0aef046200b2987f31509ffa4239eaa03555482226a597fd9a2dff1719b', 'active', NULL, 496);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-NG-5', 1, 'decision', 'local', NULL, NULL, 'read-references out of scope: Persisting handles, page tokens or read results across sessions', 'be9b1d8081f34947005f2db05ae346d65d6bf5dc076f8067c467fbf4375bfbac', 'active', NULL, 497);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-NG-6', 1, 'decision', 'local', NULL, NULL, 'read-references out of scope: MCP, HTTP, idea-facade or any second index beside IntelliJ', 'ecae7e0f8c4e5171e6f16bdf8573d90109a0a4bfc944ec63300b18c52f2cb7dd', 'active', NULL, 498);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-NG-7', 1, 'decision', 'local', NULL, NULL, 'read-references out of scope: Changing CAP-LIFECYCLE-ADMISSION or CAP-DOMAIN-RUN-DRIVER declarations or semantics', '25c06f7005b6cb74d32f80e9e76c85d80e36e5bb32ea4528a96fc4d13672b217', 'active', NULL, 499);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-NG-8', 1, 'decision', 'local', NULL, NULL, 'read-references out of scope: Requirements, operations and acceptance owned by the other semantic reads slices', '411dcc3ae4a89541caddb945cb40147590988e50adeb18f74c1b52965c6ad531', 'active', NULL, 500);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-AS-0', 1, 'pre', 'local', NULL, NULL, 'read-references assumption: Requirement IDs are unique across the five semantic reads slices, which replace CAP-SEMANTIC-READS. A reference to a requirement outside this spec names the slice that owns it: read-domain SR-001, SR-002, SR-012, SR-014, SR-021, SR-022, SR-023, SR-024; read-pipeline SR-003, SR-004, SR-005, SR-015, SR-016, SR-019, SR-020, SR-026, SR-028; read-text-search SR-010, SR-017; read-symbols SR-006, SR-007, SR-008, SR-011, SR-013, SR-018, SR-025; read-references SR-009, SR-027.', '5cb9b4ee2e9915a2ec6235a4c92bdaaaf1cb3249403c6f51346c31ad095691da', 'active', NULL, 501);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-AS-1', 1, 'pre', 'local', NULL, NULL, 'read-references assumption: IntelliJ JUnit 5 test fixtures for a Java project with editors, libraries, generated and excluded roots, dumb mode and a test reference query executor are available through the IntelliJ Platform Gradle test framework configuration; the design may change plugin-core/build.gradle.kts for this and must keep tests discoverable as @Test methods.', '5a4545732f844d3b69824a38c7f0eeda635ae04db91ed5956cdd1da4da7044c0', 'active', NULL, 502);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-AS-2a', 1, 'pre', 'interaction', NULL, NULL, 'read-references assumes name and file indexes throw IndexNotReadyException in dumb mode.', 'cd28c2e57c23aec5d7f10acdd28788eb306b40c2fd3fe7332f2a6ce406a368bb', 'active', NULL, 503);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-AS-2b', 1, 'pre', 'interaction', NULL, NULL, 'read-references assumes non-dumb-aware reference search executors block until smart mode without read access, so SR-016 calls them inside the read computation.', '3780c272bcf45b155eb96babe0f98dde2c27472f00351cb6eb5bdd4659c4b146', 'active', NULL, 504);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-AS-2c', 1, 'pre', 'interaction', NULL, NULL, 'read-references assumes dumb-mode entry runs a write action that cancels a running non-blocking read computation, which reruns only when its constraints hold again.', 'a0106882381d3734d26015d858f86c0b6db47e120c94af3db23a667a33e2900b', 'active', NULL, 505);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-AS-2d', 1, 'pre', 'local', NULL, NULL, 'read-references assumes the platform exposes no partial-result signal for reference search; completeness is only complete or more results.', '244b74e2f673eda2d89e1c898a4dda4a69e74b059d5be94e28d149a4a9bbc60c', 'active', NULL, 506);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-AS-3', 1, 'decision', 'local', NULL, NULL, 'read-references assumption: Normalizations of product terms: SR-025 range, signature, owner and containing-declaration definitions; SR-006 catalog declaration kinds; SR-003 line model and defaults; SR-004 path rendering and check order; SR-010 match and excerpt rule and skipped-file count; SR-020 READ_FAILED category rule; SR-026 failure precedence; SR-001 query validation; SR-004 canonical root comparison; SR-009 reference range, line and kind; SR-010 document offsets and match column; SR-025 parameter type text, array dimensions and compact constructors; SR-012 entry kinds.', '4f3a081a9525034bbde75113bf6d4183fef9df27637a5052bfd7caad9221b706', 'active', NULL, 507);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-AS-4', 1, 'decision', 'local', NULL, NULL, 'read-references assumption: Normalizations of scope: generated sources are omitted from find_file, unrestricted search_symbols and search_text directory scans, and included and marked in find_references so reference sets stay complete; handle reuse for the same element (SR-011) keeps one live handle per element in the registry.', '65fdf9c67d27f383e1f9e1a3d037009ca223703135c3ff6bad1da9fac7ca3497', 'active', NULL, 508);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-AS-5', 1, 'decision', 'local', NULL, NULL, 'read-references assumption: The product rule ''reports partial search/index readiness separately'' is satisfied by fail-closed INDEX_NOT_READY and TOO_MANY_RESULTS outcomes, because the platform gives no partial-result signal.', 'a57461cba553b751b02eaa2e77101dbf993a7087837b1b89a26496f1cb3ab209', 'active', NULL, 509);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-AS-6', 1, 'pre', 'local', NULL, NULL, 'read-references assumption: Java short-name stub lookups hide library source files unless library sources are included (JavaSourceFilterScope.java:36-51). A project reference to a compiled library class or method is equivalent to the declaration in its attached source (PsiClassImplUtil.java:1162-1228,1251-1273), so find_references on a library source handle finds project references.', '10ca782b6607481f88d62649e865c9b7458dcaebfd67064dd7fc028465b3c6cb', 'active', NULL, 510);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-REQ-SR009-1', 1, 'pre', 'local', NULL, NULL, 'find_references takes a symbol handle and a scope PROJECT (default) or LIBRARIES with the SR-005 meaning, except that references inside generated sources are included and marked generated.', '9ca90d62132f2dabebd7b2adf9fcd86e0aed8e6ae4de63839a0e389cb285902b', 'active', NULL, 511);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-REQ-SR009-2', 1, 'post', 'local', NULL, NULL, 'find_references: It returns every platform PsiReference in scope that resolves to the element, including import statements, Javadoc references ({@link}, @see) and references from non-Java files.', 'be4891946094760e1a2fe8a13b843407ad4a3a751c772d2d4f5618a64ff669d7', 'active', NULL, 512);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-REQ-SR009-3', 1, 'invariant', 'local', NULL, NULL, 'find_references: A reference that resolves to a compiled library declaration is a reference to the equivalent declaration in its attached library source.', '3fc29c097b5f2d71eb5e358f306e40e8fb5aba9e78294563ffb034df34730981', 'active', NULL, 513);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-REQ-SR009-4', 1, 'invariant', 'local', NULL, NULL, 'find_references: Method search is strict: calls through a super method, calls to overriding methods and calls to overloads are not references to the handle''s method.', '2049a2a8a75f34cf48737f4d26c66061513e6c6f6ed3bb876d7b5ae4d4e7b07e', 'active', NULL, 514);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-REQ-SR009-5', 1, 'post', 'local', NULL, NULL, 'find_references: Every page carries the re-resolved target identity (kind, name, qualified owner, signature, declaration range and current document version, as in SR-008) and the scope used.', '37946c44d27ef006d9fad438132acca16c4e6e81c36db4cbb72bd059769cc15e', 'active', NULL, 515);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-REQ-SR009-6', 1, 'post', 'local', NULL, NULL, 'find_references: Each reference has rendered path, a range of 0-based start and end-exclusive UTF-16 document offsets (the reference element start offset plus the reference range in that element), the 1-based line of the range start, a line excerpt (SR-010 excerpt rule with the range start as match start), a generated flag, a kind and the containing declaration (SR-025), absent when no catalog declaration encloses the reference.', '1347266cc2ff69b6f1b711f2bda4d74a4135156bb00ce05f1a7b0fb18310215e', 'active', NULL, 516);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-REQ-SR009-7', 1, 'invariant', 'local', NULL, NULL, 'find_references: The kind is IMPORT for a reference inside a Java import statement, DOC for a reference inside a Java doc comment, and CODE otherwise.', '2b0307cca56889fa5a50d2bb84414e94d2d563e5550f275f0cdc6f199604c706', 'active', NULL, 517);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-REQ-SR009-8', 1, 'invariant', 'local', NULL, NULL, 'find_references: Unresolved text in comments or string literals and identifiers that resolve to a different element are not references.', 'cafe4e5085907c9067a1eddad2a670c5cd0736a87f2607746a2c08b798cb4d90', 'active', NULL, 518);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-REQ-SR009-9', 1, 'invariant', 'local', NULL, NULL, 'find_references: Results are ordered by rendered path, then start offset.', 'f43f994db59977fc525ca6782ee66017f474ea849faed7b82f5dd475735e68db', 'active', NULL, 519);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-REQ-SR009-10', 1, 'outcome', 'local', 'find_references results exceed collection cap', 'TOO_MANY_RESULTS with narrowing hint, no page', 'find_references with more results than the result collection cap returns TOO_MANY_RESULTS with a narrowing hint and no page.', '3c29dbc18206eb2c4b6f8f8e817080d6d74607919633cb56bedfc86952019565', 'active', NULL, 520);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-REQ-SR027-1', 1, 'invariant', 'interaction', NULL, NULL, 'Milestone closure: all seven read operations run through the frozen run driver in one fixture, and their rendered outcomes appended through CacheGeneration keep the prefix invariant across editor text changes, reindexing and file deletion.', 'bd02f05f6d1e6e68f7344682c188650c858978176d50443df460db2e16d3461d', 'active', NULL, 521);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-REQ-SR027-2', 1, 'invariant', 'local', NULL, NULL, 'Read outcome values produced before IDE state changes stay equal to copies taken when they were produced.', '1b066da8717d259cb33b5018636fee1ce38c246068dfb1f147fe22d7ef93fbda', 'active', NULL, 522);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-ACC-0', 1, 'outcome', 'local', 'two unrelated same-simple-name classes, one referenced', 'separate candidates; exact references for each', 'search_symbols returns two same-simple-name classes as separate candidates with different qualified owners; find_references returns exactly the referenced class''s references and a complete empty page for the other.', 'a31c625590d9eadd6acfe2746ec6499a483f6f94e6a1698e22ff29526b6d472e', 'active', NULL, 523);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-ACC-1', 1, 'outcome', 'local', 'find_references on Derived.m, Base.m, Util.u, Util with overrides, overloads, text and non-Java references', 'strict resolved references with kinds, generated flag and target identity', 'find_references acceptance: strict method search, IMPORT/DOC/CODE kinds, generated flag, non-Java references, target identity and PROJECT scope on every page, ranges start at the referenced name.', 'fedc50494826bbf9d7fe6caf9101faa223df2deb21fd7b25fb2bc1196783bd4c', 'active', NULL, 524);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-ACC-2', 1, 'outcome', 'interaction', 'read outcomes appended across editor change, reindex and file deletion', 'every request extends previous bytes exactly; earlier outcomes unchanged', 'Appending read outcomes across editor changes, reindexing and file deletion: every consecutive request extends the previous bytes exactly and earlier outcomes equal their copies.', '6e8f0dd717c765a7e53b8dd20f720a3e91e4b0f89a98785b1c042cdbc49f39cc', 'active', NULL, 525);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-ACC-3', 1, 'outcome', 'interaction', 'dumb mode starts during find_references', 'INDEX_NOT_READY past the bound; complete list after restart within the bound', 'Dumb mode during find_references: past the index wait bound returns INDEX_NOT_READY with no partial references; leaving dumb mode before the bound returns the complete list after restart.', 'a1f16f34a9dab326f674b09e7e7c9225b6bb44e942344084f8b54cf272e18076', 'active', NULL, 526);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-ACC-4', 1, 'outcome', 'local', 'find_references page two after unsaved edit', 'STALE_PAGE', 'find_references paging: unchanged state continues deterministically to a complete final page, a repeated token returns the same page, and a request after an unsaved project edit returns STALE_PAGE.', '6ed9f6a589a47b34c14535e97b6ec662ecff20ae471ff2df0e3ad1ecc1a4616a', 'active', NULL, 527);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-ACC-6', 1, 'outcome', 'local', 'find_references PROJECT on library source handles', 'project reference resolving to the compiled declaration', 'find_references on library source class and method handles in PROJECT scope returns the project reference that resolves to the compiled declaration.', 'f1a53e86d9e9ec17ce19b9ccae28aa4bd3bc3aa9a06bfdcbf1205dc291411c36', 'active', NULL, 528);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-ACC-7', 1, 'outcome', 'local', 'reference query executor throws with source text', 'READ_FAILED category INDEX_QUERY, no source text in outcome or log', 'A reference search exception returns READ_FAILED with category INDEX_QUERY; outcome and log contain no source text, argument or stack content.', 'ac9d642a1168d42ad0449f77a1a0e3e97cf0c3bb058542a81fe4ece51a115497', 'active', NULL, 529);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-DEC-reference_set', 1, 'decision', 'local', NULL, NULL, 'Decision reference_set: all resolved PSI references with strict method search.', 'd386db2d3cdbac30b55f623f7d32073214a0f31df4ffc1d6fba0a5c7a3858bb4', 'active', NULL, 565);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-DEC-reference_target_identity', 1, 'decision', 'local', NULL, NULL, 'Decision reference_target_identity: every find_references page carries target identity and scope.', 'aec8cfea9c0c9657be56185b8e771eeab4490bc22e3a7e980790d21ab4a87950', 'active', NULL, 566);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-OPM-3', 1, 'post', 'local', NULL, NULL, 'find_references when the handle resolves and references exist: every page carries target identity and scope, with references in SR-024 order.', '0b34776019c933177ab84b7786d0c78808199b847608c66d01030c38a3eb7eba', 'active', NULL, 579);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-NBM-0', 1, 'outcome', 'local', 'nullable platform return in a read adapter', 'named outcome, never null', 'read-references: a nullable platform return (missing document, file or resolved element) becomes a named outcome (FILE_NOT_FOUND, UNSUPPORTED_FILE, STALE_HANDLE), never a null in a domain value.', 'c69658c7ee15f9f7a421a3ad3e3c1d118ebc99e8afce024bc4029e4e6a704453', 'active', NULL, 581);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-TSA-0', 1, 'invariant', 'local', NULL, NULL, 'Reference entries are constructed only by the adapter with a closed kind enum and generated flag; the adapter uses platform reference search with strict method search, element-offset ranges and kind from the enclosing import or doc comment, so text occurrences, unrelated same-name symbols and super-method calls are never reported.', 'f41f9377770100803c6a8461d20819e3e0bee4c7e9944efb3665a5b53588e232', 'active', NULL, 582);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-TSA-1', 1, 'invariant', 'local', NULL, NULL, 'Milestone closure needs a prefix regression over all seven reads across changing IDE state; immutable outcome values and single rendering by CacheGeneration are the only type-level prevention.', '1427bf055bac6e2b5da106ee2d87b64142ba517ffc4866ea5a731646904f6832', 'active', NULL, 583);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-STG-0-entry', 1, 'pre', 'local', NULL, NULL, 'read-references stage 0 (spec) entry needs SR-009, SR-027 and evidence EV-SOURCE.', '37874a6806d85b757e1c7f4fe4d785e1035cf48234a4a8eb3be997a6075bd35e', 'active', NULL, 584);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-STG-0-exit', 1, 'post', 'local', NULL, NULL, 'read-references stage 0 (spec) exit needs SR-009, SR-027 and evidence EV-STRUCTURE, EV-SPEC-REVIEW; outcome: SPEC_VALID for the exact normalized feature basis; no design or implementation claim', '1e57be5098b9873c9391bd65855d7c38cbc82e90abaaede92637e974a16fc1e2', 'active', NULL, 585);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-STG-1-entry', 1, 'pre', 'local', NULL, NULL, 'read-references stage 1 (design) entry needs SR-009, SR-027 and evidence EV-STRUCTURE, EV-SPEC-REVIEW.', '8e8436ab0b640ddb4a756f9a6c1c3e817de38ced5ff2ddd0adfbfb53eff8ba03', 'active', NULL, 586);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-STG-1-exit', 1, 'post', 'local', NULL, NULL, 'read-references stage 1 (design) exit needs SR-009, SR-027 and evidence EV-DESIGN-SOURCE, EV-DESIGN-COMPILE, EV-DESIGN-REVIEW, EV-RECEIPT; outcome: DESIGN_VALID; implementation surface frozen', 'de5a7e2afcd6f57fe334bfc55c46453f52472051e9420c3b9ecca1db842706f2', 'active', NULL, 587);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-STG-2-entry', 1, 'pre', 'local', NULL, NULL, 'read-references stage 2 (implementation) entry needs SR-009, SR-027 and evidence EV-DESIGN-SOURCE, EV-DESIGN-COMPILE, EV-DESIGN-REVIEW, EV-RECEIPT.', 'b3de79dc00f609eb5d8b29e1cbd34d070f252fc0a97bbffc114604891f3cb92d', 'active', NULL, 588);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RREF-STG-2-exit', 1, 'post', 'local', NULL, NULL, 'read-references stage 2 (implementation) exit needs SR-009, SR-027 and evidence EV-IDE, EV-PREFIX, EV-BUILD, EV-IMPLEMENTATION-REVIEW; outcome: CAP-READ-REFERENCES closure qualified', '9a9d9469efb03e7a6423c6f1c97051f36819f2d7f7718937373030130ad7469d', 'active', NULL, 589);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-SCOPE-1', 1, 'decision', 'local', NULL, NULL, 'Literal text search and pagination: search_text over current document text and page-token continuation and staleness for every paged read.', '67c723d0eccdfd485caa870e5ce6556d241b5c11043f4e5775a3a7f6c53ffdb7', 'active', NULL, 601);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-SCOPE-2', 1, 'pre', 'local', NULL, NULL, 'CAP-READ-TEXT-SEARCH depends on CAP-READ-PIPELINE.', 'bc1d8b67385722713dddc38f2e9ec5effb7197452a82b18cc85b62181a38e1e3', 'active', NULL, 602);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-SCOPE-3', 1, 'decision', 'local', NULL, NULL, 'Wire JSON argument parsing, tool schemas, the LLM status/code/content envelope and rendering of read outcomes into ToolOutcome content are excluded and belong to the codec feature.', '3b1cbf76b02a6cfa4773663534ec2e4a4f563d56eb0c13f378faec4ae2f60ba3', 'active', NULL, 603);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-NG-0', 1, 'decision', 'local', NULL, NULL, 'Out of scope: Wire JSON argument parsing, tool schemas, tool descriptions, the LLM status/code/content envelope and ToolOutcome content rendering', '18121ca2d4c5c24ab0694825b402807a410935fbaf1c5caa639c2980affeb490', 'active', NULL, 604);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-NG-1', 1, 'decision', 'local', NULL, NULL, 'Out of scope: Mutations, handle invalidation on agent edits, formatting, diagnostics, build and test execution', '9f7bbeeb3194c79a8b4c262d2e5f950b2f3f4648f2940e5bd4819ff2202e11ec', 'active', NULL, 605);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-NG-2', 1, 'decision', 'local', NULL, NULL, 'Out of scope: Regex search, case-insensitive search, glob file patterns and whole-project unscoped text search', 'fcdcee78c2f45f49a3ea92b2c93f24af7d897144fdc47f7305aaf36e746f9fda', 'active', NULL, 606);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-NG-3', 1, 'decision', 'local', NULL, NULL, 'Out of scope: Semantic support or parity claims for languages other than Java', 'aacf8f6bce776e3c1eaff0cfbfb469d00fb45c63098f218f3fd6ba81ac853ee9', 'active', NULL, 607);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-NG-4', 1, 'decision', 'local', NULL, NULL, 'Out of scope: Session owner wiring, New Session UI and tool-window content lifetime integration beyond a registry dispose operation', '9750e474a2422e598bab5c5a71518081e8cee15c74c8e613f1e2b4cda5fa13e1', 'active', NULL, 608);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-NG-5', 1, 'decision', 'local', NULL, NULL, 'Out of scope: Persisting handles, page tokens or read results across sessions', 'cd9c3dad6b3decd95a15019c3e3c2c00a49e050f49aa6b0c4ec688eb77c04f28', 'active', NULL, 609);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-NG-6', 1, 'decision', 'local', NULL, NULL, 'Out of scope: MCP, HTTP, idea-facade or any second index beside IntelliJ', '2d582bd7b4870bc64400c2c3e0da18f4a24bf0eeec73967fe5b1513ca5b1e281', 'active', NULL, 610);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-NG-7', 1, 'decision', 'local', NULL, NULL, 'Out of scope: Changing CAP-LIFECYCLE-ADMISSION or CAP-DOMAIN-RUN-DRIVER declarations or semantics', '5c9796178212ae5ca53121b2dc0cabc8e18238ae80b85713cf366cdc01ab9393', 'active', NULL, 611);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-NG-8', 1, 'decision', 'local', NULL, NULL, 'Out of scope: Requirements, operations and acceptance owned by the other semantic reads slices', '97a4ba8bcb4c540cceb4d5da1a6cf400972b8fd8fc34d26b79bd495a243fb60f', 'active', NULL, 612);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-AS-0', 1, 'pre', 'local', NULL, NULL, 'Requirement IDs are unique across the five semantic reads slices, which replace CAP-SEMANTIC-READS. A reference to a requirement outside this spec names the slice that owns it: read-domain SR-001, SR-002, SR-012, SR-014, SR-021, SR-022, SR-023, SR-024; read-pipeline SR-003, SR-004, SR-005, SR-015, SR-016, SR-019, SR-020, SR-026, SR-028; read-text-search SR-010, SR-017; read-symbols SR-006, SR-007, SR-008, SR-011, SR-013, SR-018, SR-025; read-references SR-009, SR-027.', '58ace15e7bd643216a2d3ec04fb43d697b6d7732e9541d96e2188c13e4531c64', 'active', NULL, 613);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-AS-1', 1, 'pre', 'local', NULL, NULL, 'IntelliJ JUnit 5 test fixtures for a Java project with editors, libraries, generated and excluded roots, dumb mode and a test reference query executor are available through the IntelliJ Platform Gradle test framework configuration; the design may change plugin-core/build.gradle.kts for this and must keep tests discoverable as @Test methods.', '0878852c371704ab726c89cb058292f363aa5cf934d9602b3ae7da9ec297bc32', 'active', NULL, 614);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-AS-2', 1, 'pre', 'local', NULL, NULL, 'Only the document modification stamp changes on unsaved edits; the view provider stamp stays at the last committed stamp. The PSI modification count changes on committed physical PSI changes and on dumb-mode entry and exit, not on uncommitted edits.', '75772b252c74d6676ee47434c0b725682bd86bcddc15a01b68aa45d5aa1abea8', 'active', NULL, 615);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-AS-3', 1, 'pre', 'local', NULL, NULL, 'Normalizations of product terms: SR-025 range, signature, owner and containing-declaration definitions; SR-006 catalog declaration kinds; SR-003 line model and defaults; SR-004 path rendering and check order; SR-010 match and excerpt rule and skipped-file count; SR-020 READ_FAILED category rule; SR-026 failure precedence; SR-001 query validation; SR-004 canonical root comparison; SR-009 reference range, line and kind; SR-010 document offsets and match column; SR-025 parameter type text, array dimensions and compact constructors; SR-012 entry kinds.', 'ece4e801dab955bf5532befd35f8efadbdabc00d3ba111f3999df3366e336fe6', 'active', NULL, 616);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-AS-4', 1, 'pre', 'local', NULL, NULL, 'Normalizations of scope: generated sources are omitted from find_file, unrestricted search_symbols and search_text directory scans, and included and marked in find_references so reference sets stay complete; handle reuse for the same element (SR-011) keeps one live handle per element in the registry.', '5bd34704118aeda50fb69275b48522b331063c5dd0ea27b8686305402f315362', 'active', NULL, 617);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-AS-5', 1, 'pre', 'local', NULL, NULL, 'The product rule ''reports partial search/index readiness separately'' is satisfied by fail-closed INDEX_NOT_READY and TOO_MANY_RESULTS outcomes, because the platform gives no partial-result signal.', '51783040101f97d9e4bb0dcc159d7a24c8a60d453fe3fa29edd1e57795c60609', 'active', NULL, 618);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-AS-6', 1, 'pre', 'local', NULL, NULL, 'The PSI modification count also changes for document and VFS changes to project-content files whose PSI is not loaded (PsiDocumentManagerBase.java:1149,1314; PsiVFSListener.java:139-148), so SR-017 staleness covers find_file and search_text over unloaded files.', '45f53866faade2182bc5f435c0afed37a3bd716a58eb1eb09f6b6c0fa12cc4b9', 'active', NULL, 619);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-REQ-SR010-1', 1, 'pre', 'local', NULL, NULL, 'search_text takes a required scope path (SR-004) and a literal query (SR-001), matched case-sensitively; regex is excluded.', '42812048daa66be9e584fb0ddb7a22e6e8acfaf1ac7cc59b88b4b463a6ef32bc', 'active', NULL, 620);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-REQ-SR010-2', 1, 'post', 'local', NULL, NULL, 'A directory scope searches its files recursively and omits excluded, generated and binary files; text files too large for content loading are omitted and counted in a skipped-file count carried on every page.', '82d6bbefdbc5f178c2a155a51eaa940e27c078c3c20b35566ff5e15c098b8278', 'active', NULL, 621);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-REQ-SR010-3', 1, 'outcome', 'local', 'search_text binary or non-text file scope', 'UNSUPPORTED_FILE', 'A file scope searches that file; a binary file scope, or a file scope that the platform does not load as text content, returns UNSUPPORTED_FILE.', '4abad00368b9c5863445134132b9352a2a2b46241c06d7d84f90231354c727a3', 'active', NULL, 622);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-REQ-SR010-4', 1, 'invariant', 'local', NULL, NULL, 'The search reads current document text, including unsaved changes.', '8db0e039ddae71b71ecab4effe75e68b805d2167b55a18322221ae3d2f0384fd', 'active', NULL, 623);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-REQ-SR010-5', 1, 'post', 'local', NULL, NULL, 'Each non-overlapping match, scanned left to right, is one result with rendered path, 1-based line, start and end offsets as 0-based end-exclusive UTF-16 document offsets, and an excerpt.', '411be184a644e69e35308718689e247b93e36afcec69d124a7c702f41c922850', 'active', NULL, 624);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-REQ-SR010-6', 1, 'invariant', 'local', NULL, NULL, 'The match column is the match start offset minus the start offset of its line.', 'c6aab83fd5a6aa1384d9ed0d8d926e72a2cc4d6e4672f6c7f1789fd84c5f2646', 'active', NULL, 625);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-REQ-SR010-7', 1, 'invariant', 'local', NULL, NULL, 'The excerpt is the whole line when it has at most 500 UTF-16 code units; otherwise it is the 500-unit window starting at column max(0, min(matchColumn − 100, lineLength − 500)) with truncated set, shortened by one unit at each end that splits a surrogate pair.', '271667a86a248746e48df0c12dd5aeaaac0d5128f1c4aad0f0a2132165b6b35c', 'active', NULL, 626);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-REQ-SR010-8', 1, 'invariant', 'local', NULL, NULL, 'Results are ordered by rendered path, then start offset.', '9c4f0e66c19934c3c5d3e1f31a0bb6e87d30ce3ffa9b3f4007702cecb9d843bf', 'active', NULL, 627);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-REQ-SR010-9', 1, 'outcome', 'local', 'search_text results exceed the collection cap', 'TOO_MANY_RESULTS with narrowing hint, no page', 'Paged collection applies the result collection cap (SR-002): more results than the cap returns TOO_MANY_RESULTS with a narrowing hint and no page.', '550d703744a442c0ecc7de8f5b0fd47276035ffa78d147159cf819cd363a5d4d', 'active', NULL, 628);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-REQ-SR017-1', 1, 'decision', 'local', NULL, NULL, 'The paged operations are find_file, search_symbols, get_file_outline, find_references and search_text.', 'b9df8e9762ab71b38d6497f633c5c75c953d3019c631d836010f724cb9b75764', 'active', NULL, 629);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-REQ-SR017-2', 1, 'invariant', 'local', NULL, NULL, 'A page result is either complete or has more results with a next-page token.', '450b2572200b47a4c391e8568bab02038bcca36962233924979a59aae19525d4', 'active', NULL, 630);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-REQ-SR017-3', 1, 'invariant', 'local', NULL, NULL, 'A page token is a registry entry (SR-012) bound to the operation, the full argument set without the token, the session registry, the PSI modification count observed when the first page was computed, and the next offset.', '3388319edfd4ac17011cc2f7044043a091d00c5c88909b477b2af82942d97133', 'active', NULL, 631);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-REQ-SR017-4', 1, 'pre', 'local', NULL, NULL, 'A next-page request repeats the argument set and adds the token; a different limit is a different argument set.', 'e7fc4522c0c3702b2a4919086c4e9f4b7c4ed90210aca8fd26453758f2dfe129', 'active', NULL, 632);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-REQ-SR017-5', 1, 'post', 'local', NULL, NULL, 'Each page result that has more results issues a new token for the following page.', '80a342b57df90cde4ef27784c854cd67a2ff543b15137763e8b54fe3b5d82a44', 'active', NULL, 633);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-REQ-SR017-6', 1, 'post', 'local', NULL, NULL, 'A token stays valid after use: while it is live and still matches, a repeated request with it returns the same page again.', '932fdcba82842af68aadf8ec93ce42e689d69ccba29f734b4582bb95d97bb491', 'active', NULL, 634);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-REQ-SR017-7', 1, 'outcome', 'local', 'next-page token unknown, evicted, foreign or mismatched, or PSI modification count differs', 'STALE_PAGE', 'A next-page request returns STALE_PAGE when the token is unknown, evicted, of another kind or from another registry, when the operation or argument set differs, or when the PSI modification count differs.', 'f998dfe5a45d0cd8c6672fe30f47ad1daba7ee32b9f66224bbe65a4e8df10fe9', 'active', NULL, 635);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-REQ-SR017-8', 1, 'invariant', 'local', NULL, NULL, 'The count is compared before any wait for indexing (SR-026), in a read computation with documents committed, and again inside the operation''s read computation.', 'a209b5f08590317f6ca2156a75529dfdd9df6b3957c7b86e7fac1b1afe30be42', 'active', NULL, 636);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-REQ-SR017-9', 1, 'invariant', 'local', NULL, NULL, 'Because computations run with committed documents (SR-015), unsaved edits change the count.', '3b7e1bf286ebb380a6a89b0325e09090a66a6f25c3b6317a1922a50f6f183776', 'active', NULL, 637);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-REQ-SR017-10', 1, 'outcome', 'local', 'indexing between pages', 'STALE_PAGE without index wait', 'Dumb-mode entry and exit also change the count, so indexing between pages returns STALE_PAGE by design, without a wait.', '62acc9e01f93aab95c8ddc4edafdccc2bb91d37095a47bac924fad92f8e9b374', 'active', NULL, 638);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-REQ-SR017-11', 1, 'invariant', 'local', NULL, NULL, 'Ordering is deterministic within one modification count.', 'f0fd065ee9fa20cc91581ec82dec8440554f41babfb1df6df7c60560674a0a3f', 'active', NULL, 639);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-ACC-0', 1, 'outcome', 'local', 'search_text a literal in a directory scope where matches differ by case, one match is in an unsaved editor, one file is generated, one is excluded, one is binary, one text file exceeds the content-loading limit, one line holds two non-overlapping matches, and one match starts at column 800 of a 2,000-unit line; also search_text with the binary file and with the file above the content-loading limit as the file scope.', 'Only case-sensitive matches in current document text are returned; generated, excluded and binary files are absent; the skipped-file count is 1; the two matches on one line are two results; each result''s start and end are document offsets; the long-line excerpt is the 500-unit window starting at column 700 with truncated set; both file scopes return UNSUPPORTED_FILE.', 'When: search_text a literal in a directory scope where matches differ by case, one match is in an unsaved editor, one file is generated, one is excluded, one is binary, one text file exceeds the content-loading limit, one line holds two non-overlapping matches, and one match starts at column 800 of a 2,000-unit line; also search_text with the binary file and with the file above the content-loading limit as the file scope. Then: Only case-sensitive matches in current document text are returned; generated, excluded and binary files are absent; the skipped-file count is 1; the two matches on one line are two results; each result''s start and end are document offsets; the long-line excerpt is the 500-unit window starting at column 700 with truncated set; both file scopes return UNSUPPORTED_FILE.', '5871303742f126465467367d9973a535aa26356f6a085a65ed60a92e2a4bac36', 'active', NULL, 640);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-ACC-1', 1, 'outcome', 'local', 'Hold smart mode constant. Request page one of search_text with limit 1, request page two without a change, repeat the page-two request with the same token, then make an unsaved document edit in the project and request page two again; reuse a token with a different limit, with find_file and in a new registry. Separately, with the index wait bound injected as 200 ms, request page one of search_text, enter dumb mode, and request page two.', 'Unchanged state continues in deterministic order to a complete final page, and the repeated page-two request returns the same page again; every page result with more results carries a page token that differs from every token issued before it, including the token of the first page-two result; the request after the unsaved edit, the different limit, the other operation and the new registry return STALE_PAGE; the request after dumb-mode entry returns STALE_PAGE before 200 ms elapse.', 'When: Hold smart mode constant. Request page one of search_text with limit 1, request page two without a change, repeat the page-two request with the same token, then make an unsaved document edit in the project and request page two again; reuse a token with a different limit, with find_file and in a new registry. Separately, with the index wait bound injected as 200 ms, request page one of search_text, enter dumb mode, and request page two. Then: Unchanged state continues in deterministic order to a complete final page, and the repeated page-two request returns the same page again; every page result with more results carries a page token that differs from every token issued before it, including the token of the first page-two result; the request after the unsaved edit, the different limit, the other operation and the new registry return STALE_PAGE; the request after dumb-mode entry returns STALE_PAGE before 200 ms elapse.', '3b75be361d19558f61140d5aa074013eab31b9b6fbe4cb437f271046c9e5ab30', 'active', NULL, 642);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-ACC-2', 1, 'outcome', 'local', 'With the result collection cap injected as 3, call search_text for a literal with 4 matches, and for a literal with 3 matches and limit 2.', 'The first returns TOO_MANY_RESULTS with a narrowing hint and no page; the second returns a page of 2 with a next-page token and then a complete page of 1.', 'When: With the result collection cap injected as 3, call search_text for a literal with 4 matches, and for a literal with 3 matches and limit 2. Then: The first returns TOO_MANY_RESULTS with a narrowing hint and no page; the second returns a page of 2 with a next-page token and then a complete page of 1.', '7e2af3e98907659bcb8fe64cbda25fd45e84d168700da100dbbbc95d97bf403e', 'active', NULL, 644);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-DEC-pagination', 1, 'decision', 'local', NULL, NULL, 'Decision pagination: PSI_MODIFICATION_COUNT_BOUND_TOKEN_STALE_PAGE', 'fd7c0f94e145b66cfb57eabe7ea0e34e6de5849f663ef2d8fe86f1e8dfd1c219', 'active', NULL, 671);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-DEC-search_text_matching', 1, 'decision', 'local', NULL, NULL, 'Decision search_text_matching: LITERAL_CASE_SENSITIVE_500_CHAR_EXCERPT', '61621825ec92931aa68fe55f374a0af2041515b8edb0ce5b71dbe113ee82cf04', 'active', NULL, 672);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-DEC-page_token_reuse', 1, 'decision', 'local', NULL, NULL, 'Decision page_token_reuse: REPLAYABLE_WHILE_LIVE_NEW_TOKEN_PER_PAGE', '5a2346ebab7473dfb984489adbdb5f5b724e415098505625b527049daa93b950', 'active', NULL, 673);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-DEC-page_staleness_precedence', 1, 'decision', 'local', NULL, NULL, 'Decision page_staleness_precedence: COUNT_CHECK_BEFORE_INDEX_WAIT', '461cb41260418bce458b52ad8655dc6aa71ca765af452607a0ff4bf64f2d1932', 'active', NULL, 674);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-OPM-0', 1, 'outcome', 'local', 'next page when token live and PSI modification count, operation, arguments and registry match', 'Next page in deterministic order', 'next page (SMART) when token live and PSI modification count, operation, arguments and registry match: Next page in deterministic order; phase SMART', '221d54a3128f1cb6992884ae4ab842b5fa3c26a75f7dfab263ab65173c8ae57a', 'active', NULL, 678);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-OPM-1', 1, 'outcome', 'local', 'next page when token already used, still live, and PSI modification count, operation, arguments and registry match', 'Same page again with a new next-page token when more results exist', 'next page (SMART) when token already used, still live, and PSI modification count, operation, arguments and registry match: Same page again with a new next-page token when more results exist; phase SMART', '78df6bc77f9a47c376aee8d3f0a578949d50a616ddb843299c394e2c66f7f2fa', 'active', NULL, 682);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-OPM-2', 1, 'outcome', 'local', 'next page when token unknown, evicted, wrong-kind, foreign, or operation or arguments differ', 'STALE_PAGE; restart from page one; no wait for indexing', 'next page (SMART|INDEXING) when token unknown, evicted, wrong-kind, foreign, or operation or arguments differ: STALE_PAGE; restart from page one; no wait for indexing; phase unchanged', '7b511f8d3ea856256534f99e944ccbb847500ed7b0bfa80c0d4328385fd166cd', 'active', NULL, 686);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-OPM-3', 1, 'outcome', 'local', 'next page when token matches but PSI modification count changed, including by a dumb-mode transition', 'STALE_PAGE without waiting for indexing; restart from page one', 'next page (SMART|INDEXING) when token matches but PSI modification count changed, including by a dumb-mode transition: STALE_PAGE without waiting for indexing; restart from page one; phase unchanged', '640902c62f6c86db292d460d274490f692cfcc53e36fd76b73a8433018362a1e', 'active', NULL, 690);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-NBM-0', 1, 'outcome', 'local', 'nullable platform return such as missing document, file or resolved element', 'Named outcome (FILE_NOT_FOUND, UNSUPPORTED_FILE, STALE_HANDLE); never a null in a domain value', 'read adapter platform results with nullable platform return such as missing document, file or resolved element: Named outcome (FILE_NOT_FOUND, UNSUPPORTED_FILE, STALE_HANDLE); never a null in a domain value', '9d16b23efacb96cddd08faad83b2d36f5ee2293e4aecce3f7579ef7db8d3868b', 'active', NULL, 692);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-TSA-0-INVALID', 1, 'invariant', 'local', NULL, NULL, 'Never representable or produced: Regex or case-insensitive matching, a whole-project scan without explicit scope, stale disk text, an excerpt that does not contain its match start, or a silent empty result for an unreadable file scope', 'b3ddc0ddaf94155d93385d402df17d652004d781b646709d1f1bac9dc63eda94', 'active', NULL, 693);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-TSA-0-TYPE', 1, 'invariant', 'local', NULL, NULL, 'Literal query value and required scope component; no regex or case option exists in the argument type', '042b1853ce716d38e82447937959d5d2f2ea471d359841ae1ffbc677fd5e42c3', 'active', NULL, 694);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-TSA-0-RUNTIME', 1, 'invariant', 'local', NULL, NULL, 'Adapter scans current document text for literal non-overlapping matches, computes the excerpt window and counts skipped large files', '8253024b0736ed059b4840872a9d9b1d6d52763b9dc119805eb906d67ea8e3fd', 'active', NULL, 695);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-TSA-1-INVALID', 1, 'invariant', 'local', NULL, NULL, 'Never representable or produced: A later page that silently skips or repeats items after a project change, or a replayed token that returns a different page', 'aa9e413d3bb8fd277e858ab40da027d96c348e540e1cb4e3a878a9f18b0002ff', 'active', NULL, 697);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-TSA-1-TYPE', 1, 'invariant', 'local', NULL, NULL, 'Continuation sum type Complete or More(token); token is a registry entry constructible only by the registry and bound to operation, arguments and count', '94f27a04ee8f79ccf9b782110fe840bd06f64ed1a09e540f63bb145a4323df3a', 'active', NULL, 698);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-TSA-1-RUNTIME', 1, 'invariant', 'local', NULL, NULL, 'Adapter compares the current PSI modification count before the index wait and again inside the computation, and recomputes the page from the token offset', '13af95b725678de724b3aad6c407bbe00dc8ae5e6a2c06e6f676e2d059277031', 'active', NULL, 699);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-STG-0', 1, 'post', 'local', NULL, NULL, 'CAP-READ-TEXT-SEARCH spec stage outcome: SPEC_VALID for the exact normalized feature basis; no design or implementation claim', '42ac3f4eb1b4d9f902e21bf018bb1c0f4fe025c93327ff1eebb56bc2fe1e7097', 'active', NULL, 729);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-STG-1', 1, 'post', 'local', NULL, NULL, 'CAP-READ-TEXT-SEARCH design stage outcome: DESIGN_VALID; implementation surface frozen', '734c00477dbc598c9f46a80c0d8ddb68b3d51f9a84afd0f830117c714e1c731f', 'active', NULL, 730);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-STG-2', 1, 'post', 'local', NULL, NULL, 'CAP-READ-TEXT-SEARCH implementation stage outcome: CAP-READ-TEXT-SEARCH closure qualified', '56d335be797c140791449da66dfc9649c044545dfccc1ec979da4f038b3179d0', 'active', NULL, 731);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RTXT-REQ-SR017-9', 2, 'invariant', 'interaction', NULL, NULL, 'Because computations run with committed documents (SR-015), unsaved edits change the count.', '3b7e1bf286ebb380a6a89b0325e09090a66a6f25c3b6317a1922a50f6f183776', 'active', 'modeled by read_execution INV_R5 (compute on committed documents)', 777);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SCOPE-1', 1, 'decision', 'local', NULL, NULL, 'read-symbols scope: Java symbol identity reads: search_symbols, get_file_outline and get_symbol_info, symbol handle issue and reuse, handle re-resolution, Java-only language support and identity terms.', '6e3776e4984b76de3fed886bc541dec163456c8491ddb7fc51693b86f365b04c', 'active', NULL, 778);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SCOPE-2', 1, 'pre', 'local', NULL, NULL, 'read-symbols depends on CAP-READ-PIPELINE.', 'f37cf2897f7bc29a0dea58014c2c05f53d96a141129b32482f1728c3de828ad6', 'active', NULL, 779);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SCOPE-3', 1, 'decision', 'local', NULL, NULL, 'read-symbols excludes: Wire JSON argument parsing, tool schemas, the LLM status/code/content envelope and rendering of read outcomes into ToolOutcome content are excluded and belong to the codec feature.', 'c9c1f1d5a18945e20c55ee8727beb5cbd10d5c542e05848d89d782aab21a7534', 'active', NULL, 780);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-NG-0', 1, 'decision', 'local', NULL, NULL, 'Out of scope for read-symbols: Wire JSON argument parsing, tool schemas, tool descriptions, the LLM status/code/content envelope and ToolOutcome content rendering', 'e2adbcadce387a689d727a646bbaf3b8802adafc37e1411f0e0357c53faaa9b5', 'active', NULL, 781);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-NG-1', 1, 'decision', 'local', NULL, NULL, 'Out of scope for read-symbols: Mutations, handle invalidation on agent edits, formatting, diagnostics, build and test execution', '6b6171e5e8dbd9303dfaf441d6928c22764c0f78aec19c420e53f1d0553a5abc', 'active', NULL, 782);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-NG-2', 1, 'decision', 'local', NULL, NULL, 'Out of scope for read-symbols: Regex search, case-insensitive search, glob file patterns and whole-project unscoped text search', '48d83431444d9873a0f1f383b0591f518d16afe70cd5c97f2d67b55f51fa602e', 'active', NULL, 783);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-NG-3', 1, 'decision', 'local', NULL, NULL, 'Out of scope for read-symbols: Semantic support or parity claims for languages other than Java', '88440d90720872a4673e34490d1004b8b72e59cd51508e4a4d0a255558272f2e', 'active', NULL, 784);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-NG-4', 1, 'decision', 'local', NULL, NULL, 'Out of scope for read-symbols: Session owner wiring, New Session UI and tool-window content lifetime integration beyond a registry dispose operation', 'f83fedbd006c976ff01d11e5f4f01d511bbac00a1d09f2a9e03bc7a9ae74f720', 'active', NULL, 785);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-NG-5', 1, 'decision', 'local', NULL, NULL, 'Out of scope for read-symbols: Persisting handles, page tokens or read results across sessions', '82289912750357900abae288e1797729ec068198d66422435bac9de69badcd43', 'active', NULL, 786);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-NG-6', 1, 'decision', 'local', NULL, NULL, 'Out of scope for read-symbols: MCP, HTTP, idea-facade or any second index beside IntelliJ', '48d246d1c64e211439805be2cb94bf0395eaa5d94fd041dd552fc110ec6d0b6c', 'active', NULL, 787);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-NG-7', 1, 'decision', 'local', NULL, NULL, 'Out of scope for read-symbols: Changing CAP-LIFECYCLE-ADMISSION or CAP-DOMAIN-RUN-DRIVER declarations or semantics', '5796ff312020768eabc6321fe45d0ca8979470c80782b7a25813eda96ec6d0e8', 'active', NULL, 788);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-NG-8', 1, 'decision', 'local', NULL, NULL, 'Out of scope for read-symbols: Requirements, operations and acceptance owned by the other semantic reads slices', '30ecc0bffad18c477357eb1a5f818d97f02f6861e58633e5e39da45138eb0598', 'active', NULL, 789);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-AS-0', 1, 'pre', 'local', NULL, NULL, 'read-symbols assumption: Requirement IDs are unique across the five semantic reads slices, which replace CAP-SEMANTIC-READS. A reference to a requirement outside this spec names the slice that owns it: read-domain SR-001, SR-002, SR-012, SR-014, SR-021, SR-022, SR-023, SR-024; read-pipeline SR-003, SR-004, SR-005, SR-015, SR-016, SR-019, SR-020, SR-026, SR-028; read-text-search SR-010, SR-017; read-symbols SR-006, SR-007, SR-008, SR-011, SR-013, SR-018, SR-025; read-references SR-009, SR-027.', '5433d7a5dbd6d8b6ef86b24044b7d3ccfb0cf49c9ba7f5ab0b0ca8121e449f18', 'active', NULL, 790);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-AS-1', 1, 'pre', 'local', NULL, NULL, 'read-symbols assumption: IntelliJ JUnit 5 test fixtures for a Java project with editors, libraries, generated and excluded roots, dumb mode and a test reference query executor are available through the IntelliJ Platform Gradle test framework configuration; the design may change plugin-core/build.gradle.kts for this and must keep tests discoverable as @Test methods.', '7347ddfbaf27365432dd02570f7e0e807df23a56d930cf9a1988bab7e0d69231', 'active', NULL, 791);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-AS-2', 1, 'pre', 'local', NULL, NULL, 'read-symbols assumption: Smart pointers return no element after the element is deleted. After the element''s text is replaced, restore by element info can bind to a replacement declaration at the same range (SmartPsiElementPointerImpl.java:90-115), so SR-013 compares the restored kind, name and signature with the handle payload.', '894476d8c65a982a20f34fe9cb55174cd4e4c94282cd22cbd671cd0de5f7a0a7', 'active', NULL, 792);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-AS-3', 1, 'pre', 'local', NULL, NULL, 'read-symbols assumption: The Structure View builder is not relied on for outlines because background use is not established; outlines walk Java PSI declarations in a background read action.', 'a2a6dff02b6482add2f3b226a6fd6c75bdd8fc60b8c5fdaf6c69e05b907b8a00', 'active', NULL, 793);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-AS-4', 1, 'pre', 'local', NULL, NULL, 'read-symbols assumption: Normalizations of product terms: SR-025 range, signature, owner and containing-declaration definitions; SR-006 catalog declaration kinds; SR-003 line model and defaults; SR-004 path rendering and check order; SR-010 match and excerpt rule and skipped-file count; SR-020 READ_FAILED category rule; SR-026 failure precedence; SR-001 query validation; SR-004 canonical root comparison; SR-009 reference range, line and kind; SR-010 document offsets and match column; SR-025 parameter type text, array dimensions and compact constructors; SR-012 entry kinds.', 'f963c785f174f06dc8b741640df7f68e6fc30d304d709afcd49377df50c4ac19', 'active', NULL, 794);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-AS-5', 1, 'pre', 'local', NULL, NULL, 'read-symbols assumption: Normalizations of scope: generated sources are omitted from find_file, unrestricted search_symbols and search_text directory scans, and included and marked in find_references so reference sets stay complete; handle reuse for the same element (SR-011) keeps one live handle per element in the registry.', 'a8b4975762640471cf59c648284723e25398705eb779dcae16d3f1eab5ebf9cc', 'active', NULL, 795);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-AS-6', 1, 'pre', 'local', NULL, NULL, 'read-symbols assumption: Java short-name stub lookups hide library source files unless library sources are included (JavaSourceFilterScope.java:36-51). A project reference to a compiled library class or method is equivalent to the declaration in its attached source (PsiClassImplUtil.java:1162-1228,1251-1273), so find_references on a library source handle finds project references.', '5f9c48230638bfc607dd15c2907550ba42414441e9990b226955d2567b2059a3', 'active', NULL, 796);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR006-1', 1, 'pre', 'local', NULL, NULL, 'SR-006: search_symbols takes a case-sensitive name, a scope PROJECT (default) or LIBRARIES with the SR-005 meaning, and an optional restriction to one file path or one owner type handle.', 'fd04974cf2c32e70385d0a30f6352f32abad1fa1c5d96003ca53579b0fd04ea7', 'active', NULL, 797);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR006-2', 1, 'invariant', 'local', NULL, NULL, 'SR-006: A nonempty name matches a declaration whose simple name is equal to it.', '68ab76ef7e751ca595751178ba71255365d5011d6e56aa5c28af2d6fc08af815', 'active', NULL, 798);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR006-3', 1, 'invariant', 'local', NULL, NULL, 'SR-006: Without a restriction, generated sources are omitted in both scopes, and the library candidates of LIBRARIES are declarations in attached library source files; a compiled library class without attached sources is not a candidate.', '7daf885f5fae2f2eebff8d4651a99aa9c17736c7433f8b972a9b244d58cfc020', 'active', NULL, 799);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR006-4', 1, 'pre', 'local', NULL, NULL, 'SR-006: An empty name is valid only with a restriction.', '10ce8c365b79337e4c0f7483bee7bf54d1b50682e22567631f2402b7691d9698', 'active', NULL, 800);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR006-5', 1, 'decision', 'local', NULL, NULL, 'SR-006: A restriction overrides scope and generated-source filtering.', '37299e1d039b6842c9f429c2af1578836e8b61776273f5be2393f52d7714fca3', 'active', NULL, 801);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR006-6', 1, 'invariant', 'local', NULL, NULL, 'SR-006: A file restriction lists every catalog declaration in that file at any nesting depth; an owner type restriction lists the declarations directly declared in that type, including nested types but not their members and not inherited members.', '00520b5cab6df3896c95a67d5901cdfac7ea7aab260b217cb4f2d87a9111a88a', 'active', NULL, 802);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR006-7', 1, 'outcome', 'local', 'search_symbols owner handle element is not a type', 'NOT_A_TYPE', 'SR-006: An owner type handle whose element is not a class, interface, enum, record or annotation type returns NOT_A_TYPE.', '773459b0cc9242d1bc517b00d3809c4ecd8d375c525ae72137bd7acc66ababb3', 'active', NULL, 803);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR006-8', 1, 'invariant', 'local', NULL, NULL, 'SR-006: A nonempty name with a restriction matches only inside the restriction.', 'd5108f5d73288074b3e7a6166fa070453ced4b5a0bf12700e19c8e34e681ed32', 'active', NULL, 804);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR006-9', 1, 'invariant', 'local', NULL, NULL, 'SR-006: The catalog declaration kinds are Java class, interface, enum, record, annotation type, method, constructor, field and enum constant written in source.', '44a35ff871d4661ead3aa0dcdee9e4e8056868d8ce4e6c78735cb955f5ba4444', 'active', NULL, 805);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR006-10', 1, 'invariant', 'local', NULL, NULL, 'SR-006: Local classes, anonymous classes, any declaration inside a local class, anonymous class or enum-constant body, record components, implicit constructors, initializers and lambdas are not declarations.', 'e7578d371fe30a401fb9c148b4aeed3ce7f75af980ab161159243a9abd34763f', 'active', NULL, 806);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR006-11', 1, 'invariant', 'local', NULL, NULL, 'SR-006: A constructor matches the name of its class.', 'b5aed17fcefdccb3b016acac620e08b907c3e204f20335f5e374e53971c6211b', 'active', NULL, 807);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR006-12', 1, 'invariant', 'local', NULL, NULL, 'SR-006: Each matching declaration is a separate candidate with symbol handle, language, kind, name, qualified owner, signature, rendered path and declaration range (SR-025).', 'ca99d607a9acdb7a0a0d239778a038ad0c8d361689e3e139112090933babd643', 'active', NULL, 808);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR006-13', 1, 'invariant', 'local', NULL, NULL, 'SR-006: Overloads and unrelated same-name types are never merged or reduced to a first match.', '7e0e644689cbe2cd899c2a0c9ce25935744d6a15d7669a8977a6dcaffb0477f4', 'active', NULL, 809);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR006-14', 1, 'outcome', 'local', 'search_symbols results exceed the result collection cap', 'TOO_MANY_RESULTS', 'SR-006: Paged collection applies the result collection cap (SR-002): more results than the cap returns TOO_MANY_RESULTS with a narrowing hint and no page.', '862940289aa22a3d24823f47aa5d7d8736521e61d029051bfcda6d1423d5a4d4', 'active', NULL, 810);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR007-1', 1, 'post', 'local', NULL, NULL, 'SR-007: get_file_outline takes one file path and returns the catalog declarations (SR-006) of that file in source order, at any nesting depth, each with nesting depth (the number of enclosing catalog declarations, so 0 for top-level types), kind, name, signature, declaration range (SR-025) and symbol handle, in pages of at most 100 entries.', '5285a685b05823467a9a497cea29a640b2aae2d2a2d61aa8fb249de459464c87', 'active', NULL, 811);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR007-2', 1, 'invariant', 'local', NULL, NULL, 'SR-007: It returns no statements or expression nodes.', '0083b363d012976e81ec65f1f628023e5cfcff5f5a47c8b25ac18b0778cbd489', 'active', NULL, 812);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR007-3', 1, 'invariant', 'local', NULL, NULL, 'SR-007: It never resolves types, so it needs no index.', '0fae75a9504ab9535ba7c7156fb9748fedf6801ab68d971082963e9235c11093', 'active', NULL, 813);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR007-4', 1, 'outcome', 'local', 'get_file_outline on a non-Java file', 'UNSUPPORTED_LANGUAGE', 'SR-007: A non-Java file returns UNSUPPORTED_LANGUAGE, never an empty success.', 'b2279c50187b24f8fd4ae407ca207c62f544d1b4feed7e268b7bb5c2af16bc6b', 'active', NULL, 814);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR007-5', 1, 'outcome', 'local', 'get_file_outline results exceed the result collection cap', 'TOO_MANY_RESULTS', 'SR-007: Paged collection applies the result collection cap (SR-002): more results than the cap returns TOO_MANY_RESULTS with a narrowing hint and no page.', '046fbdd50eca2f9ba721d0d681182313ffa48ddea3bf304c832f76741d751d98', 'active', NULL, 815);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR008-1', 1, 'post', 'local', NULL, NULL, 'SR-008: get_symbol_info takes a symbol handle and returns the symbol identity (kind, name, qualified owner, signature), declaration range (SR-025), the current document version, and either the declaration source with a new read handle for exactly that range on every call, or SOURCE_TOO_LARGE with the declaration line count and UTF-8 byte size and no source and no read handle when the declaration exceeds 300 lines or 24 KiB.', '42f60fe0e0942c136a40ac1f357e90f6a83456ed8732a95208106121a06b3308', 'active', NULL, 816);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR011-1', 1, 'invariant', 'local', NULL, NULL, 'SR-011: Symbol handles are issued only by the adapter from IntelliJ resolution results of catalog operations.', '0f06d4e41009a49e448ea9d8d8c9c35c0c5b0ddb859555f71996a1e8487d318b', 'active', NULL, 817);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR011-2', 1, 'invariant', 'local', NULL, NULL, 'SR-011: A handle is an opaque session-scoped identifier that encodes no PSI pointer, path, offset or source text.', '75f5e83b97eeeae7db38f9c474efce4e69e4dfc79dfa6d2c30275c15f3335273', 'active', NULL, 818);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR011-3', 1, 'invariant', 'local', NULL, NULL, 'SR-011: The adapter payload of a symbol handle holds the smart pointer plus language, qualified owner, signature, file identity and the document modification stamp observed at issue.', 'd1b50a89fd62c4c2d8ab658f1701386d5bdf669109bcf967f4dbc0bceb864cf4', 'active', NULL, 819);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR011-4', 1, 'invariant', 'local', NULL, NULL, 'SR-011: Before issuing, the adapter compares the new pointer with live symbol entries using SmartPointerManager.pointToTheSameElement and returns the existing handle when one matches (registry issue-or-reuse, SR-012).', 'ce5294f041111d85cc767d776ca8af3e91ca7e0ad5372df78989a8667a0c089e', 'active', NULL, 820);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR011-5', 1, 'invariant', 'local', NULL, NULL, 'SR-011: The release action of a symbol handle payload removes its smart pointer with SmartPointerManager.removePointer.', '0820d154da7c45d965df90c15777ae6b832fac60215da275ee00850ebb666c0b', 'active', NULL, 821);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR013-1', 1, 'pre', 'interaction', NULL, NULL, 'SR-013: A read operation on a symbol handle re-resolves the stored smart pointer inside its read computation with documents committed.', '4b00bca3c76d64e0c0983d5362e29cae40859f52deed67cf5b34b6b4c313bacf', 'active', NULL, 822);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR013-2', 1, 'outcome', 'local', 'symbol handle element deleted or restored kind/name/signature differs', 'STALE_HANDLE', 'SR-013: If the element no longer exists, or the restored element''s kind, name or signature differs from the handle payload, it returns STALE_HANDLE.', '8ac9e230905a71f11ac234ce475198c5f2e241a2e4861ae71877fb8199110d5c', 'active', NULL, 823);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR013-3', 1, 'outcome', 'interaction', 'symbol handle element exists after edits with same kind/name/signature', 'current state and current document version', 'SR-013: If the element still exists after document edits with the same kind, name and signature, the operation uses the element''s current state and reports the current document version.', '88f3ee078168405ce25129803db18db4e49f79fd7af790379f4d3527017cd32f', 'active', NULL, 824);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR018-1', 1, 'invariant', 'local', NULL, NULL, 'SR-018: Semantic operations support Java only.', '65f823004304849a4ba3a4a42525c5708d478fe2773cd7dc983231c17e8be082', 'active', NULL, 825);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR018-2', 1, 'invariant', 'local', NULL, NULL, 'SR-018: Symbol handles exist only for Java declarations of the SR-006 kinds, and search_symbols returns only Java declarations.', 'c1aecbc6e32b6c76947e9c0a8506aafafd69a617286439b547c2b3749ce2c72d', 'active', NULL, 826);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR018-3', 1, 'invariant', 'local', NULL, NULL, 'SR-018: get_file_outline on a non-Java file and search_symbols restricted to a non-Java file return UNSUPPORTED_LANGUAGE.', '8cf7dea61be895bcce1b22f6492bea2d996f6a0dd092ec042cff2d05a12b760e', 'active', NULL, 827);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR018-4', 1, 'invariant', 'local', NULL, NULL, 'SR-018: find_references on a Java symbol includes resolved references from non-Java files (SR-009).', '4e913695bb30436eb1b9d51c4ffe38db873463950e5323cdc7453a0d53073458', 'active', NULL, 828);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR018-5', 1, 'invariant', 'local', NULL, NULL, 'SR-018: read_file, find_file and search_text work for any text file.', 'c9a46e9e3310a5a7d4ad30b672ccbd155ee6b805d59404c7934d01ca15a4924e', 'active', NULL, 829);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR025-2', 1, 'invariant', 'local', NULL, NULL, 'SR-025: A declaration range is the text range of the declaration PSI element in the current document, including its doc comment, annotations and modifiers, reported as 0-based start and end-exclusive UTF-16 offsets plus 1-based start and end lines.', '06bb03c61d89f9b218e9ec1c7e56d14ce20d084b56abf7e7da8ebf09abc09ad7', 'active', NULL, 831);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR025-3', 1, 'invariant', 'local', NULL, NULL, 'SR-025: A signature is computed from source text without type resolution: for a method or constructor, the name followed by the parameter type texts in parentheses, separated by '', ''; for a field or enum constant, the name; for a type, its qualified name.', '1c65e594fb6f4a78bbb046d9338678f391e6a01b86e3cf4f7fc6e9d3a14c9b71', 'active', NULL, 832);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR025-4', 1, 'invariant', 'local', NULL, NULL, 'SR-025: A parameter type text is the text of the parameter type element with comments and annotations removed, whitespace runs collapsed to one space, one ''[]'' appended for each array dimension written after the parameter name, and varargs written as ''...''.', '369d276f43ea0cbd9fff9e7d56bce9641c2f5b17cedbdf0d86964eff2ff5f4f9', 'active', NULL, 833);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR025-5', 1, 'invariant', 'local', NULL, NULL, 'SR-025: A compact canonical constructor uses the record component types in declaration order.', '6fd520b04c383c190530a23b39e8b89c9e15de18fc35cd414a19e4e19ce78461', 'active', NULL, 834);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR025-6', 1, 'invariant', 'local', NULL, NULL, 'SR-025: A signature does not prove identity; the handle does.', '76771e2d9d703f3185b638fca475791a8d22d0e4277d22d5270dc76599af8b1e', 'active', NULL, 835);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR025-7', 1, 'invariant', 'local', NULL, NULL, 'SR-025: The qualified owner of a member or nested type is the qualified name of the containing type; of a top-level type, its package name (empty for the default package).', '18a9b778cbe5cdaa2b002d2f592658242a312b4d382145534b201cbf55989a1f', 'active', NULL, 836);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-SR025-8', 1, 'invariant', 'local', NULL, NULL, 'SR-025: The containing declaration of a reference is the innermost enclosing catalog declaration, reported as qualified owner plus signature.', 'e3b713a425295644233a46e8d6a0c021a2e2817c0f189620e6399eb1723cec24', 'active', NULL, 837);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-ACC-0', 1, 'outcome', 'interaction', 'Open a Java file in an editor and insert a new method with a unique name without saving, then call read_file, get_file_outline, search_symbols and get_symbol_info for it.', 'All four report the new method from the unsaved text, with ranges that match the unsaved document and the unsaved document version.', 'read-symbols acceptance SemanticReadIdeTest#unsavedEditorContentWins: when Open a Java file in an editor and insert a new method with a unique name without saving, then call read_file, get_file_outline, search_symbols and get_symbol_info for it. then All four report the new method from the unsaved text, with ranges that match the unsaved document and the unsaved document version.', '40b36ce2e029b8dcd1dc16f0770f986d38058053c3cd8b58b660e7823b6a67e2', 'active', NULL, 838);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-ACC-1', 1, 'outcome', 'local', 'Declare two overloads of one method name in one class, ''m(java.util.List<String> a)'' and ''m(int... b)'', and search_symbols for that name.', 'Two distinct candidates with distinct handles are returned in SR-024 order with signatures ''m(java.util.List<String>)'' and ''m(int...)''; neither is chosen silently.', 'read-symbols acceptance SemanticReadIdeTest#overloadsAreDistinctCandidates: when Declare two overloads of one method name in one class, ''m(java.util.List<String> a)'' and ''m(int... b)'', and search_symbols for that name. then Two distinct candidates with distinct handles are returned in SR-024 order with signatures ''m(java.util.List<String>)'' and ''m(int...)''; neither is chosen silently.', '82427b46e6a6ba62684536b9ebcbcdb2952661b43f49a2a1db79d4697d8cb445', 'active', NULL, 839);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-ACC-2', 1, 'outcome', 'local', 'Call get_file_outline on a Java file with nested classes, on a Java file with 101 catalog declarations, and on a non-Java text file, and call search_symbols restricted to the non-Java file.', 'The Java outline lists only declarations in source order with handles, and each nesting depth equals the number of enclosing catalog declarations; the 101-declaration file returns a page of 100 entries with a next-page token and then a complete page of 1; the non-Java outline and the restricted search return UNSUPPORTED_LANGUAGE with a hint that names read_file and search_text and no other tool, never an empty success; no handle is issued for the non-Java file.', 'read-symbols acceptance SemanticReadIdeTest#outlineIsJavaDeclarationsOnly: when Call get_file_outline on a Java file with nested classes, on a Java file with 101 catalog declarations, and on a non-Java text file, and call search_symbols restricted to the non-Java file. then The Java outline lists only declarations in source order with handles, and each nesting depth equals the number of enclosing catalog declarations; the 101-declaration file returns a page of 100 entries with a next-page token and then a complete page of 1; the non-Java outline and the restricted search return UNSUPPORTED_LANGUAGE with a hint that names read_file and search_text and no other tool, never an empty success; no handle is issued for the non-Java file.', '75e2f4756f74e2af23ec505c612a69c39c2363a72b24cef9d5243b3b9c42b293', 'active', NULL, 840);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-ACC-3', 1, 'outcome', 'local', 'Call get_symbol_info on the handle of a method that has a Javadoc comment and an annotation and is preceded in the file by a line containing a non-BMP character; call it again on the same handle; then call it on a method longer than 300 lines.', 'The first result has identity, a range that starts at the doc comment in UTF-16 offsets with 1-based lines, bounded source, current document version and a read handle whose range equals the returned range; the repeated call returns an outcome equal to the first except for a distinct read handle identifier; the long method returns SOURCE_TOO_LARGE with line count and byte size and no source and no read handle.', 'read-symbols acceptance SemanticReadIdeTest#symbolInfoReturnsReadHandleForReturnedRange: when Call get_symbol_info on the handle of a method that has a Javadoc comment and an annotation and is preceded in the file by a line containing a non-BMP character; call it again on the same handle; then call it on a method longer than 300 lines. then The first result has identity, a range that starts at the doc comment in UTF-16 offsets with 1-based lines, bounded source, current document version and a read handle whose range equals the returned range; the repeated call returns an outcome equal to the first except for a distinct read handle identifier; the long method returns SOURCE_TOO_LARGE with line count and byte size and no source and no read handle.', '3dfc001cc2c6ccf92eae534ee12c92f7981dcb13cf1b048b1df3ada8360cb23e', 'active', NULL, 841);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-ACC-4', 1, 'outcome', 'local', 'Record SmartPointerManagerImpl.getPointersNumber for a Java file; return the same element of that file from search_symbols and get_file_outline; submit a handle string that the registry never issued; then dispose the registry.', 'Both operations return the same handle; the unissued handle returns STALE_HANDLE with a hint that names only catalog tools; after disposal the pointer count of the file equals the recorded count.', 'read-symbols acceptance SemanticReadIdeTest#handlesAreRegistryIssuedAndReused: when Record SmartPointerManagerImpl.getPointersNumber for a Java file; return the same element of that file from search_symbols and get_file_outline; submit a handle string that the registry never issued; then dispose the registry. then Both operations return the same handle; the unissued handle returns STALE_HANDLE with a hint that names only catalog tools; after disposal the pointer count of the file equals the recorded count.', '6d0e186946c5e4d587351eadd2f267dc1c33947782fa3b328a6097d61e8dbc3a', 'active', NULL, 842);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-ACC-5', 1, 'outcome', 'interaction', 'Obtain a method handle, edit the document above the method and inside its body, call get_symbol_info; replace the whole method text with a method of another name at the same position and call get_symbol_info; obtain a second method handle, delete that method and call get_symbol_info again.', 'After the edits above and inside the body the result reports the moved range, the current body and the new document version; after the replacement by another name and after deletion the result is STALE_HANDLE.', 'read-symbols acceptance SemanticReadIdeTest#editedHandleReResolvesAndDeletedHandleIsStale: when Obtain a method handle, edit the document above the method and inside its body, call get_symbol_info; replace the whole method text with a method of another name at the same position and call get_symbol_info; obtain a second method handle, delete that method and call get_symbol_info again. then After the edits above and inside the body the result reports the moved range, the current body and the new document version; after the replacement by another name and after deletion the result is STALE_HANDLE.', 'f88aa25095fd7e49a58a2185bb40f0f74f4a375b6bcfab6a004e0b18ebf8c80b', 'active', NULL, 843);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-ACC-6', 1, 'outcome', 'local', 'In a Java file with a top-level class holding two explicit constructors, a nested class, a method m(String a[]), a field, a local class with a method, an anonymous class with a method and an initializer, plus an annotation type, an enum with constants one of which has a body with a method, and a record with a compact canonical constructor, call search_symbols with an empty name restricted to the file and restricted to the top-level class handle, and with the class name unrestricted. Also call search_symbols with an empty name restricted to a generated source file, restricted to a library class handle with scope PROJECT, and restricted to the handle of method m. With the result collection cap injected as 3, call search_symbols with an empty name restricted to the file.', 'The file restriction lists every catalog declaration at every depth, including the annotation type, the enum constants and the compact constructor with the record component types as signature; the class restriction lists only its two constructors, nested class, method and field; m has signature ''m(String[])''; local classes, anonymous classes, their methods, the enum-constant body method and initializers are absent; the unrestricted class-name query returns the class and its two constructors as separate candidates; the generated file restriction and the library class restriction list their declarations; the method handle restriction returns NOT_A_TYPE. The capped restricted query returns TOO_MANY_RESULTS with no page.', 'read-symbols acceptance SemanticReadIdeTest#restrictedSymbolListingUsesCatalogKinds: when In a Java file with a top-level class holding two explicit constructors, a nested class, a method m(String a[]), a field, a local class with a method, an anonymous class with a method and an initializer, plus an annotation type, an enum with constants one of which has a body with a method, and a record with a compact canonical constructor, call search_symbols with an empty name restricted to the file and restricted to the top-level class handle, and with the class name unrestricted. Also call search_symbols with an empty name restricted to a generated source file, restricted to a library class handle with scope PROJECT, and restricted to the handle of method m. With the result collection cap injected as 3, call search_symbols with an empty name restricted to the file. then The file restriction lists every catalog declaration at every depth, including the annotation type, the enum constants and the compact constructor with the record component types as signature; the class restriction lists only its two constructors, nested class, method and field; m has signature ''m(String[])''; local classes, anonymous classes, their methods, the enum-constant body method and initializers are absent; the unrestricted class-name query returns the class and its two constructors as separate candidates; the generated file restriction and the library class restriction list their declarations; the method handle restriction returns NOT_A_TYPE. The capped restricted query returns TOO_MANY_RESULTS with no page.', 'de4e107651a0d9ba1db13979755cfb9cf6e8d4015efd97ee28dc0a17bc9ea61f', 'active', NULL, 844);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-ACC-7', 1, 'outcome', 'local', 'Attach a library with a sources jar and a second library without sources. Call search_symbols for a class of each library with PROJECT and LIBRARIES scope, then call get_symbol_info on the handle of the library-with-sources class.', 'PROJECT returns no library candidate; LIBRARIES returns the class from the sources jar with its jar URL path and origin LIBRARY and returns no candidate for the class without sources; get_symbol_info returns the declaration source from the sources jar.', 'read-symbols acceptance SemanticReadIdeTest#librarySymbolsUseAttachedSources: when Attach a library with a sources jar and a second library without sources. Call search_symbols for a class of each library with PROJECT and LIBRARIES scope, then call get_symbol_info on the handle of the library-with-sources class. then PROJECT returns no library candidate; LIBRARIES returns the class from the sources jar with its jar URL path and origin LIBRARY and returns no candidate for the class without sources; get_symbol_info returns the declaration source from the sources jar.', 'f52e23651fa43204fd03560ad700bb50bbdf7fc984aae138f73980745ec874c5', 'active', NULL, 845);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-ACC-8', 1, 'outcome', 'local', 'In dumb mode with the index wait bound injected as 200 ms, call get_symbol_info with an unissued handle, get_symbol_info with a read handle identifier, and search_symbols restricted to a Kotlin file.', 'The handle calls return STALE_HANDLE and the Kotlin call returns UNSUPPORTED_LANGUAGE, all before 200 ms elapse.', 'read-symbols acceptance SemanticReadIdeTest#symbolPrecedenceSkipsIndexWait: when In dumb mode with the index wait bound injected as 200 ms, call get_symbol_info with an unissued handle, get_symbol_info with a read handle identifier, and search_symbols restricted to a Kotlin file. then The handle calls return STALE_HANDLE and the Kotlin call returns UNSUPPORTED_LANGUAGE, all before 200 ms elapse.', '526197666f3e837c3035a05011c11aff62782035d58eec534c740aa323ecbee2', 'active', NULL, 846);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-DEC-edited_handle', 1, 'decision', 'local', NULL, NULL, 'read-symbols decision edited_handle: RE_RESOLVE_AND_REPORT_CURRENT', 'a179bd1705897e42665fe0eaf28f01bd161e5fb25a69fbfd2fd6bed8f43cc167', 'active', NULL, 857);
