INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-DEC-search_restriction', 1, 'decision', 'local', NULL, NULL, 'read-symbols decision search_restriction: RESTRICTION_OVERRIDES_SCOPE_AND_GENERATED_NON_TYPE_OWNER_NOT_A_TYPE', 'ae67d6f5213e3e00bb730ea1514fad9a994ad15258e2f3a50567b65ea9edb0aa', 'active', NULL, 868);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-DEC-restored_pointer_identity', 1, 'decision', 'local', NULL, NULL, 'read-symbols decision restored_pointer_identity: KIND_NAME_SIGNATURE_MISMATCH_STALE_HANDLE', 'cff61f98fb458af79d00ef7f15be3f52a14aa31eeb17ee1e53e1b1f1191e379c', 'active', NULL, 871);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-DEC-unsupported_language_hint', 1, 'decision', 'local', NULL, NULL, 'read-symbols decision unsupported_language_hint: CATALOG_HINT_READ_FILE_AND_SEARCH_TEXT', '0e46dc5398c02dd7fe78d7d774f735c5c2e042cd7e44b5d7963585c927988fd1', 'active', NULL, 875);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-OPM-0', 1, 'outcome', 'local', 'get_file_outline in INDEXING when more results than the collection cap', 'TOO_MANY_RESULTS with narrowing hint; no page; no wait for indexing', 'read-symbols operation matrix 0: get_file_outline in INDEXING when more results than the collection cap -> TOO_MANY_RESULTS with narrowing hint; no page; no wait for indexing; next phase INDEXING', '5adfc07c0ce054605b91d926d83556cf395acc757a5bb0e5bf6847776ceb9c2a', 'active', NULL, 877);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-OPM-1', 1, 'outcome', 'local', 'get_file_outline|search_symbols restricted to a file in SMART|INDEXING when file is not Java', 'UNSUPPORTED_LANGUAGE; no wait for indexing', 'read-symbols operation matrix 1: get_file_outline|search_symbols restricted to a file in SMART|INDEXING when file is not Java -> UNSUPPORTED_LANGUAGE; no wait for indexing; next phase unchanged', 'f0b7bf26b3edc6ce0fa10e71d9db3fe1764c17989d0f8cb86d4cee931ba6b394', 'active', NULL, 878);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-OPM-2', 1, 'outcome', 'local', 'get_symbol_info|find_references|search_symbols with an owner type handle in SMART|INDEXING when handle unknown, evicted, wrong-kind or foreign', 'STALE_HANDLE with catalog-only rediscovery hint; no wait for indexing', 'read-symbols operation matrix 2: get_symbol_info|find_references|search_symbols with an owner type handle in SMART|INDEXING when handle unknown, evicted, wrong-kind or foreign -> STALE_HANDLE with catalog-only rediscovery hint; no wait for indexing; next phase unchanged', '9817f7fac07e97730237435b484c08b7224bfc6df6b585a4e7feacac3542dd72', 'active', NULL, 879);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-OPM-3', 1, 'outcome', 'interaction', 'get_symbol_info|find_references|search_symbols with an owner type handle in SMART when handle issued by this registry and element exists with the same kind, name and signature', 'Re-resolve; report current state and document version', 'read-symbols operation matrix 3: get_symbol_info|find_references|search_symbols with an owner type handle in SMART when handle issued by this registry and element exists with the same kind, name and signature -> Re-resolve; report current state and document version; next phase SMART', '420b5f6b5660250e1717b107d4c19fa6bbca8cf799956cb3127d388e8d9dfa33', 'active', NULL, 880);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-OPM-4', 1, 'outcome', 'local', 'get_symbol_info|find_references|search_symbols with an owner type handle in SMART when handle issued by this registry and element deleted, or restored element differs in kind, name or signature', 'STALE_HANDLE with catalog-only rediscovery hint', 'read-symbols operation matrix 4: get_symbol_info|find_references|search_symbols with an owner type handle in SMART when handle issued by this registry and element deleted, or restored element differs in kind, name or signature -> STALE_HANDLE with catalog-only rediscovery hint; next phase SMART', '79e5e74d2182f75c17f1a9fe8a6117af9c010ecffbf43572b870290e18430bee', 'active', NULL, 881);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-OPM-5', 1, 'outcome', 'local', 'search_symbols with an owner type handle in SMART when handle issued by this registry and element is not a class, interface, enum, record or annotation type', 'NOT_A_TYPE', 'read-symbols operation matrix 5: search_symbols with an owner type handle in SMART when handle issued by this registry and element is not a class, interface, enum, record or annotation type -> NOT_A_TYPE; next phase SMART', '854cc984f6272f378d7aa5fe4a6d78b134188237b6db379f8ca0d037f3fea3e2', 'active', NULL, 882);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-NBM-0', 1, 'outcome', 'local', 'read adapter platform results with nullable platform return such as missing document, file or resolved element', 'Named outcome (FILE_NOT_FOUND, UNSUPPORTED_FILE, STALE_HANDLE); never a null in a domain value', 'read-symbols null boundary: read adapter platform results with nullable platform return such as missing document, file or resolved element -> Named outcome (FILE_NOT_FOUND, UNSUPPORTED_FILE, STALE_HANDLE); never a null in a domain value', '38ffe5b607b0e3b45600695ba2bcfcf6abe6bb208cfe6c7069f3bcc270b0441c', 'active', NULL, 883);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-TSA-0', 1, 'invariant', 'local', NULL, NULL, 'read-symbols type safety 0: invalid state [One candidate chosen for an ambiguous name, merged overloads, an unrestricted wildcard listing, a non-catalog declaration kind, a candidate without a qualified owner, or an owner restriction on a non-type] is prevented by [Candidate list type with one entry per resolved declaration; declaration kind enum limited to the catalog kinds; qualified owner is a required component; wildcard argument factory requires a restriction; sealed outcome with a NOT_A_TYPE variant]; residual runtime obligation [Adapter enumerates every declaration the name index returns within scope and page, searches library sources with library sources included, omits declarations inside local classes, anonymous classes and enum-constant bodies, and checks the owner handle element kind]; because [Declaration sets depend on the live index]', '1e6e16181be5355bd35b698bc65723ead503ba173341258a37d56cbd8169ad95', 'active', NULL, 884);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-TSA-1', 1, 'invariant', 'local', NULL, NULL, 'read-symbols type safety 1: invalid state [A raw AST dump, or an empty outline for an unsupported language] is prevented by [Outline entry type limited to declaration kinds; sealed outcome with UNSUPPORTED_LANGUAGE variant]; residual runtime obligation [Adapter walks Java PSI declarations in a background read action without resolving types]; because [Language support is determined by the file type at runtime]', '3a06537fa6f344b4e3553b75556c8faa10b0d360b4323411f8890c03002d1927', 'active', NULL, 885);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-TSA-2', 1, 'invariant', 'local', NULL, NULL, 'read-symbols type safety 2: invalid state [Symbol information built from model-supplied text instead of a handle] is prevented by [Operation argument is a symbol handle value only; sealed outcome with a source variant that carries the read handle for exactly the returned range and a SourceTooLarge variant without source or handle]; residual runtime obligation [Adapter re-resolves the handle before reading]; because [Identity must come from IntelliJ resolution (I5)]', '9d8a6d82f98996e8c87460ca10ff192b2e6ef5295239ff31504e89ac8204f190', 'active', NULL, 886);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-TSA-3', 1, 'invariant', 'local', NULL, NULL, 'read-symbols type safety 3: invalid state [A model-forged or content-derived handle, or two live handles for one element] is prevented by [Handle identifier constructible only by the registry; the registry offers issue-or-reuse with an adapter-supplied match predicate and never compares payloads itself]; residual runtime obligation [Adapter compares a new smart pointer with live payload pointers using pointToTheSameElement before issuing]; because [Java cannot prevent a model from echoing arbitrary strings; resolution must reject them]', '6af73e308e38bd1db0d326c6ca65fcdebdc3af099edcc65ac44274d516988294', 'active', NULL, 887);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-TSA-4', 1, 'invariant', 'local', NULL, NULL, 'read-symbols type safety 4: invalid state [A read that reports a deleted element, a replacement declaration as the handle''s element, or pre-edit ranges for an edited document] is prevented by [Sealed resolution outcome with live and stale variants]; residual runtime obligation [Adapter reads pointer and document version in one read action and compares the restored element''s kind, name and signature with the handle payload]; because [Pointer survival after reparse is platform behavior]', '10da8e19f4a366a1fbb3e84ed8f71fa1fce7644237a0c29757715150f4e985be', 'active', NULL, 888);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-TSA-5', 1, 'invariant', 'local', NULL, NULL, 'read-symbols type safety 5: invalid state [A symbol handle issued for a non-Java PSI element] is prevented by [Adapter-only handle factory that accepts only Java declarations of catalog kinds; UNSUPPORTED_LANGUAGE variant in outline and restricted symbol search outcomes]; residual runtime obligation [Adapter checks the file language before semantic access]; because [QUALIFICATION_TARGET limits qualification to Java]', '7b3c853c891f3b56655ebdf95e4e09e5a617c670b74bb64d93dd0d2e81e0b479', 'active', NULL, 889);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-TSA-6', 1, 'invariant', 'local', NULL, NULL, 'read-symbols type safety 6: invalid state [A range that omits the doc comment, a line/column range in another unit, or a signature that depends on type resolution] is prevented by [Declaration range value with validated UTF-16 offsets and 1-based lines; signature value built by one adapter function from source text]; residual runtime obligation [Adapter reads element text ranges from committed PSI and converts offsets to lines on the same document]; because [Later mutation features depend on the exact range; outlines must work without indexes]', 'dadb0f1a7e585d2be2db32a522b8b6d95852975d5c04cf6a228b6aeb71c7466a', 'active', NULL, 890);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-STG-0-ENTRY', 1, 'pre', 'local', NULL, NULL, 'read-symbols stage 0 entry requires: SR-006, SR-007, EV-SOURCE', 'f96ef86c35022927f16fc5fa1bd63e3e087b5294823b82bb21d70a98ff25333d', 'active', NULL, 891);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-STG-0-EXIT', 1, 'post', 'local', NULL, NULL, 'read-symbols stage 0 exit requires: SR-006, SR-007, SR-008, SR-011, SR-013, SR-018, SR-025, EV-STRUCTURE, EV-SPEC-REVIEW', 'ed99e45058ab6ebcf2eedec4da6c8929ab00fe3fda1d575978787a770dfac120', 'active', NULL, 892);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RSYM-STG-0-OUTCOME', 1, 'post', 'local', NULL, NULL, 'read-symbols stage 0 outcome: SPEC_VALID for the exact normalized feature basis; no design or implementation claim', 'a8d777826ec7d6dab6e82420ab36155fbe226f98fc5e45263dba5f99af4d74c1', 'active', NULL, 893);
