INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-SCOPE-1', 1, 'decision', 'local', NULL, NULL, 'read-pipeline: The IntelliJ read pipeline and the file reads: admission and cancellation through CallAdmission, committed-document read computations, indexing readiness with the bounded wait, sanitized failures, fixed failure precedence, path resolution, read_file and find_file.', 'c6bb32efd54f0a91765053855594412763926e0a469460db9026355e1e551efe', 'active', NULL, 946);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-SCOPE-2', 1, 'pre', 'local', NULL, NULL, 'read-pipeline: Depends on CAP-READ-DOMAIN.', 'ee1abdc5da06f00696f038b747324985686b10934d003a48c29a20d62fe422a5', 'active', NULL, 947);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-SCOPE-3', 1, 'decision', 'local', NULL, NULL, 'read-pipeline: Wire JSON argument parsing, tool schemas, the LLM status/code/content envelope and rendering of read outcomes into ToolOutcome content are excluded and belong to the codec feature.', '46729fa8773fe400453a088dbb5f36808227380f2c2ee9e2f51faa23dbdd7d93', 'active', NULL, 948);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-NG-0', 1, 'decision', 'local', NULL, NULL, 'read-pipeline: out of scope: Wire JSON argument parsing, tool schemas, tool descriptions, the LLM status/code/content envelope and ToolOutcome content rendering', 'e1efbb444a1d4a7ceeff06d6b8ffae461432c85a6fa00dbd72f3f328cc4104c6', 'active', NULL, 949);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-NG-1', 1, 'decision', 'local', NULL, NULL, 'read-pipeline: out of scope: Mutations, handle invalidation on agent edits, formatting, diagnostics, build and test execution', '977adf1de1fbe0467e231296aaa629836cbb3c999e6f3e27dc4f709a2914c727', 'active', NULL, 950);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-NG-2', 1, 'decision', 'local', NULL, NULL, 'read-pipeline: out of scope: Regex search, case-insensitive search, glob file patterns and whole-project unscoped text search', '8c813a2f10b5554c69727f0a9607e54da75afe4ffce1079fb825430dd70d2bd8', 'active', NULL, 951);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-NG-3', 1, 'decision', 'local', NULL, NULL, 'read-pipeline: out of scope: Semantic support or parity claims for languages other than Java', 'bb8b5b19aeb6c437e951f2c968328e5678832ac54a9b63f2b3a580f2a48bcfb9', 'active', NULL, 952);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-NG-4', 1, 'decision', 'local', NULL, NULL, 'read-pipeline: out of scope: Session owner wiring, New Session UI and tool-window content lifetime integration beyond a registry dispose operation', '7ec7d07cfa5b3d7bba386387c4ffee8fbe98433efe012bdeaa118ddfa513b6a1', 'active', NULL, 953);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-NG-5', 1, 'decision', 'local', NULL, NULL, 'read-pipeline: out of scope: Persisting handles, page tokens or read results across sessions', 'f30e4227371c983cfeb8a443c51c6421cdf8c87f0ef87b9bd08b250af03f3f95', 'active', NULL, 954);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-NG-6', 1, 'decision', 'local', NULL, NULL, 'read-pipeline: out of scope: MCP, HTTP, idea-facade or any second index beside IntelliJ', 'e9952c043f90f1531f865a380bfac5e75482c1bdf44c82ad1c9dc5db3eada3c5', 'active', NULL, 955);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-NG-7', 1, 'decision', 'local', NULL, NULL, 'read-pipeline: out of scope: Changing CAP-LIFECYCLE-ADMISSION or CAP-DOMAIN-RUN-DRIVER declarations or semantics', '183a2ed280da1a12cf32d2c2acadcd3598b661a05b5bc798d51d1322f6c7569e', 'active', NULL, 956);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-NG-8', 1, 'decision', 'local', NULL, NULL, 'read-pipeline: out of scope: Requirements, operations and acceptance owned by the other semantic reads slices', 'ff4a108989697a1d650f7ab17928ac9061da02785909bad383c8197dc6f1daa5', 'active', NULL, 957);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-AS-0-0', 1, 'pre', 'local', NULL, NULL, 'read-pipeline: Requirement IDs are unique across the five semantic reads slices, which replace CAP-SEMANTIC-READS.', '94e378666e13e203b51ec6d871200c241754976638f73c7c52e8702062236604', 'active', NULL, 958);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-AS-0-1', 1, 'pre', 'local', NULL, NULL, 'read-pipeline: A reference to a requirement outside this spec names the slice that owns it: read-domain SR-001, SR-002, SR-012, SR-014, SR-021, SR-022, SR-023, SR-024; read-pipeline SR-003, SR-004, SR-005, SR-015, SR-016, SR-019, SR-020, SR-026, SR-028; read-text-search SR-010, SR-017; read-symbols SR-006, SR-007, SR-008, SR-011, SR-013, SR-018, SR-025; read-references SR-009, SR-027.', '41ccb62fd0e1039fa85913a34208dda26300b19c62cdcc47a333d31f49e17c4f', 'active', NULL, 959);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-AS-1-0', 1, 'pre', 'local', NULL, NULL, 'read-pipeline: CAP-LIFECYCLE-ADMISSION is frozen with FINAL_GATE_PASS; its S3 is blocked only on EV-SURFACE.', '8d082d2653d456b469693e40f0fadc8e52f504ad7f8e33c30c45dd29ec28ddb8', 'active', NULL, 960);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-AS-1-1', 1, 'pre', 'local', NULL, NULL, 'read-pipeline: This feature relies on its admission semantics, and this feature''s S3 cannot close while lifecycle S3 remains blocked.', '876372748c8ff736f4f7484e451ed10f83da92cf0bc5407254d85ac07cca197f', 'active', NULL, 961);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-AS-2-0', 1, 'pre', 'local', NULL, NULL, 'read-pipeline: CAP-DOMAIN-RUN-DRIVER is closed; reads bind to its PlannedCall.ToolOperation, ToolRunner and CallAdmission surfaces without changing them.', '3a0d85e1b35d7bf5ef93fca19ad12c6c2894b41b7e452457c975faa59bbb5ebb', 'active', NULL, 962);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-AS-3-0', 1, 'pre', 'local', NULL, NULL, 'read-pipeline: A read cancelled after admission, or finding a disposed registry at registration, throws java.util.concurrent.CancellationException from the Effect; the frozen driver maps it to ToolOutcome.FailedAfterStart with the message ''Tool execution failed after admission: CancellationException'' and no touched paths (NativeRunDriver.executeOne).', '00c99937749693a8663a42bc13363bc2b1ebe91dd622c09be909e74393afbc2d', 'active', NULL, 963);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-AS-3-1', 1, 'pre', 'local', NULL, NULL, 'read-pipeline: The frozen driver acts on the ToolRunner''s returned NotStarted reason for refused admission (NativeRunDriver.kt:156-179), so the codec maps the NotAdmitted read result as SR-019 states.', '1c25e89f9ef5686059065ef1d8408ee7e4d9e657e9d4e8a6eca5ea3b456785a5', 'active', NULL, 964);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-AS-3-2', 1, 'pre', 'local', NULL, NULL, 'read-pipeline: The codec feature renders expected read outcomes into ToolOutcome content and cannot change lifecycle accounting.', '9a4a3bb092cd962c1768f5e55da6f3127970faa026d1d2fc1e622db671bba6b4', 'active', NULL, 965);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-AS-4-0', 1, 'pre', 'local', NULL, NULL, 'read-pipeline: IntelliJ JUnit 5 test fixtures for a Java project with editors, libraries, generated and excluded roots, dumb mode and a test reference query executor are available through the IntelliJ Platform Gradle test framework configuration; the design may change plugin-core/build.gradle.kts for this and must keep tests discoverable as @Test methods.', 'e437609b9f0d282bd23cdfaadffde95d03d9456f73360635746a447c1a813b90', 'active', NULL, 966);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-AS-5-0', 1, 'pre', 'local', NULL, NULL, 'read-pipeline: Name and file indexes throw IndexNotReadyException in dumb mode (FileBasedIndexImpl).', '024a983f5bfb052ee10c22d0f0fee2533d717a271a1f54fb8eb563ac685ac6a3', 'active', NULL, 967);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-AS-5-1', 1, 'pre', 'local', NULL, NULL, 'read-pipeline: Reference search executors that are not dumb-aware block until smart mode when called without read access (QueryExecutorBase.java:57-66), so SR-016 requires calls inside the read computation.', '6d9451d8490293ef9948b5ad6186ad30b9b85122e4e802e524c642f246f06457', 'active', NULL, 968);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-AS-5-2', 1, 'pre', 'local', NULL, NULL, 'read-pipeline: Dumb-mode entry runs a write action (DumbServiceImpl.kt:335-342), and a write action cancels a running non-blocking read computation, which reruns only when its constraints hold again (NonBlockingReadActionImpl.java:639-641,808-814).', 'ca922a8ba49df1b75e0cc8a3eaa47940ff8213b481edb2b17719320326bd8e75', 'active', NULL, 969);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-AS-5-3', 1, 'pre', 'local', NULL, NULL, 'read-pipeline: The platform exposes no partial-result signal for reference search; completeness is only complete or more results.', '04f84999c3e29e78eb9fda0bf91ea1ee0314ac3929391f4d8f8bc62777a02946', 'active', NULL, 970);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-AS-6-0', 1, 'pre', 'local', NULL, NULL, 'read-pipeline: Only the document modification stamp changes on unsaved edits; the view provider stamp stays at the last committed stamp.', '582db29aae10eb8e9004c9cb4e13f0b20e8c0e72921f95a0bf51d4b825769b6c', 'active', NULL, 971);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-AS-6-1', 1, 'pre', 'local', NULL, NULL, 'read-pipeline: The PSI modification count changes on committed physical PSI changes and on dumb-mode entry and exit, not on uncommitted edits.', '07c3e1a7c6a883020f0aecb5f70d0ab7d121ea7507006a468c6271fe77744c02', 'active', NULL, 972);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-AS-7-0', 1, 'pre', 'local', NULL, NULL, 'read-pipeline: Normalizations of product bounds: limit 1–100 with default 50 for find_references; 300 lines and 24 KiB for get_symbol_info source with SOURCE_TOO_LARGE above it; 1,000 UTF-16 units for text queries; LINE_EXCEEDS_BYTE_CAP as the explicit error for a start line above 24 KiB (product ''smaller read or explicit unsupported error'').', 'ffe1f3b8874ca2b0aa3df986489ed5bd818ed1ff355ee6cf92cf3a7c12595a45', 'active', NULL, 973);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-AS-8-0', 1, 'pre', 'local', NULL, NULL, 'read-pipeline: Normalizations of product terms: SR-025 range, signature, owner and containing-declaration definitions; SR-006 catalog declaration kinds; SR-003 line model and defaults; SR-004 path rendering and check order; SR-010 match and excerpt rule and skipped-file count; SR-020 READ_FAILED category rule; SR-026 failure precedence; SR-001 query validation; SR-004 canonical root comparison; SR-009 reference range, line and kind; SR-010 document offsets and match column; SR-025 parameter type text, array dimensions and compact constructors; SR-012 entry kinds.', '461f776c869b48cd715fcbd2963c46a78edb1bf316e472a83f13ae47b8aff2bf', 'active', NULL, 974);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-AS-9-0', 1, 'pre', 'local', NULL, NULL, 'read-pipeline: Normalizations of scope: generated sources are omitted from find_file, unrestricted search_symbols and search_text directory scans, and included and marked in find_references so reference sets stay complete; handle reuse for the same element (SR-011) keeps one live handle per element in the registry.', '952077bf1a03c6fb0429688d3a57c5ae13053fb02b5463b971c89d3259546816', 'active', NULL, 975);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-AS-10-0', 1, 'pre', 'local', NULL, NULL, 'read-pipeline: The product rule ''reports partial search/index readiness separately'' is satisfied by fail-closed INDEX_NOT_READY and TOO_MANY_RESULTS outcomes, because the platform gives no partial-result signal.', '1d2266858faac292689a1bdb1b7d9401e11ce3fc474e311c925ab6880f77b7d7', 'active', NULL, 976);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-AS-11-0', 1, 'pre', 'local', NULL, NULL, 'read-pipeline: The PSI modification count also changes for document and VFS changes to project-content files whose PSI is not loaded (PsiDocumentManagerBase.java:1149,1314; PsiVFSListener.java:139-148), so SR-017 staleness covers find_file and search_text over unloaded files.', '3b835607d3cdeeb589ab44fca11ea758d7823a403e23cea1f358efff8df45d8e', 'active', NULL, 977);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-0-0', 1, 'pre', 'local', NULL, NULL, 'read-pipeline: read_file takes a path, an optional 1-based start line (default 1) and an optional 1-based inclusive end line (default start plus 99).', '16c8b96712c724e73c11d4f5b4a9e2376b9360f0fd1ea465a78a836acd6b1808', 'active', NULL, 978);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-0-1', 1, 'pre', 'local', NULL, NULL, 'read-pipeline: An end before start, or a span above 300 lines, is an argument rejection.', '3499dae3defc3992d1b204169801f768bf0b6287b6d436ace3c23b3786f23be5', 'active', NULL, 979);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-0-2', 1, 'invariant', 'local', NULL, NULL, 'read-pipeline: Lines are the lines of the current document text with LF terminators; a final LF does not start another line, and an empty document has zero lines.', 'f9229168488e46f2707ba4e378c30c597c74c5f5d2e8a913e2b69314930f42da', 'active', NULL, 980);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-0-3', 1, 'post', 'local', NULL, NULL, 'read-pipeline: The range is clipped at end of file and the actual range is returned.', '03d1eade0d29c67c69426330b348bbb3e57560e06d241125a181d5bf6520754d', 'active', NULL, 981);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-0-4', 1, 'outcome', 'local', NULL, NULL, 'read-pipeline: A start line after the last line, including any start in an empty document, returns RANGE_OUT_OF_BOUNDS with the line count.', '263bb3c557b5a9afacf3bfb48911e4005e69e3c492f3bb44f79366ed2216b70b', 'active', NULL, 982);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-0-5', 1, 'invariant', 'local', NULL, NULL, 'read-pipeline: The 24 KiB cap counts the UTF-8 bytes of the returned lines including their LF terminators.', 'c25b4f029e0a3b34ca7af5bf95101817d1619ced2bcb3eb1dbf6d6c8a8d5bd18', 'active', NULL, 983);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-0-6', 1, 'outcome', 'local', NULL, NULL, 'read-pipeline: When the cap cuts the range, the result holds the largest whole-line prefix, its actual range and a truncated flag.', '88830468c269b0d3c4d5bc930471d6c2d6f3a9141b4f645971aa4aed6b256fd5', 'active', NULL, 984);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-0-7', 1, 'outcome', 'local', NULL, NULL, 'read-pipeline: When the start line alone exceeds 24 KiB, the result is LINE_EXCEEDS_BYTE_CAP with that line''s byte size.', 'e221adfefe62d92a10dfec603e8c2e1589f573e8d65a1c73bd59a16119447a5e', 'active', NULL, 985);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-0-8', 1, 'outcome', 'local', NULL, NULL, 'read-pipeline: A binary file, or a file the platform does not load as text content, returns UNSUPPORTED_FILE.', '3e788daf8ea8e411fca06363ee9fe5007ecc4bed56d1a7a40deff97dc40e18d9', 'active', NULL, 986);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-0-9', 1, 'post', 'local', NULL, NULL, 'read-pipeline: A successful read returns a new read handle (SR-014) on every call; read handles are never reused.', '84d488a4322e032a7c0151be40af3a2116c3eb43b781c62cc7a3b2afda55a37d', 'active', NULL, 987);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-1-0', 1, 'pre', 'local', NULL, NULL, 'read-pipeline: A path argument is relative to the project base directory or absolute.', '7671f9e443c49fd2730d1fe82164aee780788bae18701afd4e7dd1f9774c45cb', 'active', NULL, 988);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-1-1', 1, 'pre', 'local', NULL, NULL, 'read-pipeline: The adapter normalizes it (removes ''.'' and ''..'' segments, resolves symbolic links) before any check.', '35f8651ea1188fd438b66a2fccf13510f076c5b1cceeb3f713e87aa7bbaa7190', 'active', NULL, 989);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-1-2', 1, 'invariant', 'local', NULL, NULL, 'read-pipeline: Project content roots, library source roots, excluded roots and the project base directory are compared in the same canonical form, with symbolic links resolved.', 'c281e592c903533eaf9a99a16f7783d9d02a6ec8a74f7fc8f62a36f5494b1f58', 'active', NULL, 990);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-1-3', 1, 'outcome', 'local', NULL, NULL, 'read-pipeline: The first matching check wins, in this order: (1) the normalized path is not under a project content root or an attached library source root, decided by its nearest existing ancestor, returns OUTSIDE_PROJECT; a file in a library class root (compiled classes) is OUTSIDE_PROJECT; (2) the path is under an excluded root returns EXCLUDED_PATH; (3) no file or directory exists returns FILE_NOT_FOUND; (4) a directory where a file is required returns NOT_A_FILE.', 'fc852051494f749a0406f479a7794b619301f81342db970d518d00990e5dff57', 'active', NULL, 991);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-1-4', 1, 'post', 'local', NULL, NULL, 'read-pipeline: A returned path is rendered with ''/'' separators relative to the canonical project base directory when the file is under it, and otherwise as the platform file URL (for example a jar:// URL for a library source entry); both forms are accepted as path input.', '4dea40b3535e543b9eb9e99c64c489d81801186493b2c2148d93b7fdd697a355', 'active', NULL, 992);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-1-5', 1, 'invariant', 'local', NULL, NULL, 'read-pipeline: Library files are read-only evidence.', '68f232ecc5e63cb7ebdf2ca241e8118d9d7e53ec0c75d8b5c477e30538cc1daf', 'active', NULL, 993);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-2-0', 1, 'pre', 'local', NULL, NULL, 'read-pipeline: find_file takes a query and a scope.', '26cff2fdd11a7e0841d71b726c3d3844dadf5cc0db69c1ff94c82c51e7486bf1', 'active', NULL, 994);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-2-1', 1, 'pre', 'local', NULL, NULL, 'read-pipeline: The query is an exact case-sensitive file name, or a relative path of one or more whole trailing path segments ending in a file name, matched case-sensitively (''a/B.java'' matches ''…/a/B.java'' and not ''…/xa/B.java'').', 'febdaf1800d53117e17ead00aa4a21dbebe3d3b15e15ad5c67a95912ce919cf8', 'active', NULL, 995);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-2-2', 1, 'invariant', 'local', NULL, NULL, 'read-pipeline: Scope PROJECT (default) covers non-excluded project content except generated sources.', '25772f1b5148fec2bfe9f684f99e7e5633d43b14c1eacd980c1423c734551413', 'active', NULL, 996);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-2-3', 1, 'invariant', 'local', NULL, NULL, 'read-pipeline: Scope LIBRARIES covers PROJECT content plus attached library sources.', '665df8f7ae46400e35d9fe0b528632ae4c0831f8e2d8b6dba2ea3410dcf0a646', 'active', NULL, 997);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-2-4', 1, 'decision', 'local', NULL, NULL, 'read-pipeline: A generated source is a file for which any GeneratedSourcesFilter reports generated.', '9f51599ab6c9da2c5df29fe14e4c5869616ef335a2d850bf57d07ac6617f061c', 'active', NULL, 998);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-2-5', 1, 'post', 'local', NULL, NULL, 'read-pipeline: Each result carries its rendered path (SR-004) and origin PROJECT or LIBRARY.', '3a48cf75d796c253bc160b9a29c966d7fd37c688f0d2e94bc37f5b4fdc0b8703', 'active', NULL, 999);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-2-6', 1, 'post', 'local', NULL, NULL, 'read-pipeline: Results are ordered by rendered path.', 'b1a0110814d64b44395694e7334fa85369e7114e51bd6781bda5d6ea843321fe', 'active', NULL, 1000);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-2-7', 1, 'outcome', 'local', NULL, NULL, 'read-pipeline: Paged collection applies the result collection cap (SR-002): more results than the cap returns TOO_MANY_RESULTS with a narrowing hint and no page.', '069709f02f62f102dcc1626d55fdda7df091a91a3d5fff603b88ba8b63e43fc0', 'active', NULL, 1001);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-3-0', 1, 'invariant', 'local', NULL, NULL, 'read-pipeline: Current editor content is authoritative.', '2602efa0c0c365bc476b280f3612f79a1b955d746fecbaf3ac60ad298e4a1624', 'active', NULL, 1002);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-3-1', 1, 'invariant', 'interaction', NULL, NULL, 'read-pipeline: Every operation computes its result inside one read computation that runs only when all documents are committed (the platform documents-committed constraint), so every returned text and range comes from the current document including unsaved changes, and every PSI range matches the reported document version.', 'fc20949288f6ccdd051d99a17006be2d1081ca78b1a939d3041a690e7b15fa3c', 'active', NULL, 1003);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-3-2', 1, 'decision', 'local', NULL, NULL, 'read-pipeline: The document version is the document modification stamp.', '8d2c88ffdd607641707ef313c6d70fe93e5d49a1d4e42c33952c3cc25b4a94fb', 'active', NULL, 1004);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-3-3', 1, 'invariant', 'local', NULL, NULL, 'read-pipeline: Two calls with equal arguments, with no project change and no registry disposal between them and with every input handle and page token still live, return equal outcomes, except for the identifiers of newly issued read handles and page tokens.', '8e61fa11c56bba06ac51a98c419d96b52400744cd5232a66338549f7d7e0b6b7', 'active', NULL, 1005);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-4-0', 1, 'invariant', 'local', NULL, NULL, 'read-pipeline: Index-backed operations (find_file, search_symbols, get_symbol_info, find_references, search_text) run their read computation under the platform smart-mode constraint, and every index-backed platform call, including reference search, runs inside that read computation and never outside read access.', '5f7466b1adbd77b725bd4a147cdb23f323054f9eef3d3e9b418ae6923eaaa852', 'active', NULL, 1006);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-4-1', 1, 'invariant', 'interaction', NULL, NULL, 'read-pipeline: The total wait for smart mode, including restarts after dumb mode begins during the computation, is bounded by the index wait bound: an injected duration with production value 30 seconds.', '69ede0f738e90d9c7d506aac68a6ba2155509d36d6880e6c41f35402f2dd5978', 'active', NULL, 1007);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-4-2', 1, 'decision', 'local', NULL, NULL, 'read-pipeline: DumbService.waitForSmartMode(long) is not used.', '315456bf054567d1f05d50381c5c90ebfb45e811599c2e3e5011f33b70f20a91', 'active', NULL, 1008);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-4-3', 1, 'outcome', 'interaction', NULL, NULL, 'read-pipeline: At the bound the operation returns INDEX_NOT_READY with a retry hint and no partial result.', '7d6c8e22f48049606583654b790d5047050f0c9c2b2f9ff401415c61062655e8', 'active', NULL, 1009);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-4-4', 1, 'outcome', 'interaction', NULL, NULL, 'read-pipeline: An IndexNotReadyException that escapes the computation also returns INDEX_NOT_READY with no partial result.', 'c142920324ced9b982bf39e3532482f344daa8c4c7fa41b307de448a651e7397', 'active', NULL, 1010);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-4-5', 1, 'invariant', 'interaction', NULL, NULL, 'read-pipeline: A write action that cancels a read computation restarts it; time spent in these restarts does not count toward the index wait bound and has no bound, and only cancellation (SR-019) ends it. read_file and get_file_outline do not wait for indexing.', 'e712d32f638b0cf7b5c09c1cc6f396f7c496cc0ae7a0c9bf8aab5ad925d2ebd0', 'active', NULL, 1011);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-4-6', 1, 'outcome', 'local', NULL, NULL, 'read-pipeline: A closed, disposed or not-yet-initialized project returns PROJECT_UNAVAILABLE.', 'b9f060f72dd16a8a58e02f7b69cbe5785be15e706b9fe16e25e6b1bff7ee0b8d', 'active', NULL, 1012);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-4-7', 1, 'invariant', 'local', NULL, NULL, 'read-pipeline: No operation returns an empty success because indexes were unavailable.', '2cb26301b9625cdfe81e1c91d49bf31603c6274b7ace109000eb10f9e9e7dc64', 'active', NULL, 1013);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-5-0', 1, 'invariant', 'local', NULL, NULL, 'read-pipeline: Each read is one admitted executable call.', 'ce6f181a1e6d07b9d51462b88bc015ab7c114d856e1d1e8012ff45d6c604c5e8', 'active', NULL, 1014);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-5-1', 1, 'invariant', 'local', NULL, NULL, 'read-pipeline: The read executor receives the CallAdmission and RunCancellation that the ToolRunner passes and calls CallAdmission.execute exactly once off the EDT.', '5e91ea876c3058b2f7be82b89ea25d567fd79566af8f875d2d89ee69ac7f2513', 'active', NULL, 1015);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-5-2', 1, 'outcome', 'interaction', NULL, NULL, 'read-pipeline: When execute returns Limited or Rejected, the Effect did not run, no IntelliJ access happens, and the read executor returns a typed NotAdmitted result that carries the admission result; the codec feature maps it to ToolOutcome.NotStarted with RUN_LIMIT_NOT_STARTED for Limited and CANCELLED_NOT_STARTED for Rejected.', 'acc63c7de1ac7bf6534af34b9b23881d0f7a045cf0a3d99d6a607313604b1ee2', 'active', NULL, 1016);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-5-3', 1, 'invariant', 'interaction', NULL, NULL, 'read-pipeline: The Effect contains the index wait and the whole read computation, and it returns or throws only after the platform read computation for this call has terminated.', 'f567e32c8e1c90594a421cb92fd6bd3a17f5df6ad00c72c33c8703439d507e19', 'active', NULL, 1017);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-5-4', 1, 'invariant', 'local', NULL, NULL, 'read-pipeline: The run cancellation token cancels the wait and the computation; the listener registered on RunCancellation only requests that cancellation and never blocks, because RunSession runs listeners under its monitor, possibly on the EDT.', '07ed32171f52031b2abd67757d37a5fdb041ea270440b2f2a0a5537845d53652', 'active', NULL, 1018);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-5-5', 1, 'outcome', 'interaction', NULL, NULL, 'read-pipeline: On cancellation, including content close, the Effect throws java.util.concurrent.CancellationException, so the lifecycle records FAILED_AFTER_START and the frozen driver records ToolOutcome.FailedAfterStart with no touched paths; no success value, partial result, handle or page token is produced.', 'de007c4eb35c025f2a4ea9c5b9387553ed6bfb66e873a7ae55867e95532e04c3', 'active', NULL, 1019);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-5-6', 1, 'invariant', 'interaction', NULL, NULL, 'read-pipeline: Handles and page tokens are registered only after the computation completed without cancellation.', '62db61e26253d4f2a373c8bf056cbf6ab7932b8af0898b4a4690c980aa525040', 'active', NULL, 1020);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-5-7', 1, 'outcome', 'interaction', NULL, NULL, 'read-pipeline: If the registry is disposed when they are registered, it registers nothing and the Effect throws java.util.concurrent.CancellationException with the same lifecycle and driver results.', '1c1cc1dfc5bcf66aa9a230dcf21e0b685c8eb3cb332328e0ffc212e58d1f6f47', 'active', NULL, 1021);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-5-8', 1, 'post', 'local', NULL, NULL, 'read-pipeline: Expected read outcomes return normally.', 'ce40e46328305876153df4b3d9b6402a9e31b8db792b14d9139dbbd151048974', 'active', NULL, 1022);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-5-9', 1, 'invariant', 'local', NULL, NULL, 'read-pipeline: The read never waits for the EDT while it holds read access.', 'eaee7121fa9307b9b178639bfedb22f1099583d83fe8cdb76fda0a9506bbb08a', 'active', NULL, 1023);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-6-0', 1, 'outcome', 'local', NULL, NULL, 'read-pipeline: An unexpected platform failure during a read returns READ_FAILED with a category from a closed set and no source text, arguments or stack content.', 'f0b18a69d704c33623aab7d980d6008986fb02dedc57441efc79f80d2f6dadf8', 'active', NULL, 1024);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-6-1', 1, 'decision', 'local', NULL, NULL, 'read-pipeline: The first matching rule gives the category: PATH_RESOLUTION for a failure in the SR-004 path checks; INDEX_QUERY for a failure inside a name index, file name index or reference search call; DOCUMENT_READ for a failure while reading document text or line offsets; PSI_READ for every other failure at SR-026 steps 2 to 9.', 'ffc03fc359d58215ab35761b4a50264cddb4a9c329ff0e81ad7346e3305b65ca', 'active', NULL, 1025);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-6-2', 1, 'invariant', 'local', NULL, NULL, 'read-pipeline: A violated domain invariant throws.', '246fa150608fd0ec686ba935fa5dc903fdfbd7d987602a5d9bf0b51e87618c67', 'active', NULL, 1026);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-6-3', 1, 'invariant', 'local', NULL, NULL, 'read-pipeline: Logs record only operation, category and counts.', '1bcaa0f36d3bfba3e46e26e6e4226789999011b5d2318077541f94f03e8971d7', 'active', NULL, 1027);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-6-4', 1, 'invariant', 'local', NULL, NULL, 'read-pipeline: Every outcome that carries a hint (STALE_HANDLE, STALE_PAGE, INDEX_NOT_READY, TOO_MANY_RESULTS, SOURCE_TOO_LARGE, LINE_EXCEEDS_BYTE_CAP, UNSUPPORTED_LANGUAGE, READ_FAILED) names only catalog tools.', 'c553325cb752e3db499dc7481512a67453f5f45cb8686dc794dcc18338209e35', 'active', NULL, 1028);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-6-5', 1, 'decision', 'local', NULL, NULL, 'read-pipeline: The UNSUPPORTED_LANGUAGE hint names read_file and search_text as the labeled fallback.', '779d0a22a93c8f59e0882b64a207ab7234ea5ccaa53836d3771bf567344d4527', 'active', NULL, 1029);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-7-0', 1, 'invariant', 'local', NULL, NULL, 'read-pipeline: Failure precedence for one admitted read, first applicable wins: (1) cancellation, including a disposed registry at registration (SR-019); (2) PROJECT_UNAVAILABLE; (3) registry lookup of an input symbol handle, including an owner type handle (STALE_HANDLE), then of an input page token, including a different operation or argument set (STALE_PAGE), then the PSI modification count of the token (STALE_PAGE), all without waiting for indexing; (4) path outcomes in SR-004 order; (5) file-type and language outcomes (UNSUPPORTED_FILE, UNSUPPORTED_LANGUAGE), without waiting for indexing; (6) INDEX_NOT_READY for index-backed operations; (7) re-resolution STALE_HANDLE (SR-013), then NOT_A_TYPE (SR-006), then PSI modification count STALE_PAGE inside the operation computation (SR-017); (8) TOO_MANY_RESULTS; (9) the operation result, including RANGE_OUT_OF_BOUNDS, LINE_EXCEEDS_BYTE_CAP and SOURCE_TOO_LARGE.', '0ec3e49bfd18789d0551cebd77f554fe85aa062475204c6840186d14324e51bc', 'active', NULL, 1030);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-7-1', 1, 'outcome', 'local', NULL, NULL, 'read-pipeline: An unexpected platform failure at steps 2 to 9 returns READ_FAILED.', 'aa98fa796f32f4d7233ceec687850669484c4da2e8047415b7ce1c27e39cf831', 'active', NULL, 1031);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-7-2', 1, 'pre', 'local', NULL, NULL, 'read-pipeline: Argument rejection (SR-001) happens before admission.', '1250776f617c78870eb90cb0dfa789f255f58a73babb58aed6e1271a54d717cc', 'active', NULL, 1032);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-7-3', 1, 'decision', 'local', NULL, NULL, 'read-pipeline: The read pipeline has all nine steps from this slice on; steps whose outcomes belong to later slices (STALE_HANDLE and NOT_A_TYPE in read-symbols, STALE_PAGE in read-text-search) stay in their positions and are bound by those slices without a change to this order.', '12e7ae7a9b36772a42414179e4b64ac6b47cb97f88d4326cd801ece834c9738e', 'active', NULL, 1033);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-8-0', 1, 'invariant', 'local', NULL, NULL, 'read-pipeline: Read adapters hold every IntelliJ type that reads use, including smart pointers inside registry payloads; read domain values hold none (SR-021).', '86170ceacbbce9b328faa0c4545cf6fa595f19873e54df6f7db847877d47f080', 'active', NULL, 1034);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-REQ-8-1', 1, 'invariant', 'local', NULL, NULL, 'read-pipeline: The read execution path uses no MCP, HTTP or runtime reflection.', '4a5fdfbeaa73be0a49b6c14d08a637f9370650675e2cca80f91de5bc0d12de28', 'active', NULL, 1035);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-ACC-0', 1, 'outcome', 'local', 'read-pipeline: In a fixture project with lines of exactly 10 KiB plus LF, read_file lines 1–5 of that file, a range across end of file, a start after end of file, an empty file, a file whose first line exceeds 24 KiB, a binary file, a text file above the content-loading limit, a directory, a missing project path, a missing path under an excluded directory, an existing excluded file, a missing and an existing absolute path outside the project, a symlink inside the project that points outside it, a non-Java text file by absolute path, a library source file by its jar URL and a class file in a library class root; separately, in a fixture whose project base directory is reached through a symbolic link, read_file a project file by its relative path and by its absolute path through the link.', 'Lines 1–5 return exactly lines 1–2 with actual range 1–2 and truncated set; the end-of-file range is clipped to the last line; the empty file and the late start return RANGE_OUT_OF_BOUNDS with their line counts; LINE_EXCEEDS_BYTE_CAP is returned with the first line''s exact byte size; the binary file and the file above the content-loading limit return UNSUPPORTED_FILE; the directory returns NOT_A_FILE; the missing project path returns FILE_NOT_FOUND; both excluded cases return EXCLUDED_PATH; both outside paths, the symlink and the class file return OUTSIDE_PROJECT; the text file and the library source succeed; the symlinked-base reads succeed and render the same ''/''-separated path relative to the project base directory; successful reads return read handles with the observed version.', 'read-pipeline: acceptance 0: when In a fixture project with lines of exactly 10 KiB plus LF, read_file lines 1–5 of that file, a range across end of file, a start after end of file, an empty file, a file whose first line exceeds 24 KiB, a binary file, a text file above the content-loading limit, a directory, a missing project path, a missing path under an excluded directory, an existing excluded file, a missing and an existing absolute path outside the project, a symlink inside the project that points outside it, a non-Java text file by absolute path, a library source file by its jar URL and a class file in a library class root; separately, in a fixture whose project base directory is reached through a symbolic link, read_file a project file by its relative path and by its absolute path through the link. then Lines 1–5 return exactly lines 1–2 with actual range 1–2 and truncated set; the end-of-file range is clipped to the last line; the empty file and the late start return RANGE_OUT_OF_BOUNDS with their line counts; LINE_EXCEEDS_BYTE_CAP is returned with the first line''s exact byte size; the binary file and the file above the content-loading limit return UNSUPPORTED_FILE; the directory returns NOT_A_FILE; the missing project path returns FILE_NOT_FOUND; both excluded cases return EXCLUDED_PATH; both outside paths, the symlink and the class file return OUTSIDE_PROJECT; the text file and the library source succeed; the symlinked-base reads succeed and render the same ''/''-separated path relative to the project base directory; successful reads return read handles with the observed version.', 'ed4f63d6ae85f4edad69f80dded2ee66129fd9d35fb147d2fe7bc0a1ade8efc4', 'active', NULL, 1036);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-ACC-1', 1, 'outcome', 'local', 'read-pipeline: Run find_file for a name present in source, generated source, an excluded directory and a library source, with PROJECT and LIBRARIES scopes; also run find_file for ''a/B.java'' where ''a/B.java'' and ''xa/B.java'' exist. With the result collection cap injected as 2, run find_file for a name present in 3 project files.', 'PROJECT returns only the source file with origin PROJECT; LIBRARIES returns exactly the source file and the library file with their origins; the source file renders as its ''/''-separated path relative to the project base directory and the library file as its jar URL; generated and excluded files are absent; paths are ordered; the suffix query returns only ''a/B.java''. The capped query returns TOO_MANY_RESULTS with a narrowing hint and no page.', 'read-pipeline: acceptance 1: when Run find_file for a name present in source, generated source, an excluded directory and a library source, with PROJECT and LIBRARIES scopes; also run find_file for ''a/B.java'' where ''a/B.java'' and ''xa/B.java'' exist. With the result collection cap injected as 2, run find_file for a name present in 3 project files. then PROJECT returns only the source file with origin PROJECT; LIBRARIES returns exactly the source file and the library file with their origins; the source file renders as its ''/''-separated path relative to the project base directory and the library file as its jar URL; generated and excluded files are absent; paths are ordered; the suffix query returns only ''a/B.java''. The capped query returns TOO_MANY_RESULTS with a narrowing hint and no page.', '9dd5734724b77a0432f7263f972e1e68cc07b10ea6581ed0c5c6eaa742a4cbd1', 'active', NULL, 1038);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-ACC-2', 1, 'outcome', 'interaction', 'read-pipeline: With the index wait bound injected as 200 ms, enter dumb mode through the platform dumb-mode test utility and call find_file; call find_file again and leave dumb mode before the bound; call read_file during dumb mode.', 'The first call returns INDEX_NOT_READY with a catalog-only retry hint and no results after at least 200 ms; the second call returns results after indexing ends; read_file succeeds without waiting.', 'read-pipeline: acceptance 2: when With the index wait bound injected as 200 ms, enter dumb mode through the platform dumb-mode test utility and call find_file; call find_file again and leave dumb mode before the bound; call read_file during dumb mode. then The first call returns INDEX_NOT_READY with a catalog-only retry hint and no results after at least 200 ms; the second call returns results after indexing ends; read_file succeeds without waiting.', '26a2e09513cae3f1c7f690d802399803e49c82f501bdc9cbb26c341f0888d0d8', 'active', NULL, 1040);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-ACC-3', 1, 'outcome', 'interaction', 'read-pipeline: Stop the run from the EDT while a find_file read waits for indexing, and while a find_file computation blocks inside a test GeneratedSourcesFilter on a latch that the test releases only after Stop; separately close the content while such a read blocks; separately dispose the registry, without cancelling the run, while a find_file computation with limit 1 over two matching files blocks on such a latch; separately run a read whose CallAdmission returns Limited and one whose CallAdmission returns Rejected.', 'Each cancelled or disposed call''s admission status is FAILED_AFTER_START, the Effect threw java.util.concurrent.CancellationException, and the driver records ToolOutcome.FailedAfterStart with no touched paths; Stop returned before the latch was released; the Effect returned only after the blocked computation terminated; no page token was registered; admission counted each read once; the read computation thread and the Effect calling thread were not the EDT; the Limited and Rejected reads return NotAdmitted with their admission result and made no IntelliJ call.', 'read-pipeline: acceptance 3: when Stop the run from the EDT while a find_file read waits for indexing, and while a find_file computation blocks inside a test GeneratedSourcesFilter on a latch that the test releases only after Stop; separately close the content while such a read blocks; separately dispose the registry, without cancelling the run, while a find_file computation with limit 1 over two matching files blocks on such a latch; separately run a read whose CallAdmission returns Limited and one whose CallAdmission returns Rejected. then Each cancelled or disposed call''s admission status is FAILED_AFTER_START, the Effect threw java.util.concurrent.CancellationException, and the driver records ToolOutcome.FailedAfterStart with no touched paths; Stop returned before the latch was released; the Effect returned only after the blocked computation terminated; no page token was registered; admission counted each read once; the read computation thread and the Effect calling thread were not the EDT; the Limited and Rejected reads return NotAdmitted with their admission result and made no IntelliJ call.', '090b76aca598ce4e18fac7d01a882027906fdf7c7bb70f932fcaed03e9128bca', 'active', NULL, 1042);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-ACC-4', 1, 'outcome', 'local', 'read-pipeline: Make a read adapter throw an unexpected platform exception containing source text and a path, once during path checks, once inside a test GeneratedSourcesFilter during find_file and once while reading document lines for read_file.', 'The operation returns READ_FAILED with categories PATH_RESOLUTION, PSI_READ and DOCUMENT_READ in that order; the outcome and captured log contain no source text, argument or stack content.', 'read-pipeline: acceptance 4: when Make a read adapter throw an unexpected platform exception containing source text and a path, once during path checks, once inside a test GeneratedSourcesFilter during find_file and once while reading document lines for read_file. then The operation returns READ_FAILED with categories PATH_RESOLUTION, PSI_READ and DOCUMENT_READ in that order; the outcome and captured log contain no source text, argument or stack content.', 'd995492eb54fa86a8aa1d924312a2b93e8c106731c4c0253d98b9a8238d1409f', 'active', NULL, 1044);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-ACC-5', 1, 'outcome', 'local', 'read-pipeline: In dumb mode with the index wait bound injected as 200 ms, call read_file with a missing path under an excluded directory and on a binary file; with a closed project, call read_file and find_file; make path resolution throw an unexpected platform exception.', 'read_file returns EXCLUDED_PATH and UNSUPPORTED_FILE before 200 ms elapse; both closed-project calls return PROJECT_UNAVAILABLE; the injected failure returns READ_FAILED with category PATH_RESOLUTION.', 'read-pipeline: acceptance 5: when In dumb mode with the index wait bound injected as 200 ms, call read_file with a missing path under an excluded directory and on a binary file; with a closed project, call read_file and find_file; make path resolution throw an unexpected platform exception. then read_file returns EXCLUDED_PATH and UNSUPPORTED_FILE before 200 ms elapse; both closed-project calls return PROJECT_UNAVAILABLE; the injected failure returns READ_FAILED with category PATH_RESOLUTION.', '959a0dec986013759ed75a466a4014e97ce2a574969283225307b48ee27667dd', 'active', NULL, 1046);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-ACC-6', 1, 'outcome', 'local', 'read-pipeline: Open a text file in an editor and change one line without saving, then call read_file for that line and find_file for the file name, then call read_file for that line and find_file for the file name once more without a change.', 'read_file returns the unsaved line text and the unsaved document version; find_file returns the file; the repeated read_file outcome equals the first except for a distinct read handle identifier, and the repeated find_file outcome equals the first.', 'read-pipeline: acceptance 6: when Open a text file in an editor and change one line without saving, then call read_file for that line and find_file for the file name, then call read_file for that line and find_file for the file name once more without a change. then read_file returns the unsaved line text and the unsaved document version; find_file returns the file; the repeated read_file outcome equals the first except for a distinct read handle identifier, and the repeated find_file outcome equals the first.', 'a38dcb43f1490df922b167e526a554861c45dfc700ac0023779a6999107ec699', 'active', NULL, 1048);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-ACC-7', 1, 'outcome', 'local', 'read-pipeline: Discover every class file in the compiled read adapter packages and read the constant pool of each.', 'At least one class is found, and the set contains every read adapter class that the design declares; no constant pool references an MCP SDK type, java/net/http/, com/sun/net/httpserver/ or java/lang/reflect/.', 'read-pipeline: acceptance 7: when Discover every class file in the compiled read adapter packages and read the constant pool of each. then At least one class is found, and the set contains every read adapter class that the design declares; no constant pool references an MCP SDK type, java/net/http/, com/sun/net/httpserver/ or java/lang/reflect/.', '195593213fe19e535193927b6997193bb2b138e97817c562e2292faa87dd9263', 'active', NULL, 1050);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-DEC-index_wait', 1, 'decision', 'local', NULL, NULL, 'read-pipeline: decision index_wait = 30_SECONDS_THEN_INDEX_NOT_READY', '3fd0dcc101cdd32aceefbdc5b8641c25ad0d7cb3ba2744f03197fb59f7f3a2d0', 'active', NULL, 1061);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-DEC-read_cancellation', 1, 'decision', 'local', NULL, NULL, 'read-pipeline: decision read_cancellation = WAIT_AND_READ_IN_ADMITTED_EFFECT_THROW_FAILED_AFTER_START', '1b5fd3e4cc2021e3b9eccb14a89fb70d1033bad0a138a22fed8356e0605ce378', 'active', NULL, 1065);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-DEC-libraries_scope', 1, 'decision', 'local', NULL, NULL, 'read-pipeline: decision libraries_scope = PROJECT_PLUS_ATTACHED_LIBRARY_SOURCES', '40408992cbad249962f995e9638c39478129c2d8998f9cc6c454fbde29f15018', 'active', NULL, 1066);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-DEC-admission_refusal', 1, 'decision', 'local', NULL, NULL, 'read-pipeline: decision admission_refusal = TYPED_NOT_ADMITTED_RESULT_CODEC_MAPS_TO_NOT_STARTED', '20ff3d8579d9d5d3664a1d79908bd006b2c73d5b9aa6ea9e2a05c354cc2a629d', 'active', NULL, 1074);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-DEC-disposed_registry_issue', 1, 'decision', 'local', NULL, NULL, 'read-pipeline: decision disposed_registry_issue = EFFECT_THROWS_CANCELLATION_FAILED_AFTER_START', 'a6a05c2dddc1a45aa95ba22609cc458bf48fdcd6808cbbdad0f1ebed13dbae23', 'active', NULL, 1075);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-DEC-write_action_restarts', 1, 'decision', 'local', NULL, NULL, 'read-pipeline: decision write_action_restarts = UNBOUNDED_UNTIL_STOP', '98f7d54fef5b0dca30cd6fa21283d75a2c3ce7ad1fee8cbe7633466e2b351874', 'active', NULL, 1077);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-DEC-cancellation_throwable', 1, 'decision', 'local', NULL, NULL, 'read-pipeline: decision cancellation_throwable = JAVA_UTIL_CONCURRENT_CANCELLATION_EXCEPTION', 'f2ba641e511ee119f39899be5b1489484c618bbf232e32b7176315b3c6c4e315', 'active', NULL, 1078);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-DEC-read_handle_issue', 1, 'decision', 'local', NULL, NULL, 'read-pipeline: decision read_handle_issue = NEW_READ_HANDLE_PER_CALL', '2c8e1923e22d7294d48b308544029ee71c17fb7dd91c0ce5f4df7e1f7c934ad9', 'active', NULL, 1081);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-OPM-0', 1, 'outcome', 'interaction', 'read-pipeline: any read in ADMISSION when CallAdmission returns Limited or Rejected', 'Effect does not run; no IntelliJ access; the read executor returns NotAdmitted with the admission result; the codec maps it to NotStarted; next unchanged', 'read-pipeline: operation matrix 0: any read in ADMISSION when CallAdmission returns Limited or Rejected -> Effect does not run; no IntelliJ access; the read executor returns NotAdmitted with the admission result; the codec maps it to NotStarted; next phase unchanged', 'c26c3267b7bc6125fbdd3428dd844c69ccf7e3f649acf1224926b10a353b789c', 'active', NULL, 1082);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-OPM-1', 1, 'outcome', 'local', 'read-pipeline: find_file|search_symbols|get_symbol_info|find_references|search_text in SMART', 'Execute within scope, collection cap and page bounds; Complete or More(token); next SMART', 'read-pipeline: operation matrix 1: find_file|search_symbols|get_symbol_info|find_references|search_text in SMART -> Execute within scope, collection cap and page bounds; Complete or More(token); next phase SMART', '474d80e7b0de7f65242dbfd537e6d6fb4f6ec6bd349e7a2f8e7cf6bdc9a12949', 'active', NULL, 1083);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-OPM-2', 1, 'outcome', 'local', 'read-pipeline: find_file|search_symbols|find_references|get_file_outline|search_text in SMART when more results than the collection cap', 'TOO_MANY_RESULTS with narrowing hint; no page; next SMART', 'read-pipeline: operation matrix 2: find_file|search_symbols|find_references|get_file_outline|search_text in SMART when more results than the collection cap -> TOO_MANY_RESULTS with narrowing hint; no page; next phase SMART', 'a68b8105789b89f18ff354c0aeddc3395df8867837af5eb06b97a5ac27ae9975', 'active', NULL, 1084);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-OPM-3', 1, 'outcome', 'local', 'read-pipeline: find_file|search_symbols|get_symbol_info|find_references|search_text in INDEXING when registry, path and language checks pass and indexing ends within the index wait bound', 'Wait, then execute; next SMART', 'read-pipeline: operation matrix 3: find_file|search_symbols|get_symbol_info|find_references|search_text in INDEXING when registry, path and language checks pass and indexing ends within the index wait bound -> Wait, then execute; next phase SMART', '232ad46f8b63b60872e6640ffdd0a9a0d362da41c279c5741596202c32717c14', 'active', NULL, 1085);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-OPM-4', 1, 'outcome', 'interaction', 'read-pipeline: find_file|search_symbols|get_symbol_info|find_references|search_text in INDEXING when registry, path and language checks pass and indexing continues past the index wait bound', 'INDEX_NOT_READY with retry hint; no results; next INDEXING', 'read-pipeline: operation matrix 4: find_file|search_symbols|get_symbol_info|find_references|search_text in INDEXING when registry, path and language checks pass and indexing continues past the index wait bound -> INDEX_NOT_READY with retry hint; no results; next phase INDEXING', '945d0ae8d6eb3a2811e2cf28ec6ffab6e5e57b5a0dda5b00889bdee475b72399', 'active', NULL, 1086);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-OPM-5', 1, 'outcome', 'local', 'read-pipeline: any index-backed read in SMART when dumb mode begins during execution and ends within the remaining bound', 'Computation restarts; complete result; next SMART', 'read-pipeline: operation matrix 5: any index-backed read in SMART when dumb mode begins during execution and ends within the remaining bound -> Computation restarts; complete result; next phase SMART', '94e911541ebb0c79241a71958186d3a6986318800b4e2ed9b395da1b8cb05031', 'active', NULL, 1087);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-OPM-6', 1, 'outcome', 'interaction', 'read-pipeline: any index-backed read in SMART when dumb mode begins during execution and outlasts the bound', 'INDEX_NOT_READY; no partial results; next INDEXING', 'read-pipeline: operation matrix 6: any index-backed read in SMART when dumb mode begins during execution and outlasts the bound -> INDEX_NOT_READY; no partial results; next phase INDEXING', '9cbb9e25ff41bd225b78713fcd3f84b4b286019cb394b05b63e3b17545256a70', 'active', NULL, 1088);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-OPM-7', 1, 'outcome', 'local', 'read-pipeline: read_file|get_file_outline in SMART|INDEXING', 'Execute without waiting for indexing; next unchanged', 'read-pipeline: operation matrix 7: read_file|get_file_outline in SMART|INDEXING -> Execute without waiting for indexing; next phase unchanged', '224aaafcfb40082c6c34e4d704c6adcd81f722cad9da50d0f0a51db9d5be10ba', 'active', NULL, 1089);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-OPM-8', 1, 'outcome', 'local', 'read-pipeline: any read with a path argument in SMART|INDEXING when path check fails', 'First SR-004 outcome in order; no wait for indexing; next unchanged', 'read-pipeline: operation matrix 8: any read with a path argument in SMART|INDEXING when path check fails -> First SR-004 outcome in order; no wait for indexing; next phase unchanged', 'e98590e5c80a9242ef13831c0d702c5a05b83a3432c3bb37c1ab92cdcf1ada99', 'active', NULL, 1090);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-OPM-9', 1, 'outcome', 'interaction', 'read-pipeline: any read in STOPPING', 'Cancel waiting or running read; Effect throws after the computation terminates; FAILED_AFTER_START; nothing registered; next STOPPING', 'read-pipeline: operation matrix 9: any read in STOPPING -> Cancel waiting or running read; Effect throws after the computation terminates; FAILED_AFTER_START; nothing registered; next phase STOPPING', '8df3917a9e8154915f19ad83b45feda1161bbc386117794ae101567b9710c501', 'active', NULL, 1091);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-OPM-10', 1, 'outcome', 'interaction', 'read-pipeline: any read in SMART|INDEXING when a write action cancels the read computation', 'Computation restarts after constraints hold; restart time has no bound and does not count toward the index wait bound; Stop or content close ends it; next unchanged', 'read-pipeline: operation matrix 10: any read in SMART|INDEXING when a write action cancels the read computation -> Computation restarts after constraints hold; restart time has no bound and does not count toward the index wait bound; Stop or content close ends it; next phase unchanged', 'b19912c05b12bf90c1f30ea8e05f3fe22610b08fa320e1e89a7ab4cd651e957e', 'active', NULL, 1092);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-OPM-11', 1, 'outcome', 'interaction', 'read-pipeline: any read in SMART|INDEXING when content closes, or the registry is disposed, during the read', 'Cancellation wins, or the disposed registry registers nothing; Effect throws java.util.concurrent.CancellationException after the computation terminates; FAILED_AFTER_START; next REGISTRY_DISPOSED', 'read-pipeline: operation matrix 11: any read in SMART|INDEXING when content closes, or the registry is disposed, during the read -> Cancellation wins, or the disposed registry registers nothing; Effect throws java.util.concurrent.CancellationException after the computation terminates; FAILED_AFTER_START; next phase REGISTRY_DISPOSED', 'c9a6b808cf93d0607456d45b1c5366017de0565494b2d622513ffcf32791532a', 'active', NULL, 1093);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-OPM-12', 1, 'outcome', 'local', 'read-pipeline: any read in PROJECT_UNAVAILABLE when run not cancelled', 'PROJECT_UNAVAILABLE; next PROJECT_UNAVAILABLE', 'read-pipeline: operation matrix 12: any read in PROJECT_UNAVAILABLE when run not cancelled -> PROJECT_UNAVAILABLE; next phase PROJECT_UNAVAILABLE', '82bbd1a04052bf017faad4e342fb0e7bfc711d46183fb951883d6779f9366708', 'active', NULL, 1094);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-OPM-13', 1, 'outcome', 'local', 'read-pipeline: any read in PROJECT_UNAVAILABLE when run cancelled', 'Cancellation wins; Effect throws; next PROJECT_UNAVAILABLE', 'read-pipeline: operation matrix 13: any read in PROJECT_UNAVAILABLE when run cancelled -> Cancellation wins; Effect throws; next phase PROJECT_UNAVAILABLE', 'e0f741bb09d1812452887eb34b337c624a37117cad76ab06c0452e784ff36523', 'active', NULL, 1095);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-NBM-0', 1, 'outcome', 'local', 'read-pipeline: read adapter platform results with nullable platform return such as missing document, file or resolved element', 'Named outcome (FILE_NOT_FOUND, UNSUPPORTED_FILE, STALE_HANDLE); never a null in a domain value', 'read-pipeline: null boundary 0: read adapter platform results with nullable platform return such as missing document, file or resolved element -> Named outcome (FILE_NOT_FOUND, UNSUPPORTED_FILE, STALE_HANDLE); never a null in a domain value', 'b8c3469f3d6841ebf76791ad60a298db1061650cd5bc2f0be92f4cb5fb7bc7a6', 'active', NULL, 1096);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-NBM-1', 1, 'outcome', 'local', 'read-pipeline: read execution with admission capability or cancellation token', 'NullPointerException before admission or platform access', 'read-pipeline: null boundary 1: read execution with admission capability or cancellation token -> NullPointerException before admission or platform access', '18c46ae180986121d5bfda7be1251a9c8eebffc6e86d402817fb6267eae7b973', 'active', NULL, 1097);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-TSA-0', 1, 'invariant', 'local', NULL, NULL, 'read-pipeline: type safety 0: prevent Partial lines, a silently empty read, invented ranges, an over-span request, or binary bytes returned as text; by type/API: Argument factory applies line defaults and rejects end before start and spans above 300; operation-local read_file outcome variants for success with actual range, range out of bounds, line cap exceeded and unsupported file; runtime obligation: Adapter computes line offsets on the document text observed in one read action', '16d0664f378c4096bcae1a5aaaff2c47fe66cd305c9c9a2c4f7538ebd549a735', 'active', NULL, 1098);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-TSA-1', 1, 'invariant', 'local', NULL, NULL, 'read-pipeline: type safety 1: prevent A read of an arbitrary filesystem path or of an excluded tree; by type/API: Validated path argument plus a sealed path-resolution outcome whose variants follow the fixed check order; resolved file identity is constructible only by the adapter; runtime obligation: Adapter normalizes the path, resolves symbolic links and checks project file index membership under read access in the SR-004 order', '4da94a5f7d7cda68ba9870c6356763069a8436d4758165c8fbc2c6bca4800295', 'active', NULL, 1100);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-TSA-2', 1, 'invariant', 'local', NULL, NULL, 'read-pipeline: type safety 2: prevent Excluded or generated files in PROJECT results, or library files without an explicit scope; by type/API: Scope enum with PROJECT default; result entries carry rendered path (SR-004) and origin; runtime obligation: Adapter filters excluded and generated files with platform file index checks', 'f5c870bf2256186a253806febad9cd8188e3c90cd05d478d5d51d9fcde927687', 'active', NULL, 1102);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-TSA-3', 1, 'invariant', 'interaction', NULL, NULL, 'read-pipeline: type safety 3: prevent A result built from disk text while an editor holds unsaved changes, or PSI ranges from an uncommitted document; by type/API: Result values carry the document version they were computed against; runtime obligation: Adapter runs every read computation under the documents-committed constraint', '542a59b19704b5d00af73776be9e2e64ab858fd4b0ec51b64789ec63a3d3e30f', 'active', NULL, 1104);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-TSA-4', 1, 'invariant', 'interaction', NULL, NULL, 'read-pipeline: type safety 4: prevent An authoritative empty result during indexing, or an unbounded wait; by type/API: Sealed readiness outcome shared by index-backed operations; the index wait bound is a validated injected positive duration; runtime obligation: Adapter runs index-backed platform calls only inside the smart-mode read computation with the bound and maps index-not-ready failures', '7a89934074d10569535078ce50bf7314d916e1dc7541aed1c99adae3a49c49b7', 'active', NULL, 1106);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-TSA-5', 1, 'invariant', 'interaction', NULL, NULL, 'read-pipeline: type safety 5: prevent A read that bypasses admission, blocks the EDT, returns while its computation still runs, registers handles after Stop or disposal, reports partial results after Stop, or returns a completed result when admission refused; by type/API: Read executor accepts only a CallAdmission and a RunCancellation and returns a sealed read execution result with operation-local outcome variants and a NotAdmitted variant carrying the admission result; handle registration happens after the computation result is obtained; runtime obligation: Adapter links the run cancellation token to the platform read computation with a nonblocking listener, awaits termination on the Effect thread, and throws java.util.concurrent.CancellationException on cancellation or a disposed registry', '615dc14c5005df6a1f91ebdf641e3da6877775c51b8f41dd4b20b2d3bc27c4a9', 'active', NULL, 1108);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-TSA-6', 1, 'invariant', 'local', NULL, NULL, 'read-pipeline: type safety 6: prevent A swallowed platform exception reported as success, or source text in a log; by type/API: READ_FAILED variant with a closed category enum and no free-form content; hint values are built only from catalog tool names; invariant checks throw; runtime obligation: Adapter catches platform exceptions at the boundary and maps them with the SR-020 category rule', '6a16620e039b7e73f5ce87e2a008bcd11ea63f8541c157ab19171446631da800', 'active', NULL, 1110);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-TSA-7', 1, 'invariant', 'local', NULL, NULL, 'read-pipeline: type safety 7: prevent Two possible outcomes for one call, or a wait for indexing before a registry or path failure; by type/API: One adapter pipeline with ordered stages, each returning a sealed stage outcome that short-circuits; runtime obligation: Adapter maps unexpected platform failures to READ_FAILED at each stage', 'c05fed1c9f6281cb2a8e987bd068f08a39759ba8d6ae6943cacfadb857a894b7', 'active', NULL, 1112);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-TSA-8', 1, 'invariant', 'local', NULL, NULL, 'read-pipeline: type safety 8: prevent An IntelliJ type in a read domain value, or an MCP, HTTP or reflection hop on the read path; by type/API: Separate read domain and adapter packages; the registry is generic over the adapter payload type; runtime obligation: Architecture test over compiled read adapter classes', 'd5cd75a5f1c00e0ffc2bf610c1ad51d2bbdaaa2de59ed0176f3a4c69e17006ef', 'active', NULL, 1114);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-STG-0-entry', 1, 'pre', 'local', NULL, NULL, 'read-pipeline: stage 0 entry binds SR-003, SR-004, EV-SOURCE', 'c35fb63a4a2a86e681eddc0ac93be22aab9891dac4bd863908525d6976533aa2', 'active', NULL, 1116);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-STG-0-exit', 1, 'post', 'local', NULL, NULL, 'read-pipeline: stage 0 exit binds SR-003, SR-004, SR-005, SR-015, SR-016, SR-019, SR-020, SR-026, SR-028, EV-STRUCTURE, EV-SPEC-REVIEW', 'f1e1fcec61cb760bdf646df476aaf12a951c8381449629675091ea38956b4f49', 'active', NULL, 1117);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-STG-0-outcome', 1, 'post', 'local', NULL, NULL, 'read-pipeline: stage 0 outcome: SPEC_VALID for the exact normalized feature basis; no design or implementation claim', 'b8cea9a325e6bca0be639bca8210a9624983abbeb0d560e7d04446ed09e7c6ba', 'active', NULL, 1118);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-STG-1-entry', 1, 'pre', 'local', NULL, NULL, 'read-pipeline: stage 1 entry binds SR-003, SR-004, EV-STRUCTURE, EV-SPEC-REVIEW', 'd29407ae4afc1c65353c7bfd16756920deb74985de5310622e80d4d3fd5a3430', 'active', NULL, 1119);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-STG-1-exit', 1, 'post', 'local', NULL, NULL, 'read-pipeline: stage 1 exit binds SR-003, SR-004, SR-005, SR-015, SR-016, SR-019, SR-020, SR-026, SR-028, EV-DESIGN-SOURCE, EV-DESIGN-COMPILE, EV-DESIGN-REVIEW, EV-RECEIPT', '780ffc39785ad0aa766718feb946df8c03cbe367c3ee504303a99f4fb7e304ef', 'active', NULL, 1120);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-STG-1-outcome', 1, 'post', 'local', NULL, NULL, 'read-pipeline: stage 1 outcome: DESIGN_VALID; implementation surface frozen', 'e8c8a1a1928a93ccbe30c6b9cc917b0cffb5ee9ceeead706fc2f382bfb952661', 'active', NULL, 1121);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-STG-2-entry', 1, 'pre', 'local', NULL, NULL, 'read-pipeline: stage 2 entry binds SR-003, SR-004, EV-DESIGN-SOURCE, EV-DESIGN-COMPILE, EV-DESIGN-REVIEW, EV-RECEIPT', '9cf5accfcc0dca78204f0f120b11e14a50fefc698a99cea674ba93bce60cce8e', 'active', NULL, 1122);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-STG-2-exit', 1, 'post', 'local', NULL, NULL, 'read-pipeline: stage 2 exit binds SR-003, SR-004, SR-005, SR-015, SR-016, SR-019, SR-020, SR-026, SR-028, EV-IDE, EV-BUILD, EV-IMPLEMENTATION-REVIEW', 'd48db92eaf393b61d6520a6baeabeef2a14c8ee80caa7d9c1d3ec1671b926df0', 'active', NULL, 1123);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('RPIPE-STG-2-outcome', 1, 'post', 'local', NULL, NULL, 'read-pipeline: stage 2 outcome: CAP-READ-PIPELINE closure qualified', '2d08b632fed82a7b8385b3c63e65f692c77c1ac34fa49ea6fc612d89b0ee4a1a', 'active', NULL, 1124);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-I2-3', 2, 'invariant', 'local', NULL, NULL, 'No model or catalog change mid-run.', 'e183d544a41fb79284afab8fdf5bd090aa8fc4835a7809877097c6de574b137e', 'active', 'not modeled: I2: out of this plan (idle-only model/catalog change, milestone 5)', 1194);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-I2-4', 2, 'invariant', 'local', NULL, NULL, 'New Session or model change happens only at idle and invalidates every old handle.', '6f7dfd361c772935d41233a723b864ef2c57444c6b9224cd6afabb3cf670ae4c', 'active', 'not modeled: I2: out of this plan (idle-only model/catalog change, milestone 5)', 1195);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-I6-3', 2, 'pre', 'local', NULL, NULL, 'File identity, document version, symbol identity, writability and cancellation are rechecked at the final mutation boundary for every touched target.', '55fc47cfde13198031c78a4672e8e939de5ed034138600f0db0cdec4c2bdabd9', 'active', 'not modeled: I6: out of scope (mutations, milestone 3A)', 1196);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-I6-5', 2, 'invariant', 'local', NULL, NULL, 'No raw offsets survive an intervening document change.', '603c3b864c36e388121e6bdc88f6c6cedfa17cbe3aaa7800521337d9616fe99f', 'active', 'not modeled: I6: out of scope (mutations, milestone 3A)', 1197);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-H-2', 2, 'invariant', 'local', NULL, NULL, 'Eviction is safe because mutations fail on an evicted handle.', '9f6a10ab6055124cae62d5994e38b6d99db695384b9a18b1bc82ce2e392f02cd', 'active', 'not modeled: handle eviction vs mutation: mutations out of scope (milestone 3A)', 1198);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-H-3', 2, 'invariant', 'local', NULL, NULL, 'File edits invalidate handles for affected files.', '0b01d68e89d9aa93b9ace547caa400a9336fa32bb15f48d851cf02ce27828691', 'active', 'not modeled: handle invalidation on edits: mutations out of scope (milestone 3A)', 1199);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-H-5', 2, 'invariant', 'local', NULL, NULL, 'Validate pointers under read access.', '7632206fd7b73e20bc551db27ea4e1eef23f98dbccf4235c5465750e4b813776', 'active', 'not modeled: pointer validation under read access: local to the read kernel; not a multi-owner model state', 1200);
INSERT INTO clause(id, rev, kind, scope, trigger, outcome, text, text_sha256, status, reason, event_id) VALUES ('PRD-RT-4', 2, 'pre', 'local', NULL, NULL, 'Roll back provisional UI before retry.', 'd4006305595531f211984858d66f652abe14b8bb9a6bd917c9b5b91e5d644fbf', 'active', 'not modeled: provisional rollback before retry: not modeled in agent_coarse; local test in breakdown plan', 1201);
